WITH payload AS (SELECT $archive_payload$[{"id":"c2735910-6cd2-5eea-b4ae-805abcac2077","document_type":"judgment","category":"judicial","subcategory":"general","title":"جرائم معلوماتية -قذف -نشر اسم امرأة على احدى القنوات الفضائية -تهديد امرأة باملالحقة -ابتزاز -إقامة عالقة محرمة -التعزير بالسجن واجللد -سقوط حد القذف بتنازل املدعي","document_number":"34251708","case_number":"32164059","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/26","year":"1434","subject":"جرائم معلوماتية -قذف -نشر اسم امرأة على احدى القنوات الفضائية -تهديد امرأة باملالحقة -ابتزاز -إقامة عالقة محرمة -التعزير بالسجن واجللد -سقوط حد القذف بتنازل املدعي","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34251708 :‬تاريخه ‪1434/06/26 :‬هـ‬\n                    ‫رقم الدعوى ‪32164059 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34308499‬تاريخه‪1434/08/29 :‬هـ‬\n\n\n  ‫جرائــم معلوماتيــة ‪ -‬قــذف ‪ -‬نشــر اســم امــرأة علــى احــدى القنــوات‬\n  ‫الفضائيــة ‪ -‬تهديــد امــرأة باملالحقــة ‪ -‬ابتــزاز ‪ -‬إقامــة عالقــة محرمــة‬\n  ‫‪ -‬التعزيــر بالســجن واجللــد ‪ -‬ســقوط حــد القــذف بتنــازل املدعــي‬\n                                                                     ‫اخلــاص ‪.‬‬\n\n\n\n\n  ‫قــال ابــن قدامــة رحمــه اهلل يف املغنــي (‪ ( : )217/8‬يعتبــر إلقامــة حــد‬\n  ‫القــذف أن يطالــب املقــذوف ألنــه حقــه فال يســتوفى قبل طلبه كســائر‬\n  ‫حقوقــه كمــا أنــه يســقط بالعفــو كالقصــاص و يفــارق ســائر حــدود‬\n  ‫فإنــه ال يعتبــر إلقامتهــا طلــب اســتيفائها ) ‪ .‬و أنظــر إعــام املوقعــن‬\n                                                                   ‫(‪.)108/1‬‬\n\n\n\n\n  ‫توجيــه اإلتهــام للمدعــى عليــه بانتهــاك عــرض (امــرأة ) بنشــر اســمها‬\n  ‫علــى إحــدى القنــوات الفضائيــة وقذفهــا وتهديهــا إذا لــم تتجــاوب معــه‬\n  ‫و إقامــة عالقــة محرمــه معهــا و تهديهــا باملالحقــة ‪ -‬حيــث تقدمــت‬\n  ‫املــرأة املتضــرره بشــكوى لــدى هيئــة األمــر باملعــروف و النهــي عــن‬\n  ‫املنكــر تتضمــن تعرضهــا لذلــك مــن قبــل املدعــى عليــه ‪ -‬مت القبــض‬\n  ‫علــى املدعــى عليــه و بتفتيــش جوالــه عثــر علــى رقــم املشــتكيه و أرقــام‬\n\n                                                                                    ‫‪150‬‬\n\f      ‫فتيــات أخريــات ‪ -‬كمــا عثــر علــى الرســائل املذكــورة ‪ -‬طلــب املدعــي‬\n      ‫العــام إثبــات مــا أســند للمدعــى عليــه و احلكــم عليــه بحــد القــذف و‬\n      ‫الســجن و الغرامــة اســتناد ًا للمادتــن (‪3‬و‪ )6‬مــن نظــام مكافحــة اجلرائــم‬\n      ‫املعلوماتيــة مصــادرة االجهــزة املســتخدمة يف ارتــكاب اجلرميــة اســتناد ًا‬\n      ‫للمــادة (‪ )13‬مــن نظــام مكافحــة اجلرائــم املعلوماتيــة و تعزيــرة إلقامــة‬\n      ‫العالقــة احملرمــة ‪ -‬علم ـ ًا بــأن احلــق اخلــاص انتهــى بالتنــازل ‪ -‬أنكــر‬\n      ‫املدعــى عليــه مــا نســب إليــه ‪ -‬قــرر املدعــي العــام أن بينتــه اقــرار املدعــى‬\n      ‫عليــه حتقيق ـ َا و ملــف تقريــر األحــوال األمنيــة و محضــر هيئــة األمــر‬\n      ‫باملعــروف والنهــي عــن املنكــر ‪ -‬جــرى الرجــوع إلــى هــذه احملاضــر‬\n      ‫‪ -‬جــرى عرضــه علــى املدعــى عليــه فأنكرهــا ماعــدا رســالة واحــدة‬\n      ‫‪ -‬طلــب القاضــي مــن املدعــي العــام احضــار معــدي محضــر القبــض‬\n      ‫و محضــر املشــاهدة ‪ -‬لــم يســتطع املدعــي العــام إحضارهــم ‪ -‬صــدر‬\n      ‫احلكــم بعــدم ثبــوت مــا أســند للمدعــى عليــه و توجــه التهمــة القويــة عليــه‬\n      ‫بذلــك و تعزيــره لقــاء ذلــك بســجنه ســنة كاملــة وجلــده ســتمائة جلــدة‬\n      ‫مفرقــة علــى اثنــي عشــرة دفعــة وصــرف النظــر عــن طلــب املدعــي العــام‬\n      ‫بتطبيــق املــواد (‪3‬و‪6‬و‪ )13‬مــن نظــام مكافحــة اجلرائــم املعلوماتيــة ورد‬\n      ‫دعــوى املدعــي العــام بطلــب إقامــة حــد القــذف ‪ -‬صــدق احلكــم مــن‬\n                                                                ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة‬\n      ‫بســكاكا وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائية بسكاكا ‪/‬املكلف برقم ‪ 32164059‬وتاريخ ‪1432/05/08‬‬                   ‫ّ‬\n\n‫‪151‬‬\n\f‫ه ـ املقيــدة باحملكمــة برقــم ‪ 32511254‬وتاريــخ ‪ 1432/05/08‬ه ـ‬\n‫ففــي يــوم الســبت املوافــق‪ 1433/05/15‬ه ـ افتتحت اجللســة الســاعة ‪30‬‬\n‫‪ 08 :‬وفيهــا قــدم املدعــي العــام دعــوى عامــة ضــد املدعــى عليــه ســعودي‬\n‫ا فيهــا أنــه بتاريــخ ‪1432/3/10‬ه ـ‬  ‫بالســجل املدنــي رقــم ‪ .................‬قائـ ً‬\n‫وردت لهيئــة األمــر باملعــروف والنهــي عــن املنكــر شــكوى مــن إحــدى‬\n‫الفتيــات تدعــي تعرضهــا للتهديــد مــن قبــل املذكــور أعــاه بفضحهــا‬\n‫عنــد أهلهــا ويف مقــر عملهــا إذا لــم تســتجب ملطالبــة وذلــك بالــرد علــى‬\n‫مكاملاتــه وانــه قذفهــا بقولــه (قحبــة) وإرســال اســمها ألحــد القنــوات‬\n‫لفضحهــا فتــم القبــض عليــه وبتفيــش جوالــه عثــر علــى عالقــات محرمــة‬\n‫مــع مجموعــة مــن الفتيــات ومــن ضمنهــا رقــم الفتــاة املشــتكية وبســماع‬\n‫أقــوال املتهــم واســتجوابه أقــر بإرســال الرســائل للمجنــي عليهــا وذلــك‬\n‫لقيــام األخيــر بإخبــار زوجتــه بأنــه علــى عالقــة مــع بعــض الفتيــات يف‬\n‫املســتوصف أثنــاء مراجعــة زوجتــه لــه وأنــه حتصــل علــى رقمهــا مــن جوال‬\n‫زوجتــه وغرضــه هــو معرفــة ســبب قيامهــا بذلــك وحــل املوضــوع ودي‬\n‫وورد يف محضــر املشــاهدة جلــوال املجنــي عليهــا املعــد مــن قبــل رجــال‬\n‫هيئــة األمــر باملعــروف والنهــي عــن املنكــر مايلــي ‪ ( /1‬شــويف يابنــت‬\n‫النــاس أنتــي بليتينــي بســالفتك واهلل ثــم واهلل لــو مارديتــي وســمعتي إلــى‬\n‫عنــدي إنــي الخليكــي تعيشــن بدوامــة مشــاكل مــا أنتــي بقدهــا لســى‬\n‫فينــي صبــر عــن جيتــي لبيتــك إن مــا رديتــي تــراي أجــي ومعــي رســايلك‬\n‫علــى جــوال أهلــي نصيحــة خلينــا نحــل املوضــوع)‪ ( -2 .‬مهــي مشــكلة‬\n‫يحــرم حــرام لتأصــل مواصيــل منتــي قدهــا صبــرك حتطــن بالنــاس‬\n‫ماهــو فيهــم) ‪ (/3.‬حبيــت أقولــك إن الربــع إلــي كذبتــي عليهــم رقمهــم‬\n‫مــن أمــس معــي وأنــا إلــى جالــس أراســلك مــن الصبــح وكل رســائلك‬\n\n\n                                                                                         ‫‪152‬‬\n\f      ‫عنــدي إذا مارديتــي وربــي ألوصــل اجلــوال لتركــي )‪ ( /4 .‬جالســة‬\n      ‫تغازلــن ياقحبــة)‪(/5 .‬اســمك منــور ع التلفزيــون)‪( /6.‬وش رأيــك أوقــف‬\n      ‫أبــوك وأنتــي معــه) ‪( /7‬دليــت البيــت إلــى عنــده شــجرة وجمــس هاليومني‬\n      ‫اتقهــوى عنــد أبــوك)‪ .‬وبســؤاله عــن ارســاله لفظــة (قحبــة ) قــال إنــه‬\n      ‫اليــدري هــل أرســلها أم ال ألنــه كان يف حالــة صعبــة وانتهــى التحقيــق‬\n      ‫بتوجيــه االتهــام لــ‪ /‬بانتهــاك عــرض (‪ )....‬بنشــر اســمها علــى احــدى‬\n      ‫القنــوات الفضائيــة وقذفهــا بلفــظ قحبــة وتهديدهــا اذا لــم تتجــاوب معــه‬\n      ‫وإقامــة عالقــة محرمــة معهــا وهــي المتــت لــه بصلــة شــرعية وتهديدهــا‬\n      ‫باملالحقــة وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ويتعــن معــه إحالتــه‬\n      ‫للمحكمــة اجلزئيــة وفقـ ًا لنــص املــادة (‪ )128/126‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة فإننــي أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه باآلتــي ‪-1‬‬\n      ‫حــد القــذف ‪ -2‬الســجن والغرامــة اســتناد ًا للمادتــن الثالثــة والسادســة‬\n      ‫مــن نظــام مكافحــة جرائــم املعلوماتية ‪ -3‬مصادرة األجهزة املســتخدمة‬\n      ‫يف ارتــكاب اجلرميــة اســتناد ًا للمــادة الثالثــة عشــرة مــن نظــام مكافحــة‬\n      ‫جرائــم املعلوماتيــة ‪ -4‬تعزيــره إلقامــة العالقــة احملرمــة علم ـ ًا بــأن احلــق‬\n      ‫اخلــاص انتهــى بالتنــازل هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى‬\n      ‫ا ماذكــره املدعــي العــام يف دعــواه ضــدي غيــر‬       ‫املدعــى عليــه أجــاب قائـ ً‬\n      ‫صحيــح فلــم أقــم بإنتهــاك عــرض فتــاة بنشــر اســمها علــى القنــوات‬\n      ‫الفضائيــة أو أحدهــا ولــم أقذفهــا ولــم أهددهــا ولــم أقيــم عالقــة محرمــة‬\n      ‫ا الصحيــح‬    ‫معهــا هكــذا أجــاب وبعرضهــا علــى املدعــي العــام قــرر قائـ ًَ‬\n      ‫ماذكرتــه وبينتــي عليــه مايلــي ‪ -1‬ماجــاء يف إقــراره املنــوه عنــه واملــدون‬\n      ‫علــى الصفحــة رقــم (‪ )2-1‬مــن ملــف التحقيــق لفــة رقــم () وملــف تقريــر‬\n\n\n‫‪153‬‬\n\f‫األحــوال األمنيــة املوحــد صفــة رقــم (‪ )10-2‬علــى اللفــة رقــم(‪2 )1‬‬\n‫ماتضمنــه محضــر هيئــة األمــر باملعــروف والنهــي عــن املنكــر املنــوه عنــه‬\n‫واملرفــق لفــة رقــم (‪ - 3 )2‬ماتضمنــه محضــر املشــاهدة واملعــد مــن قبــل‬\n‫أعضــاء هيئــة األمــر باملعــروف والنهــي عــن املنكــر املنــوه عنــه واملرفــق‬\n‫لفــة رقــم (‪ )21/20‬اطلــب الرجــوع إليهــا هكــذا قــرر وبالرجــوع إليهــا‬\n‫وجدتهــا مطابقــة ملــا ذكــره املدعــي العــام ومبواجهــة املدعــى عليــه بهــا‬\n‫ا مــاورد بأقوالــي املشــار إليهــا صحيحــة واصــادق عليهــا وليــس‬      ‫قــرر قائـ ً‬\n‫فيهــا مايــدل علــى مــا اتهمنــي بــه املدعــي العــام وأمــا مــاورد يف محضــر‬\n‫القبــض لهيئــة األمــر باملعــروف والنهــي عــن املنكــر غيــر صحيــح وأمــا‬\n‫ماتضمنــه محضــر مشــاهدة جــوال الفتــاة غيــر صحيــح وال عالقــة لــي‬\n‫بذلــك وامــا ماتضمنــه محضــر املشــاهدة بجوالــي فغيــر صحيــح إال‬\n‫الرســالة العاشــرة التــي نصهــا ‪ ( :‬دليــت البيــت إللــي عنــده شــجر وجمــس‬\n‫هاليومــن اتقهــوى عنــد ابوكــي ) هكــذا قــرر وبعــرض ذلــك علــى‬\n‫ا الصحيــح ماذكرتــه هكــذا قــرر فطلبــت منــه‬         ‫املدعــي العــام قــرر قائـ ً‬\n‫إحضــار معــدي محضــر القبــض ومحضــري املشــاهدة املســتند عليهــا يف‬\n‫دعــواه فاســتعد بذلــك وطلــب مهلــة فأجبتــه لطلبــه ورفعــت اجللســة لذلــك‬\n‫إلى يوم الســبت املوافق ‪1433/6/28‬هـ الســاعة الثانية عشــرة والنصف‬\n‫وبــاهلل التوفيــق ‪ ،‬و يف جلســة أخــرى ففــي يــوم الســبت‬\n‫املوافق‪1433/06/28‬ه ـ افتتحــت اجللســة الســاعة ‪ 12:30:00‬و فيهــا‬\n‫حضــر املدعــي العــام واملدعــى عليــه و فيهــا لــم يحضــر املدعــي العــام‬\n‫معــدي محضــر القبــض ومحضــري املشــاهدة املســتند عليهــا يف دعــواه‬\n‫ا اطلــب إمهالــي‬  ‫حتــى اآلن وبعــرض ذلــك علــى املدعــي العــام قــرر قائ ـ ً‬\n‫مهلــة إلمتكــن مــن إحضارهــم هكــذا قــرر فأجبتــه لطلبــه وقــررت‬\n\n\n                                                                                         ‫‪154‬‬\n\f      ‫إمهالــه مهلــة ثانيــة ورفعــت اجللســة لذلــك إلــى يــوم األحــد املوافــق‬\n      ‫‪1433/08/25‬ه ـ الســاعة احلاديــة عشــرة و النصــف وبــاهلل التوفيــق ‪ ،‬و‬\n      ‫يف جلســة أخــرى ففــي يــوم األحــد املوافــق‪ 1433/08/25‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 11:30:00‬و فيهــا حضــر املدعــي العــام و املدعــى عليــه‬\n      ‫وفيهــا لــم يحضــر املدعــي العــام معــدي محضــر القبــض ومحضــري‬\n      ‫املشــاهدة املســتند عليهــن يف دعــواه حتــى اآلن وبعــرض ذلــك علــى‬\n      ‫ا اطلــب إمهالــي مهلــة إلمتكــن مــن إحضارهــم‬         ‫املدعــي العــام قــرر قائ ـ ً‬\n      ‫هكــذا قــرر فأجبتــه لطلبــه وقــررت إمهالــه مهلــة ثالثــة لذلــك وافهمتــه‬\n      ‫باعتبــاره عاجــز ًا عــن إحضارهــم حــال عــدم حضورهــم ففهــم ذلــك‬\n      ‫ورفعــت اجللســة لذلــك إلــى يــوم األحــد املوافــق ‪1433/11/21‬ه ـ الســاعة‬\n      ‫الثامنــة والنصــف وبــاهلل التوفيــق ‪ ،‬و يف جلســة أخــرى ففــي يــوم األحــد‬\n      ‫املوافــق ‪1433/11/21‬ه ـ افتتحــت اجللســة الســاعة الثامنــة و النصــف و‬\n      ‫فيهــا حضــر املدعــي العــام و لــم يحضــر املدعــي العــام معــدي محضــر‬\n      ‫القبــض ومحضــري املشــاهدة املســتند عليهــا يف دعــواه حتــى اآلن و‬\n      ‫أفهمتــه بإعتبــاره عاجــز ًا عــن إحضــاره و أن لــه ذلــك مــا لــم تقفــل املرافعــة‬\n      ‫ففهــم ذلــك و لــم يحضــر املدعــى عليــه حتــى اآلن رغــم تبلغــه بتوقيعــه يف‬\n      ‫ضبــط اجللســة الســابقة لــذا قــررت الكتابــة ملديــر شــعبة أمــن احملاكــم‬\n      ‫إلحضــاره باخلفــارة خــال وقــت الــدوام الرســمي وبــاهلل التوفيــق ‪ ،‬و يف‬\n      ‫جلســة أخــرى ففــي يــوم الســبت املوافــق ‪ 1434/03/14‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة الثامنــة والنصــف وفيهــا حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه وفيهــا لــم يحضــر املدعــي العــام معــدي محضــر القبــض ومحضــري‬\n      ‫املشــاهدة املســتند عليهــن يف دعــواه حتــى اآلن وقــد كتــب بذلــك خطاب‬\n      ‫الــى رئيــس فــرع هيئــة التحقيــق واالدعاء العام باجلــوف برقم ‪34427767‬‬\n\n\n‫‪155‬‬\n\f‫وتاريخ‪1434/2/20‬ه ـ وأفهمتــه باعتبــاره عاجــزا عــن إحضارهــم وأن لــه‬\n‫إحضارهــم مالــم تقفــل املرافعــة ففهــم ذلــك ورفعــت اجللســة للتأمــل الــى‬\n‫يــوم األحــد املوافق‪1434/6/25‬ه ـ الســاعة العاشــرة والنصــف وبــاهلل‬\n‫التوفيــق ‪ ،‬و يف جلســة أخــرى ففــي يــوم األحــد املوافــق‪ 1434/06/25‬ه ـ‬\n‫افتتحــت اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي العــام‬\n‫واملدعــى عليــه واقفلــت املرافعــة وبعــد ســماع الدعوى واالجابــة واالطالع‬\n‫علــى اوراق املعاملــة والنــكار املدعــى عليــه دعــوى املدعــي العــام ولعــدم‬\n‫وجــود بينــه لــدى املدعــي العــام الدانــة املدعــى عليــه مبــا نســب اليــه‬\n‫والعتبــار املدعــي العــام عاجــزا عــن احضــار معــدي محضــر القبــض‬\n‫واملشــاهدة املســتند عليهمــا يف دعــواه وجلميــع ماتقــدم بــه املدعــي العــام‬\n‫مــن ادلــة وقرائــن والقــرار املدعــى عليــه بصحــة الرســالة العاشــرة الواردة‬\n‫يف محضــر املشــاهدة املتضمنــه مــا نصه(دليــت البيــت اللــي عنــده شــجر‬\n‫وجمــس هاليومــن اتقهــوى عنــد ابــوك) املــدون بضبــط اجللســة االولــى‬\n‫والقــراره بإرســال رســاله لتخويــف الفتــاة املــدون علــى الصفحــة رقــم (‪)3‬‬\n‫مــن دفتــر التحقيــق لفــه (‪ )25‬والقــراره بصحــة اقواله املدونــه ومصادقته‬\n‫عليهــا وذلــك عنــد مواجهتــه بادلــة املدعــي العــام املــدون بضبــط اجللســة‬\n‫االولــى وملــا ورد يف محضــر القبــض املرفــق لفــة (‪ )2‬املتضمــن اقــرار‬\n‫املدعــى عليــه مبتابعتــه الفتــاة وتهديــده لهــا وبالكشــف علــى جهــاز‬\n‫جوالــه املضبــوط تبــن أن لــه عالقــات محرمــة مــع مجموعــة مــن الفتيــات‬\n‫ومــن ضمنهــا فتــاة اعطتــه رقــم الفتــاة املشــتكيه بهــدف التعــرف عليهــا‬\n‫ا‬‫ووجــد بجهــازه رســالة ذكــر فيهــا اســم الفتــاة املشــتكية كام ـ ً‬\n‫مرســلة إلــى أحــد القنــوات الفضائيــة بهــدف فضحهــا وملــا تضمنــه‬\n‫محضــري مشــاهدة جــوال الفتــاة وجــوال املدعــى عليــه املتضمنــن‬\n\n\n                                                                                    ‫‪156‬‬\n\f      ‫رســائل واردة الــى جــوال الفتــاة مــن جــوال املدعــى عليــه وصــادره مــن‬\n      ‫جــوال املدعــى عليــه الــى جوالهــا تتضمــن تهديــد وقــذف ورســاله نصهــا‬\n      ‫(ياســتي كلــن يبــي لنفســه الفايــده جبتلهــا جــوال ايفــون بشــرط تعــرف‬\n      ‫صاحبــي علــى وحــده قالــت ماعنــدي البعديــن ذكرتــك وخذيــت رقمــك‬\n      ‫كنــك لصاحبــي وانــا الــي ابيكــي ) ولعــدم وجــود ســوابق مســجلة علــى‬\n      ‫املدعــى عليــه حســب الئحــة املدعــي العــام وحيــث قــرر اهــل العلــم ان يف‬\n      ‫حــد القــذف حقــا هلل وحقــا للعبــد وان حــق العبــد فيــه هــو الغالــب الن‬\n      ‫املــراد مــن حــد القــذف هــو دفــع عار الزنا عــن املقذوف ويجــوز للمقذوف‬\n      ‫العفــو عنــه قــال ابــن قدامــه رحمــه اهلل (يعتبــر إلقامــة حــد القــذف أن‬\n      ‫يطالــب املقــذوف ألنــه حقــه فــا يســتويف قبــل طلبــه كســائر حقوقــه‬\n      ‫كمــا أنــه يســقط بعفــو كالقصــاص ويفــارق ســائر احلــدود فإنــه اليعتبر‬\n      ‫إلقامتهــا طلــب اســتيفائها ) املغنــي ‪ 217/8‬وانظــر إعــام املوقعــن‬\n      ‫‪ 108/1‬لذلــك كلــه وبنــاء عليــه لــم يثبــت لــدي ادانــة املدعــى عليــه‬\n      ‫املواطــن مبــا نســب اليــه مــن انتهــاك عــرض بنشــر اســمها علــى احــد‬\n      ‫القنــوات الفضائيــة وقذفهــا بلفــظ قحبــه وتهديدهــا اذا لــم تتجــاوب معــه‬\n      ‫واقامــة عالقــه محرمــه معهــا وهــي المتــت بصلــه شــرعية وتهديدهــا‬\n      ‫باملالحقــه وتوجهــت التهمــه القويــه عليــه بذلــك وقــررت تعزيــره لقــاء‬\n      ‫ذلــك بســجنه مــدة ســنة كاملــة تبــدأ اعتبــارا مــن تاريــخ ايقافــه يحتســب‬\n      ‫منهــا ماامضــاه موقوفــا يف ذمــة هــذه القضيــة وجلــدة ســتمائة جلــدة‬\n      ‫مفرقــه علــى إثنــا عشــر دفعــة متســاوية بــن كل دفعــة واخــرى مااليقــل‬\n      ‫عــن عشــرة ايــام وصرفــت النظــر عــن طلــب املدعــي العــام تطبيــق املــواد‬\n      ‫الثالثــة والسادســة والثالثــة عشــر مــن نظام مكافحة اجلرائــم املعلوماتيه‬\n      ‫لعــدم شــموله بهــا وحكمــت بــرد دعــوى املدعــي العــام بحــد القــذف ملــا‬\n\n\n‫‪157‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":150,"source_page_end":157,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e92b49a6369be39da52176d245a0195314facd091a26035bec5a48eefc00b66a","normalized_text_hash":"0789b881a0d9247e39e29a8cdaa4854f6c2da632450b2d35de80fe67e849c7a9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p150-34251708"},{"id":"88868e90-b53c-540d-8040-f36de9f8c39e","document_type":"judgment","category":"judicial","subcategory":"general","title":"جرائم معلوماتية -نشر أخبار وأسرار وصور مبوقع تواصل اجتماعي -تنازل صاحب احلق اخلاص وصغر السن وعدم وجود سوابق أحد موجبات تخفيف العقوبة التعزيرية -تعزير مبصادرة اجلوال والسجن -إغاق حساب الفيس بوك وإتاف الصور.","document_number":"34252636","case_number":"34278231","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/26","year":"1434","subject":"جرائم معلوماتية -نشر أخبار وأسرار وصور مبوقع تواصل اجتماعي -تنازل صاحب احلق اخلاص وصغر السن وعدم وجود سوابق أحد موجبات تخفيف العقوبة التعزيرية -تعزير مبصادرة اجلوال والسجن -إغاق حساب الفيس بوك وإتاف الصور.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34252636 :‬تاريخه‪1434/6/26 :‬هـ‬\n                    ‫رقم الدعوى‪34278231:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n   ‫االستئناف‪ 34291181:‬تاريخه‪1434/8/8 :‬هـ‬\n\n\n‫جرائــم معلوماتيــة ‪ -‬نشــر أخبــار وأســرار وصــور مبوقــع تواصــل‬\n‫اجتماعــي ‪ -‬تنــازل صاحــب احلــق اخلــاص وصغــر الســن وعــدم وجــود‬\n‫ســوابق أحــد موجبــات تخفيــف العقوبــة التعزيريــة ‪ -‬تعزيــر مبصــادرة‬\n    ‫اجلــوال والســجن ‪ -‬إغــاق حســاب الفيــس بــوك وإتــاف الصــور‪.‬‬\n\n\n\n\n                                             ‫‪ -‬مشار له يف تسبيب احلكم ‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن املدعــي العــام علــى املدعى عليها بقيامها بنشــر‬\n‫صــورة فتــاة يف مواقــع التواصــل االجتماعــي وطلــب إثبــات مــا أســند إليها‬\n‫وإيقــاع العقوبــة التعزيريــة عليهــا ومصــادرة جهازهــا اجلــوال والشــريحة‬\n‫وإتالفهــا وإتــاف الصــور التــي قــام والــد الفتــاة املتضــررة بإحضارهــا‬\n‫وإغــاق حســابها علــى الفيســبوك املنشــأ باســم املدعــى عليهــا ‪ ،‬أقــرت‬\n‫املدعــى عليهــا بالتهمــة وقــررت بأنهــا تائبــة ‪ ،‬قــررت احملكمــة احلكــم‬\n‫علــى املدعــى عليهــا بالســجن شــهرا ومصــادرة جهــاز جوالهــا والشــريحة‬\n‫وإتالفهــا وإتــاف الصــور التــي قــام والــد الفتــاة املتضــررة بإحضارهــا‬\n‫تعزيــرا وإغــاق حســابها علــى الفيســبوك وجــرى النطــق باحلكــم‬\n‫بحضــور اخصائيــة اجتماعيــة ‪ ،‬قــررت املدعــى عليهــا القناعــة باحلكــم‬\n\n                                                                                  ‫‪160‬‬\n\f      ‫بينمــا قــرر املدعــى العــام االعتــراض وأفهــم التعليمــات وقــدم الئحتــه‬\n                     ‫االعتراضيــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة املســاعد برقــم ‪34278231‬‬\n      ‫وتاريــخ ‪ 1434/06/17‬ه ـ املقيــدة باحملكمــة برقــم ‪341463050‬‬\n      ‫وتاريــخ ‪ 1434/06/17‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/06/21‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 12 : 45‬وفيهــا حضــر املدعــي العــام ‪..........‬‬\n      ‫ســعودي اجلنســية املكلــف برقــم ‪..........‬يف ‪1433/10/16‬ه ـ وادعــى‬\n      ‫قائــا أدعــي علــى ‪.......... /‬البالغــة مــن العمــر (‪ )18‬عــام ســعودية اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪..........‬لقيامهــا بتاريــخ ‪1434/4/23‬ه ـ‬\n      ‫بنشــر صــورة الفتــاة ‪..........‬يف مواقــع التواصــل االجتماعــي أطلــب إثبــات‬\n      ‫مــا أســند إليهــا واحلكــم عليهــا باآلتــي ‪ -1 :‬بعقوبــة تعزيريــة لقــاء قيامهــا‬\n      ‫بنشــر صــورة فتــاة يف مواقــع التواصــل االجتماعــي‪ -2 .‬مبصــادرة جهــاز‬\n      ‫جوالهــا مــن نــوع ‪ ....‬واحلامــل للرقــم املصنعــي ( ‪ )..........‬والشــريحة‬\n      ‫واتــاف الصــور التــي قــام بإحضارهــا والــد الفتــاة املتضــررة والعائــدة‬\n      ‫لهــا تعزيــرا‪ -3 .‬بإغــاق صفحــة الفيــس بــوك املنشــأة بإســم‪..........‬‬\n      ‫تعزيــرا هــذه دعــواي وبســؤال املدعــى عليهــا صادقــت علــى مــا جــاء‬\n      ‫يف الدعــوى وأنهــا تائبــة إلــى اهلل هكــذا أجابــت فبنــاء علــى مــا تقــدم‬\n      ‫وإلقــرار املدعــى عليهــا مبــا جــاء يف الدعــوى وحلرمــة مــا أقدمــت عليــه‬\n      ‫ولعــدم ســوابقها وحلداثــة ســنها ولتنــازل املدعيــة يف احلــق اخلــاص وألن‬\n\n‫‪161‬‬\n\f‫التعزيــر باملــال مقــرر شــرعا وهــو مذهــب املالكيــة واحلنابلــة واختــاره‬\n‫شــيخ اإلســام وابــن القيــم لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى‬\n‫عليهــا مبــا جــاء يف الدعــوى وحكمــت عليهــا مبــا يلــي ‪ -1 :‬بالســجن‬\n‫شــهرا ابتــداء مــن تاريــخ إيقافهــا‪ -2 .‬مبصــادرة جهــاز جوالهــا مــن نــوع‬\n‫‪ ....‬واحلامــل للرقــم املصنعــي رقــم ‪ ..........‬والشــريحة وإتــاف الصــور‬\n‫التــي قــام بإحضارهــا والــد الفتــاة املتضــررة والعائــدة لهــا تعزيــرا‪.‬‬\n‫‪ -3‬بإغــاق صفحتهــا يف الفيــس بــوك املنشــأة بإســم ‪ ...........‬وبعــرض‬\n‫احلكــم علــى املدعــي العــام قــرر االعتــراض بالئحــة وجــرى تســليمه‬\n‫نســخة مــن القــرار الشــرعي وأفهــم بنظــام االســتئناف وقــررت املدعــى‬\n‫عليهــا القناعــة وكانــت اجللســة بحضــور اإلخصائيــة االجتماعيــة ‪..........‬‬\n‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪..........‬وأقفلــت اجللســة‬\n‫الســاعة الواحــدة ظهــرا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/21‬ه ـ احلمــد هلل وحــده‬\n‫وبعــد ففــي يــوم األحــد املوافــق‪ 1434/09/13‬ه ـ افتتحــت اجللســة لــدى‬\n‫أنــا ‪..........‬القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة والقائــم بعمــل‬\n‫فضيلــة ‪..........‬وفيهــا عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n‫قرارهــا رقــم ‪ 34291181‬وتاريــخ ‪1434/8/8‬ه ـ املتضمــن املوافقــة علــى‬\n‫احلكــم الصــادر مــن فضيلتــه برقــم ‪ 34252636‬وتاريخ ‪1434/6/26‬هـ‬\n‫لــذا أمــرت باحلــاق ذلــك لضبطــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/09/13‬ه ـ‬\n\n\n\n\n                                                                                     ‫‪162‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":160,"source_page_end":162,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6d8ca86601c09ea2dfc772b4cf66dc0781486bba932cbe25c62bdbba26f1983e","normalized_text_hash":"369cbbc3e9f0c63313d3195302ddb1dce08097eed2fdc2e190d9cfe6cf62ab25","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p160-34252636"},{"id":"101eeeae-a7db-50b4-9057-6f65b58817f7","document_type":"judgment","category":"judicial","subcategory":"general","title":"ابتزاز -ابتزاز فتاة مالي ا -تهديد بنشر صور -إقامة عالقة محرمة مع فتاة -جرائم معلوماتية -وجود سابقة للمدعى عليه -املدعى عليه محصن -التعزير بالسجل واجللد ومصادرة األجهزة املستخدمة والغرامة.","document_number":"34277055","case_number":"34283626","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بطريف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/23","year":"1434","subject":"ابتزاز -ابتزاز فتاة مالي ا -تهديد بنشر صور -إقامة عالقة محرمة مع فتاة -جرائم معلوماتية -وجود سابقة للمدعى عليه -املدعى عليه محصن -التعزير بالسجل واجللد ومصادرة األجهزة املستخدمة والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34277055 :‬تاريخه‪1434/7/23 :‬هـ‬\n                          ‫رقم الدعوى‪34283626:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34309364‬تاريخه‪1434/8/29 :‬هـ‬\n\n\n      ‫ابتــزاز ‪ -‬ابتــزاز فتــاة ماليـ ًا ‪ -‬تهديــد بنشــر صــور ‪ -‬إقامــة عالقــة محرمــة‬\n      ‫مــع فتــاة ‪ -‬جرائــم معلوماتيــة ‪ -‬وجــود ســابقة للمدعــى عليــه ‪ -‬املدعــى‬\n      ‫عليــه محصــن ‪ -‬التعزيــر بالســجل واجللــد ومصــادرة األجهــزة‬\n                                                            ‫املســتخدمة والغرامــة‪.‬‬\n\n\n\n\n                       ‫‪ -1‬املادة الثالثة من نظام مكافحة اجلرائم املعلوماتية‪.‬‬\n                                             ‫‪ -2‬ما أشير له يف تسبيب احلكم‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بقيامــه بابتــزاز‬\n      ‫فتــاة بنشــر صورهــا وإقامــة عالقــة غيــر مشــروعة معهــا وطلــب إثبــات مــا‬\n      ‫أســند إليــه وإيقــاع العقوبــة التعزيريــة ســجنا وغرامــة ‪ -‬حيث ورد بالغان‬\n      ‫مــن فتاتــن لهيئــة األمــر باملعــروف والنهــي عــن املنكــر ومفادهمــا أن‬\n      ‫املدعــى عليــه تعــرف عليهمــا بواســطة موقــع متخصــص يف الشــبكة‬\n      ‫العنكبوتيــة بالتعريــف بالراغبــن يف الــزواج وأنــه طلــب منهمــا صورهما‬\n      ‫ثــم أصبــح يبتزهمــا بنشــرها وأن إحداهــن اســتجابت لتهديداتــه فحولــت‬\n      ‫لــه وألختــه مبالــغ ماليــة ‪ -‬أقــر املدعــى عليــه باســتعماله للجهــاز الــوارد‬\n      ‫مــن االبتــزاز وأن الرقــم عائــد لــه وباســتخدامه للحســاب البنكــي وورود‬\n\n‫‪163‬‬\n\f‫املبلــغ املالــي لــه وأن الصــور املوجــودة لــدى املبلغــة عائــدة لــه وملــا تضمنــه‬\n‫محضــر القبــض مــن قبــل رجــال الهيئــة مــن قيامــه بالتخلــص مــن جهــازه‬\n‫أثنــاء القبــض وبنــاء علــى مــا تضمنــه محضــر تفريــغ الرســائل وإلقــراره‬\n‫باســتعماله حســاب أختــه ولعــدم القناعــة مبــا أجــاب بــه ولوجــود ســابقة‬\n‫عليــه كمــا أنــه محصــن وإلنــكاره التهــم املوجهــة إليــه فــإن احملكمــة‬\n‫قــررت عــدم ثبــوت التهمــة بشــكل قاطــع كمــا قــررت قيــام التهمــة‬\n‫املوجبــة للتعزيــر للقرائــن القويــة وصــدر احلكــم علــى املدعــى عليــه‬\n‫بتعزيــره بالســجن واجللــد والغرامــة ومصــادرة األجهــزة املســتعملة ‪ ،‬قــرر‬\n‫املدعــى عليــه القناعــة بينمــا اعتــرض املدعــي العــام بتقــدمي الئحــة وأفهــم‬\n                   ‫بالتعليمــات ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ففــي يــوم‬\n‫األحــد املوافــق ‪1434/7/23‬ه ـ ويف متــام الســاعة العاشــرة لــدي انــا‬\n‫‪ ..........‬القاضــي باحملكمــة العامــة بطريــف وبنــاء علــى املعاملــة احملالــة‬\n‫لــي بشــرح الرئيــس برقــم ‪34283626‬وتاريــخ ‪1434/6/20‬ه ـ واملقيــدة‬\n‫برقــم ‪341464118‬بخصــوص دعــوى املدعــي العــام ضــد ‪..........‬وقــد‬\n‫حضــر املدعــي العــام وقــدم الئحــة ادعــاء فيمايلــي نصهــا بعــد املقدمــة‬\n‫املتهــم ‪ ،.......... /‬ســعودي اجلنســية مبوجــب الهويــة الوطنية رقــم (‪)..........‬‬\n‫العمــر ‪ 32 /‬عامــا املهنــة ‪ /‬موظــف مــكان اإلقامــة ‪/‬محافظــة طريــف‬\n‫رقــم اجلــوال ‪........../‬التصــرف باملتهــم ‪ /‬موقــوف مبوجــب أمــر إليقــاف‬\n‫رقــم (‪ )..........‬وتاريــخ ‪1434/5/15‬ه ـ اســتنادا للقــرار الــوزاري (‪)1900‬‬\n‫الوقائــع احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبي بعــده وبعد‪...‬‬\n\n                                                                                            ‫‪164‬‬\n\f      ‫فإنــه يف يــوم ‪1434/5/3‬ه ـ تقدمــت فتــاة لهيئــة األمــر باملعــروف والنهــي‬\n      ‫عــن املنكــر مبحافظــة ‪..........‬بشــكوى علــى صاحــب الرقــم (‪)..........‬‬\n      ‫وذكــرت أن اســمه ‪ ، ..........‬كمــا ذكــرت أنــه تعــرف عليهــا عــن طريق‬\n      ‫الشــبكة العنكبوتيــة مبوقــع زواج وهــو موقــع (‪ ، )..........‬وقــام بإيهامها‬\n      ‫بالــزواج منهــا وقــد جــاء اتصــال مــن جــوال رقــم (‪ )..........‬وذكــرت‬\n      ‫املتصلــة أن اســمها ‪ ..........‬أخــت ‪..........‬وقــد أكــدت لهــا رغبتهــم بالــزواج‬\n      ‫منهــا ‪،‬وبعــد انتهــاء االتصــال عــاود املتهــم ‪..........‬االتصــال مــن رقمــه‬\n      ‫الشــخصي ‪ ،‬وطلــب منهــا صــور شــخصية لهــا حتــى يتقــدم خلطبتهــا‬\n      ‫وذلــك بعــد أن قــام هــو بإرســال صــور شــخصية لــه للفتــاة وجــزء مــن‬\n      ‫صــورة بطاقــة أحوالــه ‪ ،‬وعندمــا قامــت الفتــاة بإرســال صورهــا لــه طلــب‬\n      ‫منهــا محادثتــه عــن طريــق الكمبيوتــر بالكاميــرا ‪ ،‬ثــم طلــب منهــا‬\n      ‫حتويــل مبالــغ ماليــة حلســابه وإال ســيقوم بنشــر صورهــا ‪ ،‬ومقاطــع‬\n      ‫الفيديــو التــي ســجلها مــن خــال الكاميــرا ‪ ،‬وقــد حولــت الفتــاة لــه‬\n      ‫مبالــغ نقديــة علــى حســابه الشــخصي رقــم (‪ )..........‬ومــن ضمــن هــذه‬\n      ‫املبالــغ مبلــغ وقــدره خمســة آالف ريــال ‪،‬كمــا طلــب منهــا املتهــم بتحويــل‬\n      ‫مبالــغ ماليــة علــى حســاب أختــه ‪..........‬رقــم (‪ ، )..........‬كمــا مت تفريــغ‬\n      ‫رســائل التهديــد مــن جــوال الفتــاة والصــادرة مــن جــوال املتهــم ‪ ....‬مــن‬\n      ‫قبــل رجــال هيئــة األمــر باملعــروف والنهــي عــن املنكــر ‪.‬وبقيــام هيئــة‬\n      ‫األمــر باملعــروف والنهــي عــن املنكــر بالرجــوع للجهــاز اخلــاص بهــم تبــن‬\n      ‫وجــود ســابقة علــى املتهــم وقــد مت التســتر عليــه يف حينــه وقــد كانــت‬\n      ‫علــى النحــو التالــي بتاريــخ ‪1432/8/24‬ه ـ مــن يــوم األثنــن تقدمــت‬\n      ‫إحــدى الفتيــات إلــى مركــز هيئــة األمــر باملعــروف والنهــي عــن املنكــر‬\n      ‫بحــي ‪..........‬بالريــاض مدعيــة علــى املتهــم ‪........../‬بابتزازهــا عــن طريــق‬\n\n\n‫‪165‬‬\n\f‫أحــد املواقــع يف الشــبكة العنكبوتيــة وهــو موقــع زواج اســمه (‪)..........‬‬\n‫‪ ،‬حيــث قــام باســتدراج الفتــاة وأخــذ صورهــا الشــخصية عــن طريــق‬\n‫إختــراق جهازهــا ‪ ،‬ثــم قــام بتهديدهــا بنشــر الصــور يف حــال عــدم تلبيــة‬\n‫رغباتــه بفتــح الكاميــرا وعــرض نفســها عليــه‪ .‬وقــد مت مشــاهدة إمييــل‬\n‫الفتــاة مــن قبــل رجــال هيئــة األمــر باملعــروف والنهــي عــن املنكــر يف يــوم‬\n‫األربعــاء املوافــق ‪1432/9/3‬ه ـ ‪ ،‬واتضــح أنــه يحتــوي علــى عــدة رســائل‬\n‫مــن إمييــل الشــاب املبتــز واملســجل يف موقــع ‪ .........‬باســم (‪ ، )..........‬ومــن‬\n‫ضمــن هــذه اإلمييــات إمييــل الفتــاة املدعيــة وعــدد أخــر مــن اإلمييــات مت‬\n‫إرســال الصــور لهــم ‪،‬وهــي عــدد ســبع صــور عائــدة للفتــاة ‪ ،‬وقــد علــق‬\n‫علــى هــذه الصــور بقولــه البــذئ (( هــذي وحــدة تطلــع مــع شــباب اســمها‬\n‫‪ ..........‬مــن ســكان الريــاض ‪،‬عمرهــا ‪23‬ســنه مطلقــة يعنــي الطريــق‬\n‫مفتــوح ‪ ،‬شــكل زوجهــا كشــفها وطلقهــا وهذا امييلهــا ‪-‬ووضع االمييل‪-‬‬\n‫تشــبك علــى طــول بايعتهــا وحتــب الطلعــات مــع الشــباب ولهــا صــور بــدون‬\n‫مالبــس بالليــل أرســلها )وقــد توصــل رجــال هيئــة األمــر باملعــروف والنهي‬\n‫عــن املنكــر عــن معلومــات لصاحــب املعــرف‪ ..........‬فاتضــح أن جوالــه‬\n‫هــو (‪ )..........‬وإمييلــه هــو نفســه املســجل لــدى الفتــاة كمــا أن لــه معــرف‬\n‫آخــر (‪)..........‬ويف يــوم ‪1434/5/15‬ه ـ قــام رجــال هيئــة األمــر باملعــروف‬\n‫والنهــي عــن املنكــر مبحافظــة طريــف باالتصــال علــى الرقــم (‪)..........‬‬\n‫وإعــداد محضــر باالتصــال ‪ ،‬ومت االتفــاق معــه علــى احلضــور يف مــكان‬\n‫معــن ‪ ،‬فحضــر املتهــم نفســه فــإذا برجــال هيئــة األمــر باملعــروف والنهــي‬\n‫عــن املنكــر يقبضــون عليــه ويتضــح أن اســمه كمــا ادعــت الفتــاه‬\n‫‪ ،..........‬وعنــد مشــاهدته لرجــال الهيئــة ويف حــن غفلــة منهــم قــام‬\n‫بالتخلــص مــن جوالــه أثنــاء القبــض عليــه ‪ ،‬علمــا أنهــم شــاهدوا اجلــوال‬\n\n\n                                                                                          ‫‪166‬‬\n\f      ‫بيــده وقــد كان يكلــم بــه ‪.‬ومبخاطبــة االتصــاالت تبــن أن الرقــم‬\n      ‫(‪ )..........‬عائــد ل‪ ،..........‬كمــا أنــه يســتخدم االنترنــت مــن نفــس هــذا‬\n      ‫الرقــم ‪.‬وباســتجواب املتهــم ‪/‬أقــر باســتخدامه الرقــم املشــار إليه‪،‬وأنــه‬\n      ‫عائــد لــه شــخصيا ‪،‬كمــا أقــر باحلســاب البنكــي وأنــه عائــد لــه خصيــا‬\n      ‫‪،‬كمــا أقــر باســتخدامه لالنترنــت ‪،‬وأقــر بأنــه مت إيــداع مبلــغ خمســة‬\n      ‫آالف ريــال حلســابه وال يعــرف مصــدر هــذا املبلــغ ‪،‬وال مــن قــام بإيــداع‬\n      ‫املبلــغ ‪ ،‬كمــا أقــر باســتخدام حســاب أختــه ‪،..........‬كمــا تناقــض يف‬\n      ‫أقوالــه يف اســتخدام جهــاز احلاســب الــاب تــوب فتــارة يقــر بــه وتــارة‬\n      ‫ينكــره ‪،‬كمــا أفــاد بــأن الصــور الشــخصية عائــدة لــه وال يعلــم كيــف‬\n      ‫وصلــت للفتــاة ‪ ،‬وأنكــر معرفتــه بالفتــاة‪ .‬وبالبحــث عــن ســوابقه تبــن‬\n      ‫عــدم وجــود ســوابق مســجلة عليــه ‪.‬وقــد انتهــى التحقيــق معــه إلــى توجيــه‬\n      ‫االتهــام ل‪..........‬بابتــزاز فتــاة بالتهديــد بنشــر صورهــا وإقامــة عالقــة‬\n      ‫غيــر شــرعية معهــا ‪ ،‬وأخــذ مبالــغ ماليــة بغيــر وجــه حــق ‪.‬وذلــك لألدلــة‬\n      ‫والقرائــن التاليــة ‪/1:‬مــا جــاء بإقــراره باســتخدام اجلــوال رقــم(‪)..........‬‬\n      ‫املنــوه عنهــا واملدونــة علــى الصفحــة رقــم(‪ )1‬لفــة رقــم (‪ /2)42‬مــا جــاء‬\n      ‫بإقــراره باســتخدام احلســاب رقــم (‪ )..........‬املنــوه عنــه واملــدون علــى‬\n      ‫الصفحــة رقــم(‪ )2‬لفــة رقــم (‪/3) 42‬مــا جــاء بإقــراره باســتخدام حســاب‬\n      ‫أختــه حكيمــة املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )1‬لفــة رقــم(‪42‬‬\n      ‫)‪/4‬مــا جــاء بإقــراره بإيــداع مبلــغ خمســة آالف ريــال حلســابه املنــوه عنــه‬\n      ‫واملــدون علــى الصفحــة رقــم (‪)2‬لفــة رقــم (‪/5)42‬مــا جــاء بالتحويــل‬\n      ‫البنكــي مــن حســاب الفتــاة إلــى حســاب املتهــم عامــر املنــوه عنهــا‬\n      ‫واملــدون لفــة رقــم(‪/6) 46‬مــا جــاء بإقــراره بعائديــة الصــور الشــخصية‬\n      ‫املرفقــة لــه لفــة رقــم (‪/7.)10،9،8،7‬مــا جــاء بإقــراره باســتخدام‬\n\n\n‫‪167‬‬\n\f‫الشــبكة العنكبوتيــة املنــوه عنهــا واملدونــة علــى الصفحــة رقــم (‪ )2‬لفــة‬\n‫رقم(‪/8)25‬مــا جــاء مــن الشــركة املشــغلة للجــوال باســتخدام املتهــم‬\n‫لإلنترنــت عــن طريــق اجلــوال املذكــور لفــة رقم(‪/9)48،47‬مــا جــاء‬\n‫بتناقــض أقوالــه يف اســتخدام احلاســب اآللــي املنــوه عنهــا واملدونــة علــى‬\n‫الصفحــة رقــم (‪ )4‬لفــة رقــم (‪/10)42‬مــا جــاء يف محضر تفريغ الرســائل‬\n‫مــن قبــل أعضــاء هيئــة األمــر باملعــروف والنهــي عــن املنكــر املنــوه عنهــا‬\n‫واملدونــة علــى اللفــة رقــم ‪/11.)23،22،21‬مــا جــاء مبحضــر هيئــة األمــر‬\n‫باملعــروف والنهــي عــن املنكــر بالتخلــص مــن جوالــه أثنــاء لقبــض عليــة‬\n‫لفــة رقــم (‪/12)30‬مــا جــاء يف محضــر مشــاهدة إمييــل الفتــاة مــن قبــل‬\n‫أعضــاء هيئــة األمــر باملعــروف والنهــي عــن املنكــر مبنطقــة الريــاض‬\n‫لفــة رقــم (‪ )12،11‬وحيــث إن مــا أقــدم عليــه املتهــم املذكــور وهــو‬\n‫بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرعا ‪،‬‬\n‫ممــا يتعــن معــه إحالتــه إلــى احملكمــة املختصــة بطلــب إثبــات إدانتــه‬\n‫مبــا أســند إليــه واحلكــم عليــه مبــا يلــي ‪/1/‬الســجن والغرامــة وفقــا‬\n‫للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام اجلرائــم املعلوماتيــة الصــادر‬\n‫باملرســوم امللكــي رقــم (م‪)17/‬وتاريــخ ‪1428/3/8‬هـ‪/2‬عقوبــة تعزيريــة‬\n‫تزجــره وتــردع غيــره ‪( .‬علمــا ان احلــق اخلــاص الزال قائمــا ) وبعــرض‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي‬\n‫العــام يف دعــواه ضــدي غيــر صحيــح وليــس عنــدي انترنــت باملنــزل واحلــي‬\n‫ال يوجــد فيــه شــبكة وليــس لــي أي عالقــة بالفتــاة وبســؤاله عــن رقــم‬\n‫اجلــوال املســتخدم باالبتــزاز وهــو ‪..........‬هــل هــو عائــد لــه فقــال نعــم هــو‬\n‫لــي وقــد مت اختراقــه وهــو مــن نــوع ‪ ....‬وال يوجــد لــدي بينــة وبســؤاله عــن‬\n‫اســتخدام احلاســب االلــي املشــار لــه أعــاه أجــاب قائــا بأنــه كان‬\n\n\n                                                                                          ‫‪168‬‬\n\f      ‫عنــدي حاســوب أيــام بدايــة برنامــج حافــز وقــد أعطيتــه أختــي مــن أجــل‬\n      ‫حتديــث البيانــات ثــم جــرى ســؤاله كيــف يحــدث بيانــات حافــز ويطلــب‬\n      ‫مــن أختــه حتديــث البيانــات والبيــت واحلــي ال يوجــد فيــه شــبكة‬\n      ‫وحتديــث البيانــات يتطلــب اتصــال بالشــبكة فأجــاب قائــا كنــت‬\n      ‫اثنــاء بدايــة برنامــج حافــز يف منــزل لوحــدي وســلمت اجلهــاز ألهلــي مــن‬\n      ‫أجــل حتديــث البيانــات ثــم جــرى ســؤاله عــن ســبب اســتخدام حســاب‬\n      ‫أختــه فقــال كنــت أســتخدمه ألغــراض شــخصية خفيفــة ومــرات‬\n      ‫بســيطة ثــم جــرى ســؤاله عــن املبلــغ الــذي أودع بحســابه ومــن أيــن أتــى‬\n      ‫لــك فأجــاب ال أعــرف مصــدر املبلــغ إلــى اآلن وقــد كنــت تقدمــت ‪.....‬‬\n      ‫مــن أجــل طلــب إعانــة ماليــة وكنــت أعتقــد أن املبلــغ منهــم ثــم جــرى‬\n      ‫ســؤاله عــن صــوره الشــخصية التــي عنــد الفتــاة فقــال ال أعلــم عــن ســر‬\n      ‫الصــور وكيــف وصلــت لهــا وهــذا الصــور عائــدة لــي لكنــي ال أعلــم‬\n      ‫كيــف وصلتهــا ثــم جــرى ســؤاله عــن اقــراره املــدون يف صحيفــة ‪2‬لفــة‬\n      ‫رقــم ‪ 35‬مــن أنــه كان يســتخدم االنترنــت عــن طريــق اجلــوال فأجــاب ال‬\n      ‫أذكــر أنــي اســتخدمت االنترنــت واقــراري ال أعلــم عنــه وقــد وقعــت مــن‬\n      ‫دون علــم ثــم جــرى ســؤاله عــن ســبب تناقــض اقوالــه يف التحقيــق فمــرة‬\n      ‫يقــول ليــس عنــدي حاســوب ومــرة يقــول عنــدي وأعطيتــه أهلــي فأجــاب‬\n      ‫قائــا عنــد توجيــه الســؤال لــه كنــت أعتقــد أنــه يف هــذا الوقــت ثــم‬\n      ‫جــرى ســؤاله عــن الرســائل املتبادلــة بينــه وبــن الفتــاة عــن طريــق جوالــه‬\n      ‫والتــي وجــدت يف جهــازه فأجــاب قائــا ال أعلــم عــن هــذه الرســائل‬\n      ‫اطالقــا وقــد يكــون جهــازي اختــرق او أخــذه أحــد وال أعلــم ثــم جــرى‬\n      ‫ســؤاله عــن محضــر هيئــة التحقيــق املــدون يف لفــة رقــم ‪30‬واملتضمــن أنــه‬\n      ‫بعــد مشــاهدة رجــال الهيئــة وهــو يكلــم باجلــوال قــام بإلقــاء اجلــوال علــى‬\n\n\n‫‪169‬‬\n\f‫غفلــة مــن رجــال الهيئــة فقــال غيــر صحيــح اطالقــا ولــم يحصــل منــي‬\n‫ذلــك اطالقــا هكــذا أجــاب ثــم جــرى ســؤاله هــل يســتخدم جوالــك‬\n‫الشــخصي أحــد غيــرك فقــال ال أعلــم وقــد يكــون اســتخدم مــن دون‬\n‫علمــي ثــم جــرى ســؤاله هــل يعــرف أحــد الرقــم الســري اخلــاص ببريــدك‬\n‫اإللكترونــي ( اإلمييــل ) فقــال ال أعلــم وأذكــر مــرة نســيته مفتــوح‬\n‫بالــدوام فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث إن املدعــى‬\n‫عليــه قــد أقــر باســتخدامه اجلــوال املذكــور أعــاه بالرقــم املذكــور وأن‬\n‫الرقــم عائــد لــه وحيــث إن املدعــى عليــه قــد أقــر باســتخدامه احلســاب‬\n‫البنكــي املذكــور أعــاه وأقــر كذلــك بدخــول حســابه مبلــغ خمســة‬\n‫آالف ريــال وحيــث إن املدعــى عليــه قــد أقــر بــأن الصــور الشــخصية‬\n‫عائــدة لــه املوجــودة يف إمييــل الفتــاة وبعــد االطــاع علــى محضــر هيئــة‬\n‫األمــر باملعــروف والنهــي عــن املنكــر مــن أنــه قــام بالتخلــص مــن جوالــه‬\n‫أثنــاء القبــض عليــه لفــة رقــم ( ‪ )30‬وبعــد االطــاع علــى محضــر مشــاهدة‬\n‫اإلمييــل التابــع للفتــاة مــن قبــل أعضــاء هيئــة األمــر باملعــروف والنهــي عــن‬\n‫املنكــر مبنطقــة الريــاض لفــة رقــم ( ‪ )11،12‬وبعــد االطــاع علــى‬\n‫محضــر تفريــغ الرســائل مــن قبــل أعضــاء هيئــة األمــر باملعــروف والنهــي‬\n‫عــن املنكــر املدونــة علــى لفــة رقــم (‪ )21،22،23‬وحيــث إن املدعــى‬\n‫عليــه قــد أقــر باســتخدام حســاب أختــه ‪..........‬ونظــرا ألن مــا دفــع بــه‬\n‫املدعــى عليــه غيــر مــاق وحيــث إن املدعــى عليــه لديــه ســابقة كمــا هــو‬\n‫موضــح يف دعــوى املدعــي العــام وحيــث إن املدعــى عليــه قــد أنكــر‬\n‫صحــة مــا جــاء يف دعــوى املدعــي العــام لــذا فإنــه لــم يثبــت لــدي ثبوتــا‬\n‫قطعيــا إدانــة املدعــي عليــه مبــا أســند إليــه يف دعــوى املدعــي العــام‬\n‫ونظــرا لتوجــه التهمــة ملــا ذكــر أعــاه مــن قرائــن قويــة ونظــرا لكــون‬\n\n\n                                                                                         ‫‪170‬‬\n\f      ‫املدعــى عليــه محصــن وبعــد االطــاع علــى الفقــرة الثانيــة مــن املــادة‬\n      ‫الثالثــة مــن نظــام اجلرائــم املعلوماتيــة وبعــد االطــاع علــى املــادة الثالثــة‬\n      ‫عشــر مــن النظــام نفســه فقــد قــررت تعزيــره اوال ‪ :‬بســجنه ســتة أشــهر‬\n      ‫اعتبــارا مــن تاريــخ إيقافــه ‪1434/5/15‬ه ـ وثانيــا ‪ :‬تغرميــه مبلــغ وقــدره‬\n      ‫عشــرون الــف ريــال مــع مصــادرة االجهــزة املســتخدمة وثالثــا جلــده ســتني‬\n      ‫جلــده دفعــة واحــدة وهــذا احلكــم للحــق العــام هــذا مــا ظهــر لــي وبــه‬\n      ‫حكمــت وبعــرض احلكــم علــى املدعــى عليــه قــرر قناعتــه ورضــاه‬\n      ‫باحلكــم وقــرر املدعــي العــام عــدم قناعتــه ورضــاه باحلكــم مــع تقــدمي‬\n      ‫الئحــة إعتراضيــة وجــرى تســليمه نســخة مــن احلكــم وأفهــم بتعليمــات‬\n      ‫اإلســتئناف وصلــى اهلل وســلم علــى نبينــا محمد حــرر يف ‪1434/7/23‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة األولــى‬\n      ‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بطريــف باإلنابــة‬\n      ‫برقــم ‪ 341941989‬وتاريــخ ‪1434/8/10‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ‪.......... /‬املســجل برقــم‬\n      ‫‪ 34277055‬وتاريــخ ‪1434/7/23‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‬\n      ‫‪ .......... /‬يف قضيــة نشــر أخبــار واســرار وصــور وقــد تضمــن القــرار‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ .‬وبدراســة القــرار وصــورة‬\n      ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                     ‫وسلم‬\n\n\n\n\n‫‪171‬‬\n\f172\n\f173\n\f174\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":163,"source_page_end":174,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cbf4b090e2b02615d426698b458fd53fa58be50e6e10709e7b02a1bf67786e8f","normalized_text_hash":"6a96ce6b16930034bba9b8841de41e2dcf8554951206dffce39b8928c853e6e0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p163-34277055"},{"id":"1806347b-962f-5c28-988f-24924ba9284b","document_type":"judgment","category":"judicial","subcategory":"general","title":"إخال باألمن الوطني -نقل أشخاص إلى منطقة حدودية بغرض املشاركة يف قتال دون إذن ولي األمر -تضارب أقوال الشهود -بينة غير موصلة-عجز املدعي العام عن إثبات دعواه -رد الدعوى-إخاء","document_number":"3233216","case_number":"113","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/2/26","year":"1434","subject":"إخال باألمن الوطني -نقل أشخاص إلى منطقة حدودية بغرض املشاركة يف قتال دون إذن ولي األمر -تضارب أقوال الشهود -بينة غير موصلة-عجز املدعي العام عن إثبات دعواه -رد الدعوى-إخاء","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫رقم الصك‪ 3233216 :‬تاريخه‪1432/2/26 :‬هـ‬\n                               ‫رقم الدعوى‪113 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪/1/74‬ص تاريخه‪1435/1/11 :‬هـ‬\n\n\n\n      ‫إخــال باألمــن الوطنــي‪ -‬نقــل أشــخاص إلــى منطقــة حدوديــة بغــرض‬\n      ‫املشــاركة يف قتــال دون إذن ولــي األمــر‪ -‬تضــارب أقــوال الشــهود‪ -‬بينــة‬\n      ‫غيــر موصلة‪-‬عجــز املدعــي العــام عــن إثبــات دعــواه‪ -‬رد الدعوى‪-‬إخــاء‬\n                                                                          ‫ســبيل‪.‬‬\n\n\n\n\n                                                    ‫‪ -1‬األصل براءة الذمة‪.‬‬\n                           ‫‪ -2‬املواد (‪ )195-194‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n      ‫أقــام املدعــي العــام دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن‬\n      ‫طلــب إدانتــه بنقــل عــدد مــن األشــخاص بســيارته إلــى منطقــة حدوديــة‬\n      ‫ملقابلــة أحــد األشــخاص هنــاك لتســهيل خروجهــم إلــى خــارج البــاد‬\n      ‫للمشــاركة يف القتــال الدائــر يف مواطــن الفتنــة واالضطــراب حتــت‬\n      ‫رايــات غيــر رايــة ولــي األمــر ودون إذنــه‪ ،‬وتضليــل جهــة التحقيــق‪،‬‬\n      ‫وطلــب احلكــم عليــه بعقوبــة تعزيريــة ومبنعــه مــن الســفر‪ ،‬حيــث قبــض‬\n      ‫علــى املدعــى عليــه بعــد إدالء بعــض املوقوفــن بإفــادات تتضمــن قيــام‬\n      ‫املدعــى عليــه مبــا نســبه إليــه املدعــي العــام ومبواجهتــه بالدعــوى أمــام‬\n      ‫ا ‪،‬حيــث إن مــا قدمــه‬ ‫احملكمــة أنكــر مــا أســند إليــه جملــة وتفصي ـ ً‬\n\n‫‪175‬‬\n\f‫املدعــي العــام مــن بينــات ال يناهــض البــراءة األصليــة ‪،‬حيــث إنــه مــن‬\n‫املقــرر شــرع ًا أن األصــل بــراءة الذمــة‪ -‬قضــت احملكمــة بعــدم ثبــوت‬\n‫إدانــة املدعــى عليــه مبــا نســب إليــه يف الدعــوى وأخلــت ســبيله منهــا‪ -‬قنــع‬\n‫املدعــى عليــه باحلكــم وعــارض عليــه املدعــي العــام‪ -‬قــررت محكمــة‬\n                                       ‫االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده‪ ،‬وبعــد ويف يــوم األحــد ‪1434/4/14‬ه ـ فتحــت اجللســة‬\n‫الســاعة الثانيــة عشــر وفيهــا حضــر املدعــي العــام ‪ .....‬ولــم يحضــر‬\n‫املدعــى عليــه رغــم طلــب حضــوره مبوجــب خطابنــا رقــم ‪34/6350‬‬\n‫وتاريــخ ‪1434/4/1‬ه ـ لــذا رفعــت اجللســة لطلــب حضوره وأقفلت اجللســة‬\n‫الســاعة الواحــدة وعشــر دقائــق وســيتم حتديــد موعــد اجللســة القادمــة‬\n‫بالتنســيق مــع اجلهــة املختصــة بإحضــار الســجناء وصلــى اهلل علــى نبينــا‬\n                                           ‫محمــد حــرر يف ‪1434/4/14‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد ‪ :‬فلــدي أنــا القاضــي باحملكمــة اجلزائيــة‬\n‫املتخصصــة بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة املتخصصــة املكلــف برقــم ‪ 113‬وتاريخ ‪1434/2/26‬هـ املقيدة‬\n‫باحملكمــة برقــم‪ 34/4030‬وتاريــخ ‪1434/2/26‬ه ـ ويف يــوم الســبت‬\n‫‪1434/4/27‬ه ـ افتتحــت اجللســة الســاعة الثانيــة عشــرة وفيهــا حضــر‬\n‫املدعــي العــام ‪ ،.......‬ولــم يحضــر املدعــى عليــه رغــم طلــب حضــوره‬\n‫بخطابنــا رقــم ‪ 34/7549‬وتاريــخ ‪1434/4/15‬هــ‪ ،‬وقــدم املدعــي العــام‬\n‫الئحــة الدعــوى ونصهــا مــا يل ــي ‪ ( :‬بصفتــي مدعيـ ًا عامـ ًا بهيئــة التحقيــق‬\n‫واالدعــاء العــام أدعــي علــى ‪ ،........‬مواليــد عــام ‪1396‬ه ـ ‪ ،‬ســعودي‬\n\n                                                                                       ‫‪176‬‬\n\f      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ، )...............‬املوقــوف ســابق ًا‬\n      ‫وصــدر التوجيــه بإطــاق ســراحه بتاريــخ ‪1433/2/28‬ه ـ ‪ .‬بارتــكاب‬\n      ‫اجلرائــم التاليــة ‪ :‬نقــل املوقوفــن‪ ، ...... /‬و‪ ،......‬و‪ ،..........‬و‪ ،......‬و‪.....‬‬\n      ‫بســيارته مــن مدينــة الدمــام إلــى منطقــة احلــدود الشــمالية ملقابلــة أحــد‬\n      ‫األشــخاص هنــاك لتســهيل خروجهــم إلــى موطــن الفتنــة واالضطــراب‬\n      ‫عميــة ضالــة‬‫(‪ )......‬للمشــاركة يف القتــال الدائــر هنــاك حتــت رايــات ّ‬\n      ‫غيــر رايــة ولــي األمــر ودون إذنــه ‪ .‬تضليــل جهــة التحقيــق بإخفــاء حقيقــة‬\n      ‫مســاعدة املشــار إليهم يف الشــروع للســفر إلى موطن الفتنة واالضطراب‬\n      ‫(‪ )......‬للقتــال هنــاك مــع وجــود مــا يثبــت مســاعدته لهــم بنقلهــم بســيارته‬\n      ‫اخلاصــة إلــى منطقــة احلــدود الشــمالية ‪ .‬حيــث إنــه بالتاريــخ أعــاه قبــض‬\n      ‫علــى املتهــم املذكــور لــورود معلومــات بعالقتــه بأحــد املشــبوهني‪.‬‬\n      ‫وبضبــط إفــادة املوقــوف ‪ ....‬أفــاد بأنــه تعــرف علــى املتهــم ‪ ....‬املكنــى‬\n      ‫‪ ....‬عــن طريــق ابــن عمــه ‪ ....‬وذلــك عــام ‪1426‬ه ـ تقريب ـ ًا مــن خــال‬\n      ‫لقاءاتــه بــه يف منــزل ‪ ....‬باإلضافــة إلــى زياراتــه للمتهــم ‪ ....‬برفقــة يف‬\n      ‫البــر بضواحــي مدينــة ‪ ......‬وأقــر بأنــه يف بدايــة عــام ‪1427‬ه ـ طلــب مــن‬\n      ‫‪ ....‬بــأن يقــوم بإيصالهــم بســيارته إلــى منطقــة احلــدود الشــمالية وهــم ‪....‬‬\n      ‫و‪ .....‬و‪ ....‬و‪ ....‬للقــاء شــخص هنــاك ســيقوم بتســهيل عمليــة خروجهــم إلــى‬\n      ‫‪ ......‬بقصــد املشــاركة يف القتــال الدائــر هنــاك وبالفعــل قــام بإيصالهــم‬\n      ‫إلــى عرعــر أو ســكاكا ثــم اتصــل علــى ذلــك الشــخص ولكــن‬\n      ‫الشــخص أخبــره بصعوبــة اخلــروج يف هــذا الوقــت وأن الظــروف األمنيــة‬\n      ‫غيــر مناســبة ثــم عــادوا إلــى الدمــام يف نفــس اليــوم علــى ســيارة نــوع ‪....‬‬\n      ‫وصــادق علــى أقوالــه شــرع ًا ‪ .‬وبضبــط إفــادة املوقــوف ‪ ....‬مينــي اجلنســية‬\n      ‫أفــاد مبثــل مــا أفــاد بــه املوقــوف‪ ....‬وصــادق علــى أقوالــه شــرع ًا ‪ .‬وقــد‬\n\n\n‫‪177‬‬\n\f‫انتهــى التحقيــق إلــى توجيــه االتهــام لــه مبــا أســند إليــه ملــا ورد يف أقــوال‬\n‫املوقوفــن ضــده ‪ ....‬و املصدقــة شــرع ًا املرفقــة بــأوراق القضيــة ‪ .‬وحيــث‬\n‫إن مــا أقــدم عليــه املتهــم املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫يــدل علــى ســوء مســلكه وانحــراف منهجــه لكــون الســمع والطاعــة‬\n‫واجلماعــة أصــل مــن أصــول أهــل الســنة واجلماعــة قــال تعالــى ‪(( :‬يــا أيهــا‬\n‫الذيــن آمنــوا أطيعــوا اهلل وأطيعــوا الرســول وأولــي األمــر منكــم فــإن‬\n‫تنازعتــم يف شــيء فــردوه إلــى اهلل والرســول إن كنتــم تؤمنــون بــاهلل‬\n‫واليــوم اآلخــر ذلــك خيــر وأحســن تأويــا)) [النســاء اآليــة ‪ ، ]59‬وقــال‬\n‫صلــى اهلل عليــه وســلم ‪( :‬مــن أطاعنــي فقــد أطــاع اهلل ومــن عصانــي‬\n‫فقــد عصــى اهلل ومــن يطــع األميــر فقــد أطاعنــي ومــن يعــص األميــر‬\n‫فقــد عصانــي) متفــق عليــه ‪ ،‬وجــاء يف العقيــدة الطحاويــة مــا نصــه ‪( :‬وال‬\n‫نــرى اخلــروج علــى أئمتنــا ووالة أمورنــا وال ندعــو عليهــم وال ننــزع يــد ًا مــن‬\n‫طاعتهــم ونــرى طاعتهــم يف طاعــة اهلل عــز وجــل فريضــة مــا لــم يأمــروا‬\n‫مبعصيــة وندعــو لهــم بالصــاح واملعافــاة) ‪ ،‬قــال اإلمــام أحمــد ‪-‬رحمــه‬\n‫اهلل ‪(-‬ومــن الســنة الالزمــة التــي مــن تــرك منهــا خصلــة لــم يقبلهــا ويؤمــن‬\n‫بهــا ‪ ،‬لــم يكــن مــن أهلهــا ‪ ...‬والســمع والطاعــة لألئمــة وأميــر املؤمنــن‬\n‫‪ ...‬والغــزو مــاض مــع األمــراء إلــى يــوم القيامــة البــر والفاجــر ‪ ...‬ومــن‬\n‫خــرج علــى إمــام مــن أئمــة املســلمني وقــد كان النــاس اجتمعــوا عليــه ‪،‬‬\n‫وأقــروا لــه باخلالفــة بــأي وجــه كان بالرضــا ‪ ،‬أو بالغلبــة ‪ ،‬فقــد شــق‬\n‫هــذا اخلــارج عصــا املســلمني وخالــف اآلثــار عــن رســول اهلل صلــى اهلل‬\n‫عليــه وســلم ‪ ،‬فــإن مــات اخلــارج عليــه مــات ميتــة جاهليــة ‪ ،‬وال يحــل‬\n‫قتــال الســلطان وال اخلــروج عليــه ألحــد مــن النــاس ‪ ،‬فمــن فعــل ذلــك فهــو‬\n‫مبتــدع علــى غيــر الســنة والطريــق) شــرح الســنة لاللكائــي ‪، 1/123‬‬\n\n\n                                                                                          ‫‪178‬‬\n\f      ‫وحيــث إن مــن واجبــات البيعــة الســمع والطاعــة يف املعــروف يف املنشــط‬\n      ‫واملكــره ويف الرضــا والغضــب وهــي صفقــة اليــد وثمــرة الفــؤاد ويجــب‬\n      ‫الوفــاء بلوازمهــا ‪ .‬كمــا أن مــا أقــدم عليــه املتهــم املذكــور مــن نقــل‬\n      ‫املوقوفــن‪ ، ....‬و‪ ، ....‬و‪ ، ....‬و‪ ، ....‬و‪ ....‬بســيارته مــن مدينــة الدمــام‬\n      ‫إلــى منطقــة احلــدود الشــمالية ملقابلــة أحــد األشــخاص هنــاك لتســهيل‬\n      ‫خروجهــم إلــى موطــن الفتنــة واالضطــراب (العــراق) للمشــاركة يف‬\n      ‫القتــال الدائــر هنــاك حتــت رايــات عميــة ضالــة غيــر رايــة ولــي األمــر‬\n      ‫ودون إذنــه يــدل علــى اشــتراكه معهــم يف اجلرميــة وهــو مخالــف ملنهــج‬\n      ‫أهــل الســنة واجلماعــة لكــون اجلهــاد حتــت رايــة اإلمــام وبأمــره مــن الزم‬\n      ‫ع ــقد بيعتــه املن ــعقد يف كـ ــل ذمــة مــن رعيتــه ‪،‬فاالفتيــات عليــه بالقتــال‬\n      ‫حتــت رايــة غيــر رايتــه ودون إذنــه مخالــف ومناقــض للــوازم ذلــك العقــد‬\n      ‫وصــورة مــن صــور اخلــروج ومنازعــة األمــر أهلــه ‪ ،‬قــال صلــى اهلل عليــه‬\n      ‫وســلم‪((:‬كانت بنــو إســرائيل تسوســهم األنبيــاء كلمــا هلــك نبــي خلفــه‬\n      ‫نبــي وإنــه ال نبــي بعــدي وســيكون خلفــاء فيكثــرون قالــوا فمــا تأمرنــا‬\n      ‫وفــوا ببيعــة األول فــاألول ‪ ،‬أعطوهــم حقهــم فــإن اهلل ســائلهم عمــا‬      ‫قــال‪ُ :‬‬\n      ‫اســترعاهم)) متفــق عليــه ‪ ،‬وقــال صلــى اهلل عليــه وســلم ‪(( :‬فإنــه مــن‬\n      ‫خــرج عــن الســلطان شــبرا مــات ميتــة جاهليــة)) احلديــث رواه البخــاري‬\n      ‫‪ ،‬وقــال صلــى اهلل عليــه وســلم‪(( :‬مــن خلــع يــد ًا مــن طاعــة لقــي اهلل يــوم‬\n      ‫القيامــة ال حجــة لــه)) رواه مســلم ‪ .‬وملّــا كانــت واليــة اجلهــاد والقتــال‬\n      ‫واليــة عامــة مختــص بهــا اإلمــام أو مــن ينيبــه ‪ ،‬وأن منــاط األمــر بــه أو‬\n      ‫منعــه إلــى حــن هــو تقديــر اإلمــام للمصالــح واملفاســد علــى نحــو تكــون‬\n      ‫فيــه كلمــة اهلل هــي العليــا ويكــون الديــن كلــه هلل ‪ ،‬قــال صلــى اهلل‬\n      ‫عليــه وســلم‪(( :‬وإمنــا اإلمــام ُج ّنــة يقاتــل مــن ورائــه ويتقــى بــه)) احلديــث‬\n\n\n‫‪179‬‬\n\f‫متفــق عليــه ‪ ،‬وجــاء يف مختصــر اخلرقــي (وواجــب علــى النــاس إذا جــاء‬\n‫العــدو أن ينفــروا املقــل منهــم واملكثــر وال يخرجــوا إلــى العــدو إال بــإذن‬\n‫األميــر إال أن يفجأهــم عــدو غالــب يخافــون كلبــه فــا ميكنهــم أن‬\n‫يســتأذنوه)) ص‪، 128‬قــال ابــن قدامــة ‪ -‬رحمــه اهلل ‪( -‬وأمــر اجلهــاد‬\n‫موكــول إلــى اإلمــام واجتهــاده ويلــزم الرعيــة طاعتــه فيمــا يــراه) املغنــي‬\n‫‪ . 166/9‬وحيــث إن حقيقــة القتــال هــو تصــرف يف الدمــاء واألمــوال‬\n‫واألعــراض علــى نحــو التفويــت والهلكــة ‪ ،‬فمتــى وقــع دون ســند مــن‬\n‫كتــاب اهلل أو ســنة رســول اهلل صلــى اهلل عليــه وســلم وقــع علــى وجــه‬\n‫الهــوى أو االنتقــام فــكان مــن قبيــل اإلفســاد الــذي نهــى اهلل عنــه ‪،‬‬\n‫قــال تعالــى ‪(( :‬وإذا تولــى ســعى يف األرض ليفســد فيهــا ويهلــك احلــرث‬\n‫والنســل واهلل ال يحــب الفســاد)) [البقــرة ‪ :‬اآليــة ‪ ، ]205‬وقــال تعالــى ‪:‬‬\n‫((مــن أجــل ذلــك كتبنــا علــى بنــي إســرائيل أنــه من قتل نفســا بغير نفس‬\n‫أو فســاد يف االرض فكأمنــا قتــل النــاس جميعــا ومــن أحياهــا فكأمنــا‬\n‫أحيــا النــاس جميعـ ًا ولقــد جاءتهــم رســلنا بالبينــات ثــم إن كثيــر ًا منهــم‬\n‫بعــد ذلــك يف األرض ملســرفون)) [املائــدة ‪ :‬اآليــة ‪ ، ]32‬وقــال صلــى اهلل‬\n‫عليــه وســلم‪(( :‬الغــزو غــزوان فأمــا مــن ابتغــى وجــه اهلل وأطــاع اإلمــام‬\n‫وأنفــق الكرميــة وياســر الشــريك واجتنــب الفســاد فــإن نومــه ونبهــه أجــر‬\n‫كلــه وأمــا مــن غــزا فخــر ًا وريــاء وســمعة وعصــى اإلمــام وأفســد يف‬\n‫األرض فإنــه لــن يرجــع بكفــاف)) رواه أحمــد والنســائي يف املجتبــى‬\n‫واحلاكــم يف املســتدرك وقــال صحيــح علــى شــرط مســلم وتابعــه الذهبي‬\n‫‪ ،‬وملّــا كان القتــال الدائــر يف ‪ ......‬وغيــره قتــال فتنــة ال يعلــم ل ــه إمــام‬\n‫العميــة مجهولــة املقصــد واألهــداف‬     ‫وال رايــة بــل تعــددت فيــه الرايــات ّ‬\n‫‪ ،‬وتناحــرت فيــه املذاهــب والطوائــف واألعــراق ‪ ،‬وقُ تــل فيــه كثيــر‬\n\n\n                                                                                         ‫‪180‬‬\n\f      ‫ممــن ال يجــوز قتلهــم مــن أهــل القبلــة وغيرهــم ‪ ،‬فقتــال هــذه صفتــه‬\n      ‫ال جتــوز املشــاركة فيــه بحــال فكيــف إذا منعــه اإلمــام والعلمــاء؟! بــل‬\n      ‫إن مثــل هــذه املواطــن منابــت لــكل شــر ‪ ،‬فيكثــر فيهــا أهــل البــدع‬\n      ‫والشــبهات ومــن يطلبــون الدنيــا بالديــن ‪ ،‬ممــن اســتهدفوا هــذه البــاد‬\n      ‫املباركــة مــن خــال زرع بدعهــم وشــبهاتهم فيمــن يفــد إليهــم مــن أهلهــا‬\n      ‫ويحرصــون علــى ذلــك ‪ ،‬فعــادوا إليهــا يكفــرون أهلهــا ووالة أمرهــا‬\n      ‫ويســتبيحون دماءهــم ‪ .‬وحيــث إن مــا أقــدم عليــه املتهــم املذكــور فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرع ًا وموجــب مــن موجبــات التعازيــر لــذا أطلــب‬\n      ‫اآلتــي ‪ -:‬إدانتــه شــرع ًا مبــا أســند إليــه ‪ .‬احلكــم عليــه بعقوبــة تعزيريــة‬\n      ‫شــديدة زاجــرة لــه ورادعــة لغيــره ‪ .‬احلكــم مبنعــه مــن الســفر بعــد انتهــاء‬\n      ‫مــدة ســجنه اســتناد ًا للمــادة السادســة الفقــرة الثانيــة مــن نظــام وثائــق‬\n      ‫الســفر الصــادر باملرســوم امللكــي رقــم م‪ 24/‬وتاريــخ ‪1421/5/28‬ه ـ ‪).‬‬\n      ‫انتهــى هكــذا ادعــى ورفعــت اجللســة لطلــب حضــور املدعــى عليــه لتــاوة‬\n      ‫الدعــوى عليــه وأقفلــت الســاعة الثانيــة عشــرة والنصــف وصلــى اهلل علــى‬\n                                           ‫نبينــا محمــد وحــرر يف ‪1434/4/27‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن ‪1434/7/4‬ه ـ فتحــت اجللســة‬\n      ‫الســاعة العاشــرة وفيهــا حضــر املدعــي العــام‪ ....‬وحضــر حلضــوره املدعــى‬\n      ‫عليــه‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ( ‪)..............‬‬\n      ‫وبســؤاله اجلــواب عــن الدعــوى بعــد تالوتهــا عليــه‪ ،‬وإفهامــه بحقــه يف‬\n      ‫اســتالم نســخة مــن الدعــوى وتوكيــل محــام أو وكيــل شــرعي أجــاب‬\n      ‫بقولــه‪ :‬أنــا مطلــق الســراح ومــن ســكان املنطقــة الشــرقية وأعانــي مــن‬\n      ‫إصابــة يف إحــدى رجلــي أدت إلــى قطعهــا مــن فــوق الركبــة وكســور‬\n      ‫يف اليديــن وتنقالتــي بواســطة كرســي متحــرك وأطلــب تســليمي نســخة‬\n\n\n‫‪181‬‬\n\f‫الئحــة الدعــوى لإلجابــة عنهــا يف اجللســة القادمــة وســأحدد يف اجللســة‬\n‫القادمــة تعيــن محــام مــن عدمــه وأطلــب منحــي وقت ـ ًا كافي ـ ًا إلعــداد‬\n‫جوابــي واختيــار احملامــي هكــذا أجــاب فجــرى تســليمه نســخة مــن‬\n‫الدعــوى لإلجابــة عنهــا يف اجللســة القادمــة ونظــر ًا لكــون احملكمــة‬\n‫يف املقــر الصيفــي بجــدة بصــدد نظــر قضايــا املوقوفــن واملدعــى عليــه‬\n‫مطلــق الســراح ويقيــم يف املنطقــة الشــرقية وطلــب منحــه وقت ـ ًا كافي ـ ًا‬\n‫إلعــداد جوابــه وتعيــن محــام يختــاره وتقديــر ًا حلالتــه الصحيــة لــذا رفعت‬\n‫اجللســة وأقفلــت الســاعة العاشــرة والربــع وتأجلــت اجللســة إلــى يوم األحد‬\n‫‪1434/10/11‬ه ـ وصلــى اهلل علــى نبينــا محمــد حــرر يف ‪1434/7/4‬هــ‪.‬‬\n‫احلمد هلل وحده وبعد ويف يوم األحد ‪1434/10/11‬هـ الســاعة العاشــرة‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي العــام‪ ....‬وحضــر حلضــوره املدعــى‬\n‫عليــه‪ ، ....‬وقــرر قائـاً‪ :‬وكلــت احملامــي‪ ......‬باملدافعــة واملرافعــة عني يف‬\n‫هــذه القضيــة ولــه حــق تقــدمي املذكــرات اجلوابيــة واللوائــح االعتراضيــة‬\n‫بعــد أخــذ توقيعــي علــى األوراق التــي يتقــدم بهــا علــى أن تتكفــل وزارة‬\n‫العــدل بدفــع أتعــاب احملامــي لعجــزي املــادي‪ -‬هكــذا قــرر‪ -‬فجــرى‬\n‫إثبــات الوكالــة بالصفــة الــواردة أعــاه‪ ،‬وبســؤال املدعــى عليــه احلاضــر‬\n‫عــن إجابتــه التــي اســتمهل مــن أجلهــا قــدم مذكــرة جوابيــة مكونــة مــن‬\n‫صفحــة واحــدة باســم احملامــي ونصهــا حرفيـ ًا مــا يلي‪( :‬بصفتــي احملامي‬\n‫والوكيل الشــرعي عن موكلي‪ ، ............./‬ســعودي اجلنســية‪ ،‬مبوجب‬\n‫ســجل مدنــي رقــم(‪ )..........‬موقــوف بســجن املباحــث العامــة بتاريــخ‬\n‫‪1432/04/1-‬ه ـ ‪ ،‬أقــدم لكــم جــواب موكلــي عــن دعــوى املدعــي‬\n‫العــام ومــا جــاء يف الئحتــه مــن تهــم حيــث قــرر موكلــي قائ ـاً‪ :‬أفيــد‬\n‫فضيلتكــم أن دعــوى املدعــي مجــرد تهــم ال صحــة لهــا وال دليــل وال بينــة‬\n\n\n                                                                                    ‫‪182‬‬\n\f      ‫ا ولــم أصــادق علــى هــذه التهم‬   ‫عليهــا وهــي غيــر صحيحــة جملـ ًة وتفصيـ ً‬\n      ‫مــن األســاس وأطلــب إخــاء ســبيلي مــن هــذه الدعــوى واحلكــم بردهــا‬\n      ‫وتعويضــي عــن األضــرار التــي تعرضــت لهــا ومنهــا ‪-:‬احلبــس االنفــرادي‬\n      ‫ملــدة خمســة أشــهر وعشــرة أيــام‪ .‬عــدم متكينــي مــن االســتعانة مبحامــي‬\n      ‫أثنــاء فتــرة التحقيــق‪ .‬القيــد بالكلبشــة يف اليديــن‪ .‬مســاومتي مــن قِ بــل‬\n      ‫احملقــق باإلقــرار علــى التصديــق والتعاون مقابل اخلــروج‪ .‬املنع من الزيارة‬\n      ‫عمــا حصــل مــن مداهمــة‬  ‫واالتصــال واالطمئنــان علــى األهــل‪ .‬ناهيكــم ّ‬\n      ‫ملنزلــي يف غيابــي وترويــع األبنــاء واألهــل بحمــل األســلحة يف وجوههــم‬\n      ‫ممــا تســبب لهــم بأزمــة نفســية مــا زالــوا يعانــون منهــا حتــى اآلن ‪ .‬هــذا‬\n      ‫جوابــي»‪ .‬انتهــى‪ .‬هــذا جــواب موكلــي وقــد أجــاب عــن التهــم مبــا يثبــت‬\n      ‫براءتــه وينفــي إدانتــه وعليــه آمــل إخــاء ســبيل موكلي من هــذه الدعوى‬\n      ‫وإثبــات براءتــه بــراءة للذمــة‪ ،‬واهلل يرعاكــم‪ ،‬وصلــى اهلل وســلم علــى‬\n      ‫نبينــا محمــد‪ .‬احملامــي‪ ...........:‬ســجل مدنــي رقــم ‪ )............( :‬ترخيــص‬\n      ‫وزارة العــدل رقــم ‪ ........... :‬انتهــى‪ .‬وبعــرض ذلــك علــى املدعــي العــام رد‬\n      ‫قائ ـاً‪ :‬تضمــن جــواب املدعــى عليــه إنــكاره ملــا نســب إليــه يف الئحــة‬\n      ‫الدعــوى العامــة وهــذا اإلنــكار غيــر صحيــح بــل الصحيــح مــا جــاء يف‬\n      ‫الالئحــة وبينتــي علــى ذلــك إقــرار املوقــوف املرفــق بــأوراق القضيــة علــى‬\n      ‫اللفــة رقــم (‪ )16‬ومــا جــاء يف إقــرار مينــي اجلنســية املرفــق بــأوراق القضيــة‬\n      ‫علــى اللفــة رقــم (‪ )15‬وهمــا إقــراران مصدقــان شــرعاً‪ ،‬وقــد تضمنــت‬\n      ‫إفــادة املوقــوف‪......... /‬بأنــه تعــرف علــى املتهــم‪ /‬املكنــى‪.... /‬عــن طريــق‬\n      ‫ابــن عمــه‪ ......... /‬وذلــك عــام ‪1426‬ه ـ تقريب ـ ًا مــن خــال لقاءاتــه بــه يف‬\n      ‫منــزل‪ ........... /‬باإلضافــة إلــى زياراتــه للمتهــم‪ ... /‬برفقــة ‪ .....‬يف البــر‬\n      ‫بضواحــي مدينــة الدمــام وأقــر بأنــه يف بدايــة عــام ‪1427‬ه ـ طلــب‪......... /‬‬\n\n\n‫‪183‬‬\n\f‫مــن‪ ........... /‬بــأن يقــوم بإيصالهــم بســيارته إلــى منطقــة احلدود الشــمالية‬\n‫وهــم (‪..... .‬و‪........‬و‪..‬و‪...‬و‪..‬و ‪ ).‬للقــاء شــخص هنــاك ســيقوم بتســهيل‬\n‫عمليــة خروجهــم إلــى العــراق بقصــد املشــاركة يف القتــال الدائــر هنــاك‬\n‫وبالفعــل قــام ‪....‬بإيصالهــم إلــى عرعــر أو ســكاكا ثــم اتصــل ‪.........‬‬\n‫علــى ذلــك الشــخص ولكــن الشــخص أخبــره بصعوبــة اخلــروج يف هــذا‬\n‫الوقــت وأن الظــروف األمنيــة غيــر مناســبة ثــم عــادوا إلــى الدمــام يف‬\n‫نفــس اليــوم علــى ســيارة نــوع ‪ ....‬كمــا تضمنــت إفــادة املوقــوف ‪.............‬‬\n‫ـ ـ مينــي اجلنســية ـ ـ مبثــل مــا أفــاد بــه املوقــوف‪ ............ /‬هكــذا رد‪ ،‬وقــد‬\n‫جــرى اطالعنــا علــى أقــوال املذكوريــن املرفقــة باملعاملــة وقــد تضمنــت‬\n‫مــا ذكــره املدعــي العــام بعاليــه‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه رد‬\n‫قائـاً‪ :‬أطلــب إمهالــي إلحضــار ردي مكتوبـ ًا هكــذا رد‪ ،‬فجرى إمهال‬\n‫املدعــى عليــه لتقــدمي رده إلــى اجللســة القادمــة‪ ،‬وأقفلــت اجللســة الســاعة‬\n‫العاشــرة والنصــف وتأجلــت إلــى يــوم الثالثــاء ‪1434/11/18‬ه ـ وصلــى‬\n                         ‫اهلل علــى نبينــا محمــد حــرر يف ‪1434/10/11‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء ‪1434/11/18‬ه ـ الســاعة‬\n‫التاســعة والنصــف افتتحــت اجللســة وفيهــا حضــر املدعــي العــام‪........ /‬‬\n‫وحضــر حلضــوره املدعــى عليــه‪ ،......... ... /‬وبســؤال املدعى عليه احلاضر‬\n‫عــن إجابتــه التــي اســتمهل مــن أجلهــا قــدم مذكــرة جوابيــة مكونــة مــن‬\n‫ثــاث صفحــات باســم احملامــي ‪ ........‬ونصهــا حرفيـ ًا مــا يلــي‪( :‬بصفتــي‬\n‫احملامــي والوكيــل الشــرعي عــن موكلــي‪ ، .... /‬ســعودي اجلنســية‬\n‫أوضــح لفضيلتكــم اآلتــي‪ :‬يف اجللســة‬     ‫مبوجــب ســجل مدنــي (‪ّ )...........‬‬\n‫املدعــي مــن مســتندات ضــد‬            ‫املاضيــة ُطلــب م ّنــا الــرد علــى مــا ّ‬\n                                 ‫قدمــه ّ‬\n‫موكلنــا‪ ،‬وهــي أقــوال لبعــض الســجناء حــول الدعــوى‪ ،‬وجواب ـ ًا علــى‬       ‫ّ‬\n\n                                                                                            ‫‪184‬‬\n\f      ‫هــذه املســتندات نفيدكــم مبــا يلــي‪-:‬أوالً‪:‬إن أقــوال املتهمــن املســاجني‬\n      ‫ضــد بعضهــم ال تعتبــر أدلــة معتبــرة ألن أقوالهــم وإقراراتهــم قاصــرة على‬\n      ‫أنفســهم‪ ،‬واملتهــم يدفــع عــن نفســه رغبــة ورهبــة وال يخلــوا مــن التعـ ّـرض‬\n      ‫لإلكــراه أو التأثيــر يف إرادة أو احلــرص علــى جلــب منفعــة لنفســه أو‬\n      ‫دفــع مضـ ّـرة فــا يصــح االعتمــاد علــى مثــل هــذه األقــوال‪ .‬ثاني ـاً‪ :‬كمــا‬\n      ‫أبــن لفضيلتكــم أن شــهادة الشــهود التــي يســتند إليهــا املدعــي العــام‬\n      ‫ال‬‫باطلــة يف األصــل‪ ،‬ويوجــد بهــا الكثيــر مــن التناقضــات بــن أقوال ك ً‬\n      ‫مــن الشــاهدين ‪ ،....‬و‪ ،......‬فالشــاهد األول‪ ،......../‬يف بدايــة اعترافــه‪،‬‬\n      ‫اعتــرف بأنهــم يف األصــل ذهبنــا يف رحلــة صيــد‪ ،‬ثــم بعــد الضغــط‬\n      ‫عليــه مــن قبــل احملققــن وممارســة اإلكــراه عليــه‪ ،‬وإقناعــه جبــر ًا‬\n      ‫باعترافــات الشــاهد الثانــي اعتــرف باآلتــي‪ :‬أنــه طلــب مــن موكلــي بــأن‬\n      ‫يقــوم بإيصالهــم بســيارته إلــى منطقــة احلــدود الشــمالية للقــاء شــخص‬\n      ‫هنــاك‪ ،‬ثــم عــادوا إلــى الدمــام يف نفــس اليــوم علــى ســيارة ‪ ....‬وصــادق‬\n      ‫علــى ذلــك‪ ،‬ولــم تكــن الســيارة لونهــا أبيــض كمــا ذكــر‪ ،‬فهــذا مــن‬\n      ‫التناقضــات التــي تبطــل شــهادته‪ ،‬فكيــف على أنســان يذهب يف ســيارة‬\n      ‫مــن الدمــام إلــى احلــدود الشــمالية وهــو لــم يعــرف لونهــا‪ ،‬وهــذه بينــة‬\n      ‫واضحــة علــى بطــان تلــك الشــهادة التــي يســتند إليهــا املدعــي العــام‪.‬‬\n      ‫علم ـ ًا بــان احملقــق أثنــاء التحقيــق عــرض علــى موكلــي موافقــة قــول‬\n      ‫‪ ،......‬بأنهــم ذاهبــن إلــى رحلــة صيــد أو املوافقــة علــى قــول الشــاهد‬\n      ‫الثانــي ‪ ،.........‬فرفــض موكلــي هــذا البهتــان والظلــم‪ .‬أمــا بالنســبة‬\n      ‫لشــهادة الثانــي‪ ،......... /‬فذكــر يف شــهادته بــأن موكلــي ميلــك ســيارة‬\n      ‫نــوع ‪ ،....‬وهــذه مــن التناقضــات التــي تبطــل تلــك الشــهادة‪ ،‬وهنــا يتبــن‬\n      ‫لفضيلتكــم التناقــض الواضــح بــن شــهادة املذكوريــن‪ ،‬وبطالنهــا‬\n\n\n‫‪185‬‬\n\f‫وعــدم صحــة االســتناد إليهــا‪ ،‬وقــد ذكــر هــذا يف محضــر املواجهــة‬\n‫إمــام احملقــق‪ ،‬وقــد طلــب موكلــي مــن احملقــق تدوينــه يف دفتــر املواجهــة‬\n‫الــذي حصلــت إمــام احملقــق بــن موكلــي وبــن الشــاهد الثانــي‪،...../‬‬\n‫ودونــة آنــذاك‪ .‬ثالثـاً‪ :‬كمــا أود لفــت أنتبــاه فضيلتكــم بــأن هنــاك ثالثــة‬\n‫ال مــن املذكوريــن‬  ‫أشــخاص مذكوريــن بأننــي قمــت بنقلهــم بجانــب ك ً‬\n‫ال مــن(‪ ،......‬و‪،......‬‬\n                       ‫الــذي أســتند إليهــم املدعــي العــام يف دعــواه وهــم ك ً‬\n‫و‪ ،)......‬فمــن العجيــب أن لــم يتــم حضورهــم واالســتناد إلــى شــهادتهم‬\n‫يف تلــك الواقعــة‪ ،‬بالرغــم مــن أنهــم أشــخاص رئيســن يف تلــك الواقعــة‪.‬‬\n‫وأخيــراً‪ :‬أفيــد فضيلتكــم أن دعــوى املدعــي العــام مرفوضــة جمل ـ ًة‬\n‫وتفصيـاً‪ ،‬كمــا أبــن لفضيلتكــم أن موكلــي لــم يســتوقف علــى أثــر‬\n‫هــذه القضيــة يف األصــل بــل اســتوقف علــى أثــر تعميــم قــدمي لــم ترفعــه‬\n‫عنــه إدارة املباحــث‪ ،‬وحــن ذهابــه للســفر فوجــئ بذلــك‪ ،‬وأثنــاء أســتالم‬\n‫املباحــث ملوكلــي مــن اجلــوازات‪ ،‬وحتويلــه إلــي قســم اإلدارة أخبــروه‬\n‫املباحــث أنــه تعميــم قــدمي‪ ،‬وأننــا لــم نرفعــه‪ ،‬ومبجــرد حضــور كفيــل‬\n‫لــك ســوف يتــم خروجــك‪ ،‬وبســبب رفــض موكلــي لنظــام الكفيــل‪،‬‬\n‫وأنــه لــم يقــم بشــيء مخالــف كان هــذا الســبب إليقافــه وســجنه‪ ،‬كمــا‬\n‫أضيــف لفضيلتكــم قصــة إيقافــه كاملــة حيــث قــال موكلــي (لقــد‬\n‫كنــت أتــردد علــى وزارة الداخليــة و ملــدة خمــس ســنوات أطالــب بعــدة‬\n‫طلبــات مــن أهمهــا العــاج خــارج اململكــة و قــد أبلغنــي د‪ .... .‬مديــر‬\n‫مكتــب التنســيق بالــوزارة أن أراجــع جــوازات الدمــام و اســتخرج جــواز‬\n‫الســفر اخلــاص بــي حتــى يتــم لــي الســفر خــارج اململكــة علــى نفقــة وزارة‬\n‫الداخليــة و بعــد ترتيــب أمــوري ذهبــت إلــى جــوازات الدمــام مستبشــر ًا‬\n‫خيــر ًا بتاريــخ ‪ 1432/4/1‬ه ـ بنــاء علــى توجيــه الدكتــور‪ .....‬وعندمــا‬\n\n\n                                                                                      ‫‪186‬‬\n\f      ‫راجعـ ــت اجلـ ــوازات تفاجــأت بأنــه علــي تعميـ ــم مــن املباح ـ ــث وألقــي‬\n      ‫القبــض علــي بــد ًال مــن العــاج الــذي كنــت أنتظــره و مت حتويلــي إلــى‬\n      ‫قســم املباحــث الواقــع يف حــي ‪ ...........‬بالدمــام و عنــد وصولــي إليــه‬\n      ‫أخبرنــي الضاب ــط الــذي أحضرنــي مــن اجلــوازات و قــال لــي « إننــا‬\n      ‫جبنــاك باخلطــأ بســبب تعميــم قــدمي عليــك لــم نرفعــه عنــك و قــد اتصلنــا‬\n      ‫بقريبــك ‪.....‬ليكفلــك» و قلــت لــه ملــاذا يكفلنــي و أنــا لــم أفعــل شــيئ ًا‬\n      ‫و قــال لــي «وصلــت الرســالة» و ذهــب عنــي وكان قريبــي قــد وصــل‬\n      ‫إلــى البــاب اخلارجــي يف نفــس القســم فخــرج إلي ــه أح ــد العسـاك ــر فقال‬\n      ‫لــه «املوضــوع تطــور روح و بعديــن نتصــل عليــك» وبعــد ســاعتني جاءنــي‬\n      ‫ضابــط آخــر و قــال لــي «ســوف يتــم حتويلــك إلــى شــعبة التحقيــق» وقلــت‬\n      ‫لــه ملــاذا فقــال الضابــط و بهــذا اللفــظ «أنــا أوريــك» و بالفعــل مت حتويلــي‬\n      ‫إلــى الســجن وقامــت فرقــة مــن املباحــث مبداهمــة منازلــي حاملــن معهــم‬\n      ‫البنــادق الرشاشــة أمــام اجليــران و كذلــك أمــام أطفالــي داخــل املنــزل و‬\n      ‫معهــم امــرأة مفتشــة و مت إغــاق أحــد الغــرف عليهــا مــع زوجاتــي وأبنائي‬\n      ‫ا حتى غرف النوم وأغراض نســائي‬           ‫وقــام الرجــال بتفتيــش املنــزل كامـ ً‬\n      ‫وبناتــي اخلاصــة ونشــرت املالبــس خــارج أماكنهــا هــذا فيمــا يخــص‬\n      ‫املنــزل األول الــذي كانــت أســرتي مجتمعــة فيــه و أمــا املنــزل اآلخــر‬\n      ‫الــذي لــم يوجــد فيــه أحــد فلــم تدخلــه املفتشــة وحصــل لــه مثــل املنــزل‬\n      ‫األول وزاد بتكســير البــاط وأمــا أنــا فحقــق معــي ومكثــت أحــد عشــر‬\n      ‫شــهر ًا منهــا خمســة أشــهر وعشــرة أيــام انفــرادي علم ـ ًا بــأن املتحــدث‬\n      ‫الرســمي بــوزارة الداخليــة قــد صــرح ســابق ًا يف بعــض وســائل اإلعــام‬\n      ‫أن الســجني إذا أمضــى ســتة أشــهر ولــم يثبــت عليــه شــيء يوضــع حتــت‬\n      ‫احملقــق خطوط ـ ًا ويطلــق ســراح الســجني ويتــم تعوضــه وأمــا أنــا فقــد‬\n\n\n‫‪187‬‬\n\f‫أمضيــت أحــد عشــر شــهر ًا ولــم أعلــم بتهمتـ ــي ول ـ ــم أصـ ــدق علـ ــى شـ ــيء‬\n‫وزيـ ــادة علــى ذلــك عنــد اإلفــراج وقعونــي علــي أن قضيتــي هــو اتصــال‬\n‫علــى رقــم مشــبوه!)‪ ،‬علم ـ ًا بــأن موكلــي قــد رفعهــا مــن داخــل الســجن‬\n‫عــن طريــق إدارة الســجن‪ .‬ومــا جــاء يف دعــوى املدعــي بهتــان وغيــر‬\n‫صحيــح ‪ ،‬وعليــه وهدي ـ ًا علــى مــا قدمــت مــن اجلــواب والدفــاع املشــروع‬\n‫عــن موكلــي‪ ،‬ومتســك ًا بقاعــدة البــراءة األصليــة أطلــب احلكــم بــرد‬\n‫دعــوى املدعــي وطلباتــه املجحفــة‪ ،‬وأطلــب إخــاء ســبيل موكلــي مــن‬\n‫هــذه الدعــوى) إلبــراء الذمــة ورفــع الظلــم‪ ،‬والســام عليكــم ورحمــة‬\n‫اهلل وبركاتــه ‪ ،،،‬احملامــي‪ ...... :‬ســجل مدنــي رقــم ‪ ) ..... ( :‬ترخيــص‬\n‫وزارة العــدل رقــم ‪ ........... :‬انتهــى‪ .‬وبعــرض ذلــك علــى املدعــي العــام رد‬\n‫قائـاً‪ :‬أمتســك مبــا ورد يف الئحــة الدعــوى هكــذا رد‪ ،‬وبســؤال املدعــي‬\n‫العــام واملدعــى عليــه هــل لديكمــا أي إضافــة غيــر مــا تقــدم فأجــاب‬\n‫املدعــي العــام قائ ـاً‪ :‬أكتفــي مبــا قدمتــه مــن أدلــة مرصــودة هكــذا‬\n‫ـدي إضافــة غيــر مــا تقــدم‪-‬‬  ‫أجــاب‪ ،‬وأجــاب املدعــى عليــه قائـاً‪ :‬ليــس لـ َّ‬\n‫هكــذا قــرر‪ -‬لــذا جــرى قفــل بــاب املرافعــة‪ ،‬ورفعــت اجللســة للتأمــل‪،‬‬\n‫وأقفلــت الســاعة التاســعة وخمســن دقيقــة وتأجلــت إلــى يــوم األربعــاء‬\n‫‪1435/1/3‬ه ـ وصلــى اهلل علــى نبينــا محمــد حــرر يف ‪1434/11/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األربعــاء ‪1434/11/19‬ه ـ الســاعة‬\n‫العاشــرة افتتحــت اجللســة وفيهــا حضــر املدعــي العــام‪ ...../‬وحضــر‬\n‫حلضــوره املدعــى عليــه‪ ، .. . . /‬فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n‫العــام وإجابــة املدعــى عليــه بإنــكار مــا نســب إليــه يف الدعــوى‪،‬‬\n‫ولكــون املدعــي العــام لــم يقــدم بينــة علــى دعــواه وقــرر اكتفــاءه‬\n‫مبــا قدمــه يف املجلــس الشــرعي‪ ،‬ومــا قدمــه املدعــي العــام ال يناهــض‬\n\n\n                                                                                         ‫‪188‬‬\n\f      ‫البــراءة األصليــة‪ -‬ومــن املقــرر شــرع ًا أن األصــل بــراءة الذمــة‪ -‬وبعــد‬\n      ‫التأمــل والدراســة ألوراق القضيــة؛ لذلــك فلــم يثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه ‪ ...............‬مبــا نســب إليــه يف الدعــوى وأخليــت ســبيله منهــا وبذلــك‬\n      ‫حكمــت‪ .‬وبإعــان احلكــم عليهمــا قــرر املدعــى عليــه بقولــه‪ :‬أنــا مقتنــع‬\n      ‫باحلكــم‪ ،‬كمــا قــرر املدعــي العــام بقولــه‪ :‬أنــا معتــرض علــى احلكــم‬\n      ‫بالئحــة اعتراضيــة هكــذا قــرر‪ ،‬فأفهمــت املدعــي العــام بــأن موعــد‬\n      ‫اســتالم نســخة مــن احلكــم يف هــذا اليــوم األربعــاء ‪1434/11/19‬ه ـ‬\n      ‫لتقــدمي اعتراضــه خــال ثالثــن يومـ ًا تبــدأ مــن تاريــخ االســتالم املذكــور‬\n      ‫وفقـ ًا للمــادة الرابعــة والتســعني بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫ويف حالــة انتهــاء املــدة دون تقــدمي اعتراضــه يتــم رفــع املعاملــة حملكمــة‬\n      ‫االســتئناف اجلزائيــة املتخصصــة بــدون الئحــة وفق ـ ًا للمــادة اخلامســة‬\n      ‫والتســعني بعــد املائــة مــن النظــام ســالف الذكــر وصلــى اهلل علــى نبينــا‬\n                                                   ‫محمــد حــرر يف ‪1434/11/19‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد ‪1434/11/23‬ه ـ فتحــت اجللســة‬\n      ‫الســاعة الثانيــة عشــرة وفيهــا حضــر املدعــي العــام وجــرى تســليمه‬\n      ‫نســخة مــن قرارنــا رقــم (‪ )................‬وتاريــخ ‪1434/11/20‬ه ـ لتقــدمي‬\n      ‫اعتراضــه عليــه يف الوقــت احملــدد نظامـ ًا وصلــى اهلل علــى نبينــا محمــد‬\n      ‫وحــرر يف ‪1434/11/23‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد ويف يــوم األحــد‬\n      ‫‪1434/12/22‬ه ـ افتتحــت اجللســة الســاعة التاســعة وخمســن دقيقــة‬\n      ‫وقــد وردتنــا الئحــة اعتراضيــة مــن املدعــي العــام قيــدت بهــذه احملكمــة‬\n      ‫برقــم ‪ 34/22285‬يف ‪1434/12/18‬ه ـ مكونــة مــن ثــاث صفحــات‬\n      ‫ولــم أجــد فيهــا مــا يؤثــر علــى احلكــم وجــرى إرفاقهــا باملعاملــة وقــررت‬\n      ‫رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف اجلزائيــة املتخصصــة‬\n\n\n‫‪189‬‬\n\f‫لتدقيــق احلكــم حســب املتبــع‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم حــرر يف ‪1434/12/22‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا القاضــي‪ ...........‬باحملكمــة اجلزائيــة‬\n‫املتخصصــة القائــم بعمــل فضيلــة القاضــي ‪ .....‬أثنــاء انتدابــه يف‬\n‫مهمــة رســمية خــارج اململكــة ويف يــوم األحــد ‪1435/1/21‬ه ـ فتحــت‬\n‫اجللســة الســاعة العاشــرة وعشــرة دقائــق وقــد عــادت املعاملــة مــن‬\n‫محكمــة االســتئناف اجلزائيــة املتخصصــة باخلطــاب ‪ 34/2102‬وتاريــخ‬\n‫‪1435/1/15‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n‫املتخصصــة املســاعد برقــم ‪ 35/1106‬وتاريــخ ‪1435/1/15‬هـ‪ ،‬واملتعلق‬\n‫بالدعــوى العامــة ضــد‪ ، /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪ ، )...........‬وقــد ُظ ّهــر القــرار مبــا نصــه ‪ ( :‬فقــد اطلعنــا علــى هــذا القرار‬\n‫رقــم ‪ 4/34/35‬وتاريــخ ‪1434/11/20‬ه ـ الصــادر مــن فضيلــة الشــيخ‬\n‫‪ ............/‬وأصدرنــا القــرار رقــم ‪/1/74‬ص وتاريــخ ‪1435/1/11‬ه ـ‬\n‫املتضمــن املصادقــة علــى احلكــم‪ .‬واهلل املوفــق )‪ .‬لــذا جــرى إحلاقــه حتــى‬\n    ‫ال يخفــى وصلــى اهلل علــى نبينــا محمــد ‪،‬حــرر يف ‪1435/1/21‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                            ‫‪190‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":175,"source_page_end":190,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"719adf4325239d7cf979a2a711b722f86cf430a98d738538823a37fc934d6b31","normalized_text_hash":"7ae2a42ec6391691c124ddf4b935af12becbee9ab521665aa4678400eeeebfd9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p175-3233216"},{"id":"c7f4d3dd-2ab9-5ccd-95b8-d3f588a9bbde","document_type":"judgment","category":"judicial","subcategory":"general","title":"اإلخال بأمن الوطن -عدم اإلخبار عن واقعة متس أمن الباد - التعزير باعتباره مخالفا للنظام وليس متخابرا مع دولة أجنبية -اإلقرار كل ال يتجزأ.","document_number":"11/34/1","case_number":"189","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بعد التعديل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"اإلخال بأمن الوطن -عدم اإلخبار عن واقعة متس أمن الباد - التعزير باعتباره مخالفا للنظام وليس متخابرا مع دولة أجنبية -اإلقرار كل ال يتجزأ.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 11/34/1 :‬تاريخه‪1434/5/4 :‬هـ‬\n          ‫رقم الدعوى‪ 189 :‬رقم قرار التصديق من‬\n      ‫محكمة االستئناف‪/2/364 :‬ص‪1434/10/7/‬‬\n                         ‫تاريخه‪1434/08/14 :‬هـ‬\n\n\n      ‫اإلخــال بأمــن الوطــن ‪ -‬عــدم اإلخبــار عــن واقعــة متــس أمــن البــاد ‪-‬‬\n      ‫التعزيــر باعتبــاره مخالفــا للنظــام وليــس متخابــرا مــع دولــة أجنبيــة‬\n                                                         ‫‪ -‬اإلقــرار كل ال يتجــزأ‪.‬‬\n\n\n\n\n                            ‫املادة (‪ )194‬و (‪ )195‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بارتكابــه جرميــة تخابــره مــع‬\n      ‫اســتخبارات دولــة أخــذت موقف ـ ًا معادي ـ ًا للمملكــة آنــذاك وذلــك‬\n      ‫مبقابلتــه ببعــض مســؤولي االســتخبارات فيهــا واتفاقــه معهــم علــى‬\n      ‫دخولــه اململكــة وتقــدمي املعلومــات عــن أعــداد اجليــش والقواعــد‬\n      ‫األمريكيــة ومواقعهــا أثنــاء الغــزو العراقــي للكويــت حيــث مت‬\n      ‫القبــض علــى املذكــور مــن قبــل اجلهــات املختصــة لعالقتــه بقضيــة‬\n      ‫تهريــب املخــدرات بالطائــرة الشــراعية وعالقتــه باملخابــرات ‪....‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــور هــو فعــل محــرم ومعاقــب عليــه‬\n                     ‫شــرع ًا وموجــب مــن موجبــات التعازيــر لــذا يطلــب‪-:‬‬\n                                               ‫‪ -1‬إثبات ما أسند إليه شرع ًا ‪.‬‬\n         ‫‪ -2‬احلكم عليه بعقوبة تعزيرية شديدة زاجرة له ورادعه لغيره‪.‬‬\n      ‫‪ -3‬احلكــم مبنعــه مــن الســفر اســتناد ًا للمــادة السادســة الفقــرة‬\n‫‪191‬‬\n\f‫الثانيــة مــن نظــام وثائــق الســفر‪ ،‬وقــد أجــاب املدعــى عليــه باملصادقــة‬\n‫ا وأن غرضــه مــن املوافقــة علــى عــرض‬     ‫علــى الدعــوى جملــة وتفصي ـ ً‬\n‫االســتخبارات كان بقصــد العــودة إلــى بــاده وليــس لــه قصــد آخــر‬\n‫وأنــه لــم يقــم بــإدالء أي معلومــات لالســتخبارات ولــم يرجــع للعــراق‬\n‫بعــد خروجــه منهــا ‪ ،‬ومبــا أن املدعــي العــام لــم يدعــي علــى املدعــى‬\n‫عليــه بتزويــد االســتخبارات مبعلومــات عمــا طلبتــه منــه ولــم يدعــي‬\n‫أنــه جتســس لصالــح تلــك اجلهــة ومبــا أن املدعــى عليــه ذكــر بــأن‬\n‫موافقتــه علــى مــا عرضتــه عليــه االســتخبارات إمنــا كان رغبــة منــه‬\n‫يف العــودة إلــى بــاده وأنــه لــم يقــم بالتجســس لتلــك الدولــة وإقــراره‬\n‫املذكــور ليــس فيــه مــا يدينــه بخصــوص التجســس واإلقــرار كل‬\n‫ال يتجــزأ ‪ -‬لذلــك كلــه لــم يثبــت إدانــة املدعــى عليــه مبــا نســبه‬\n‫إليــه املدعــي العــام يف دعواه‪،‬ومبــا أن املدعــى عليــه لــم يخبــر‬\n‫اجلهــات املختصــة يف هــذا البلــد بعــد دخولــه مبــا حصــل‪ ،‬لذلــك‬\n‫قضــت احملكمــة باحلكــم بتعزيــره علــى ذلــك بســجنه ســتة أشــهر‬\n‫اعتبــار ًا مــن تاريــخ إيقافــه ‪ .‬صــدق احلكــم مــن محكمــة االســتئناف‬\n                                                               ‫بعــد التعديــل‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة‬\n‫ـاء علــى املعاملــة الــواردة مــن هيئــة التحقيــق‬\n                                                 ‫اجلزائيــة املتخصصــة بنـ ً‬\n‫واإلدعــاء العــام برقــم هــ‪ 7515/24‬وتاريــخ ‪1434/2 /23‬ه ـ واملقيدة‬\n‫باحملكمــة بالقيــد رقــم ‪ 34/8093‬وتاريــخ ‪1434/4/22‬ه ـ احملالــة‬\n‫لنــا مــن فضيلــة الرئيــس برقــم ‪ 189‬وتاريــخ ‪1434/4/22‬ه ـ‬\n\n                                                                                  ‫‪192‬‬\n\f      ‫واملتعلقــة بدعــوة املدعــي العــام ضــد املدعــى عليــه ‪ ...‬ففــي يــوم‬\n      ‫الســبت املوافــق ‪1434/5/11‬ه ـ افتتحــت اجللســة األولــى يف الســاعة‬\n      ‫العاشــرة والنصــف وفيهــا حضــر املدعــي العــام ‪ ...‬وحضــر حلضــوره‬\n      ‫املدعــى عليــه‪ ...‬ســعودي اجلنســية يحمــل بطاقــة الهويــة الوطنيــة‬\n      ‫ا يف دعــواه (بســم اهلل الرحمــن‬     ‫رقــم ‪ ...‬وادعــى املدعــي العــام قائ ـ ً‬\n                                                  ‫الرحيــم (الئحــة دعــوى عامــة)‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪:‬‬\n      ‫بصفتــي مدعي ـ ًا عام ـ ًا بهيئــة التحقيــق واالدعــاء العــام أدعــي علــى‬\n      ‫‪ ،...‬تاريــخ امليــاد‪1363 :‬هــ‪ ،‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم (‪ ،)...‬احلالــة االجتماعيــة متــزوج ‪ ،‬املؤهــل التعليمــي ‪:‬‬\n      ‫أمــي‪ ،‬املوقــوف ســابقا بتاريــخ ‪1432/11/13‬ه ـ ‪ .‬وذلــك الرتكابــه‬\n      ‫جرمية تخابره مع استخبارات دولة أخذت موقف ًا معادي ًا للمملكة‬\n      ‫آنــذاك وذلــك مبقابلتــه بعــض مســؤولي االســتخبارات فيهــا واتفاقــه‬\n      ‫معهــم علــى دخولــه اململكــة وتقــدمي املعلومــات عــن إعــداد اجليــش‬\n      ‫والقواعــد األمريكيــة ومواقعهــا أثنــاء الغــزو العراقــي للكويــت‪.‬‬\n      ‫حيــث مت القبــض علــى املذكــور بالتاريــخ املنــوه عنــه أعــاه مــن‬\n      ‫قبــل اجلهــات املختصــة لعالقتــه بقضيــة تهريــب املخــدرات بالطائــرة‬\n      ‫الشــراعية وعالقتــه باملخابــرات ‪ . ....‬وباســتجوابه أقــر أنــه ســافر‬\n      ‫خمــس ســفرات لــأردن وســفرتني لســوريا (اليذكــر تواريخهــا) أمــا‬\n      ‫العــراق فقــد ســافر إليــه قبــل أحــداث حــرب العــراق علــى الكويــت‬\n      ‫بثالثــة أشــهر تقريبـ ًا مــن أجــل أن يقــوم باســترداد مبالــغ ماليــه لــه‬\n      ‫بذمــة (‪ )...‬ثمــن مكائــن آيــس كــرمي وقطــع ســجاد وأكيــاس‬\n      ‫بالســتك باعهــا لــه بقيمــة (‪ )180.000‬مائــة وثمانــن ألــف ريــال‬\n\n\n‫‪193‬‬\n\f‫تقريبـ ًا حيــث قــام بتقــدمي دعــواه تلــك للجهــات املعنيــة وبقــى هنــاك‬\n‫ملــدة ثــاث أشــهر يتابــع موضوعــه ‪ -‬ويف تلــك الفتــرة مت اجتيــاح‬\n‫العــراق للكويــت وســافر إلــى الكويــت للخــروج منهــا للمملكــة‬\n‫إ ّال أنــه قبــض عليــه هنــاك مــن قبــل اجليــش العراقــي‪ .‬وبعــد القبــض‬\n‫عليــه لــم يكــن معــه أي إثبــات لهويتــه الســعودية وأبلــغ اجليــش‬\n‫العراقــي أن اســمه‪ .../‬مــن باديــة العــراق وأن أســرته تقيــم باململكــة‬\n‫وقــد أوقــف لديهــم ثــم أحيــل إلــى ســجن البصــرة ثــم لســجن بغــداد‬\n‫وأســتقر بــه احلــال يف ســجن الرمــادي ملــدة ســتة أشــهر ‪ .‬وأنــه خــال‬\n‫ســجنه بالرمادي يف العراق كان يتردد عليهم أشــخاص عراقيون‬\n‫يســألونهم عــن وضعهــم يف الســجن وعــن اإلعاشــة ويف إحــدى‬\n‫املــرات طلــب أحدهــم االجتمــاع بــه يف أحــد املكاتــب بالســجن‬\n‫وأخبــره أنــه مــن االســتخبارات العراقيــة ويرغــب أن يتعــاون معهــم‬\n‫بــأن يذهــب إلــى الســعودية ويزودهــم بأعــداد اجليــش والقواعــد‬\n‫األمريكيــة ومواقعهــا وأن عليــه أن يقــدم املعلومــات لهــم خــال‬\n‫مــدة عشــرة إلــى عشــرين يوم ـ ًا حيــث يعــود ويســلم نفســه ألي‬\n‫مركــز حــدودي بالعــراق ويطلــب مقابلــة االســتخبارات هنــاك‬\n‫وبالفعــل وافــق علــى ذلــك العــرض ‪ .‬وأفــاد بــأن االســتخبارات‬\n‫العراقيــة قامــت بإنزالــه بالقــرب مــن احلــدود الســعودية باجتــاه‬\n‫جديــدة عرعــر وتســلل مبفــرده الــى األراضــي الســعودية بطريقــة‬\n‫غيــر مشــروعة ســير ًا علــى األقــدام حتــى وصــل إلــى عرعــر ومنهــا‬\n‫ســافر إلــى الريــاض ويزعــم أنــه لــم يعــد إلــى العــراق بعــد خروجــه‬\n‫منهــا ولــم يــزود االســتخبارات العراقيــة بــأي معلومــات وصــادق علــى‬\n‫اقــراره شــرعاً‪ .‬وقــد أســفر التحقيــق عــن توجيــه اإلتهــام لــه مبــا‬\n\n\n                                                                                ‫‪194‬‬\n\f      ‫أســند إليــه وذلــك ملــا ورد باعترافــه املصــدق شــرع ًا املرفــق بــأوراق‬\n      ‫القضيــة‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا مــع علمــه بأهميتهمــا وســريتها للمحافظــة علــى‬\n      ‫األمــن واســتقرار البــاد ممــا يــدل علــى ســوء مســلكه وفســاد‬\n      ‫منهجــه ومخالفتــه ملــا أمــر اهلل بــه مــن الطاعــة الواجبــة لولــي األمــر‬\n      ‫مــع علمــه مبــدى أهميتهــا وســريتها للمحافظــة علــى أمــن وإســتقرار‬\n      ‫البــاد لقولــه تعالــى (وال جتسســوا) ســورة احلجــرات آيــة ‪12‬‬\n      ‫واملذكــور خــان الوطــن بهــذا الفعــل وأبــدى اســتعداده للعمــل مــع‬\n      ‫اســتخبارات دولــة معاديــة بتقــدمي معلومــات يف غايــة األهميــة تتعلــق‬\n      ‫باجليــش والقواعــد العســكرية يف زمــن احلــرب وملــا لهــذه اخليانــة‬\n      ‫مــن أثــر عظيــم علــى العبــاد والبــاد وتعريــض مصالــح األمــة ألعظــم‬\n      ‫األخطــار يف زمــن احلــرب وهــو مخالــف للنصــوص الشــرعية ومــن‬\n      ‫ذلــك قولــه تعالــى (يــا أيهــا الذيــن أمنــوا ال تخونــوا اهلل والرســول‬\n      ‫وتخونــوا أماناتكــم وأنتــم تعلمــون) ســورة األنفــال آيــة ‪ . 27‬وال‬\n      ‫شــك أن مــا أقــدم عليــه املذكــور مبــا يخــدم مصلحــة دولــة معاديــة‬\n      ‫فيــه إضــرار كبيــر وبــاب مــن أبــواب الفســاد ومــا قــام بــه املذكــور‬\n      ‫إمنــا جــاء عــن قصــد جنائــي متثــل يف خدمــة أعــداء البــاد ومواالتهــم‬\n      ‫ومســاعدتهم يف أفعالهــم‪ .‬وقــد حــذر الرســول صلــى اهلل عليــه‬\n      ‫وســلم مــن اخليانــة فقــال (آيــة املنافــق ثــاث ‪ ...‬وإذا أؤمتــن خــان)‬\n      ‫وقولــه (ال إميــان ملــن ال أمانــة لــه)‪ .‬وحيــث إن مــا أقــدم عليــه‬\n      ‫املذكــور هــو فعــل محــرم ومعاقــب عليــه شــرع ًا وموجــب مــن‬\n      ‫موجبــات التعازيــر لــذا أطلــب ‪ -1 -:‬إثبــات مــا أســند إليــه شــرعاً‪.‬‬\n      ‫‪ -2‬احلكــم عليــه بعقوبــة تعزيريــة شــديدة زاجــرة لــه ورادعــه لغيــره‪.‬‬\n\n\n‫‪195‬‬\n\f‫‪ -3‬احلكــم مبنعــه مــن الســفر اســتناد ًا للمــادة السادســة الفقــرة‬\n‫الثانيــة مــن نظــام وثائــق الســفر‪ .‬وبــاهلل التوفيق)أ‪.‬هـ ـ هــذه دعــواي‪،‬‬\n‫ثــم جــرى ســؤال املدعــى عليــه اجلــواب عــن الدعــوى بعــد إعالمــه‬\n‫بــأن لــه احلــق يف اإلجابــة عــن الدعــوى بنفســه حــاال مشــافهة أو‬\n‫ـام أو وكيــل للدفــاع‬ ‫اإلجابــة مكتوبــة ولــه احلــق يف االســتعانة مبحـ ً‬\n‫ا كل مــا ذكــره املدعــي العــام يف دعــواه‬          ‫عنــه فأجــاب قائ ـ ً‬\n‫ا وأفيــد فضيلتكــم بــأن غرضــي مــن‬           ‫صحيــح جملــة وتفصي ـ ً‬\n‫املوافقــة علــى عــرض االســتخبارات العراقيــة كان بقصــد العــودة‬\n‫إلــى بــادي وليــس لــي قصــد آخــر كمــا أفيدكــم بأننــي لــم أقــم‬\n‫بــإدالء أي معلومــات لالســتخبارات العراقيــة ولــم أرجــع للعــراق بعــد‬\n‫خروجــي منهــا يف ذلــك التاريــخ هــذا إجابتــي وباالطــاع علــى‬\n‫املعاملــة وجــدت علــى اللفــة رقــم (‪)12‬ملــف حتقيــق وفيهــا علــى‬\n‫الصفحــة رقــم (‪ )8.7.6.5‬إقــرار للمدعــى عليــه املصــدق شــرع ًا مبــا‬\n‫نســبه إليــه املدعــي العــام يف دعــواه ونصــه‪( :‬أقــرار خطــي بتاريــخ‬\n‫‪ 24‬ـ ـ ‪1433/1/25‬ه ـ أقــر أنــا املدعــو‪... /‬ـ ســعودي اجلنســية ـ‬\n‫مبوجــب الهويــة رقــم ‪...‬والصــادرة مــن أحــوال رفحــاء وأنــا بكامــل‬\n‫قــواي العقليــة املعتبــرة شــرع ًا مبــا يلــي‪ /1 :‬أقــر بــأن أســمي‬\n‫احلقيقــي هــو ‪ ... /‬وال أحمــل بهــذا االســم أي جنســية ومــن مواليــد‬\n‫الرطبة بالعراق ونشأت يف بادية العراق واألردن وسوريا والسعودية‬\n‫ا بينهــا حتــى بلــغ عمــري عشــرون عام ـ ًا ‪ /2 .‬أقــر بأنــي‬     ‫متنق ـ ً‬\n‫عندمــا بلغــت عشــرون عامـ ًا مــن العمــر قدمــت مــع أســرتي وكنــا‬\n‫يف منطقة احلزول جنوب غرب محافظة رفحاء (منطقة صحراوية)‬\n‫وبعــد وفــاة والــدي ذهبــت إلــى شــخص يف رفحــاء يدعــى ‪...‬وال‬\n\n\n                                                                                ‫‪196‬‬\n\f      ‫أعــرف بقيــة أســمه وعرفتــه علــى نفســي باســم ‪ ... /‬وطلبــت منــه‬\n      ‫أن يســاعدني يف اســتخراج بطاقة هوية لي حيث قام مبســاعدتي‬\n      ‫وذهــب معــي إلــى مكتــب أحــوال محافظــة رفحــاء يف ذلــك الوقــت‬\n      ‫واســتخرجت بطاقــة أحــوال باســم ‪ ... /‬وبتعريــف مــن أحــد مشــايخ‬\n      ‫قبيلــة شــمر يدعــو ‪ ... /‬وبشــهادة ‪ /3...‬أقــر بأنــي منــذ أن حصلــت‬\n      ‫علــى اجلنســية الســعودية ‪1388‬ه ـ باســم ‪... /‬وأنــا أســتخدم هــذا‬\n      ‫االســم يف جميــع التعامــات ‪/4‬أقــر بأنــي بعــد حصولــي علــى بطاقة‬\n      ‫األحــوال اســتخرجت جــواز ســفر وســافرت إلــى الكويــت للبحــث‬\n      ‫عــن عمــل وقــد عملــت ســائق لســيارة أجــرة خاصــة لــي ملــدة ســنتني‬\n      ‫وبعدهــا عــدت إلــى اململكــة واســتقريت يف مدينــة عرعــر وفتحــت‬\n      ‫ورشــة إلصــاح الســيارات وتوســعت يف هــذا النشــاط وتزوجــت مــن‬\n      ‫ابنــة عمــي ‪ /5 ... /‬أقــر بأنــي بعــد ذلــك انتقلــت إلــى مدينــة‬\n      ‫الريــاض ومارســت نشــاط جتــاري مماثــل ملــا كنــت أعمــل بــه يف‬\n      ‫عرعــر باإلضافــة إلــى أنــي قمــت بتأســيس مؤسســة جتاريــة باســمي‬\n      ‫وســلمتها لشــخص عراقي اجلنســية يدعى ‪ ... /‬للمتاجرة بها مقابل‬\n      ‫أن يســلمني مبلــغ ألفــن (‪ )2000‬ريــال شــهري ًا كمــا قمــت ببيــع‬\n      ‫مكائــن آيســكرمي وقطــع مــن الــزل ومــواد بالســتيكية (عبــارة‬\n      ‫عــن أكيــاس) مببلــغ (‪ )180.000‬مائــة وثمانــون ألــف ريــال علــى‬\n      ‫‪ ...‬املذكــور ولــم أســتلم املبلــغ وبقــي يف ذمتــه ‪ ...‬الــذي بعــد فتــره‬\n      ‫غــادر إلــى العــراق بعــد تراكــم الديــون املاليــة علــى املؤسســة ‪/6 -‬‬\n      ‫أقــر بأنــي ســافرت إلــى العــراق قبــل اجتيــاح العــراق للكويــت‬\n      ‫بثالثــة أشــهر عــن طريــق منفــذ جديــدة عرعــر ملطالبــة ‪ ...‬املذكــور‬\n      ‫باملبالــغ التــي بذمتــه لــي وقــد أقمــت يف بغــداد وتقدمــت للجهــات‬\n\n\n‫‪197‬‬\n\f‫املعنيــة مــن أجــل اســترداد املبالــغ أال أن ذلــك لــم يــؤدي ألي نتائــج‬\n‫وبعدهــا تقدمــت إلــى ســفارة اململكــة يف بغــداد بشــكوى ضــد ‪...‬‬\n‫املذكور ومت إحالتي إلى اخلارجية العراقية التي بدورها أوصلتني‬\n‫إلــى شــرطة بغــداد إال أننــي لــم أحصــل علــى حقــي منــه ‪ /7 -‬أقــر‬\n‫بأنــي بعــد يــوم أو يومــن مــن اجتيــاح العــراق للكويــت ســافرت‬\n‫إلــى الكويــت للخــروج منهــا إلــى اململكــة إال أنــه قبــض علــي مــن‬\n‫قبــل اجليــش العراقــي املتواجــد يف الكويــت ولــم يكــن بحوزتــي‬\n‫أي وثائــق رســمية تثبــت هويتــي الســعودية ‪ /8 -‬أقــر بأنــه عنــد‬\n‫القبــض علــي مــن قبــل اجليــش العراقــي أبلغتهــم أن اســمي هــو ‪/‬‬\n‫‪ ...‬وأنــي مــن باديــة العــراق وعائلتــي تســكن يف الســعودية وبعدهــا‬\n‫مت ترحيلــي مــع ســجناء إلــى ســجن البصــرة ثــم ســجن بغــداد ثــم‬\n‫معتقــل الرمــادي لألســرى وســجنت هنــاك ملــدة ســتة أشــهر تقريبـ ًا‬\n‫‪ /9 -‬أقــر بأنــه أثنــاء ســجني بالرمــادي كان يتــردد علينــا‬\n‫أشــخاص ال أعرفهم من الســلطات العراقية بالزي املدني يســألون‬\n‫عــن أوضاعنــا يف الســجن بشــكل عــام ويف إحــدى الزيــارات مت‬\n‫طلبــي ملقابلــة خاصــة بأحــد مكاتــب الســجن وأخبرونــي أنهــم مــن‬\n‫االســتخبارات العراقيــة ويرغبــون أن أتعــاون معهــم لتزويدهــم‬\n‫مبعلومــات عــن أعــداد اجليــش والقواعــد األمريكيــة ومواقعهــم يف‬\n‫الســعودية وأن أقدم املعلومات لهم خالل مدة عشــرة إلى عشــرون‬\n‫يومـ ًا وذلــك عــن طريــق تســليم نفســي ألي مركــز حــدودي عراقــي‬\n‫وأطلــب منهــم مقابلــة االســتخبارات وقــد وافقــت علــى طلبهــم ‪-‬‬\n‫‪ /10‬أقــر بأنــه بعــد إبالغــي لالســتخبارات العراقيــة مبوافقتــي علــى‬\n‫طلبهــم قامــوا بنقلــي بســيارة تابعــة لالســتخبارات العراقيــة وأنزلوني‬\n\n\n                                                                                ‫‪198‬‬\n\f      ‫بالقــرب مــن احلــدود العراقيــة الســعودية يف منطقــة قريبــة مــن منفــذ‬\n      ‫جديــدة عرعــر وتســللت إلــى اململكــة ســير ًا علــى األقــدام متجــاوز ًا‬\n      ‫احلــدود بطريقــة غيــر مشــروعة حتــى وصلــت إلــى عرعــر ومنهــا‬\n      ‫ســافرت إلــى الريــاض ‪ /11 -‬أقــر بأنــي لــم أعــد إلــى العــراق بعــد‬\n      ‫أن خرجــت منهــا ولــم أقــدم أي معلومــات لالســتخبارات العراقيــة‬\n      ‫عــن مــا طلــب منــي كمــا أوردت أعــاه ‪ /12 -‬أقــر بأنــه لــي أخ‬\n      ‫شــقيق وضعتــه بعــد وفــاة والــدي لــدى عمــي ‪...‬حيــث كان يبلــغ مــن‬\n      ‫العمــر ســنتني وتولــى عمــي ‪...‬تربيتــه حتــى بلــغ مــن العمــر ســتة‬\n      ‫عشــر وقــام باســتخراج هويتــه الوطنيــة باســم ‪... /‬وبعــد تشــكيل‬\n      ‫اللجنــة اخلاصــة بتعديــل أوضــاع أبنــاء الباديــة عــدل أســمه إلــى‬\n      ‫االســم احلقيقــي وهــو ‪... /‬وهــو موجــود حالي ـ ًا يف مدينــة حائــل ‪-‬‬\n      ‫‪ /13‬أقــر بــأن لــدي عــدد ســتة أبنــاء لــم أقــم بتســجيلهم لــدى‬\n      ‫اجلهــات املختصــة وهــو (‪...‬ـ ‪ ......‬ـ ‪...‬ـ ‪...‬ـ ‪ )...‬وال يحملــون أي أثبــات‬\n      ‫لهويتهــم ألن والدتهــم كانــت بعــد عودتــي مــن العــراق ‪ /14 -‬أقــر‬\n      ‫بأنــي بعــد عودتــي مــن العــراق بطريقــة غيــر مشــروعة لــم أبلــغ أي‬\n      ‫مــن اجلهــات األمنيــة برجوعــي إلــى اململكــة رغــم علمــي أنــي‬\n      ‫مطلــوب للجهــات األمنيــة وهــذا مــا لــدي وقــد أوكلــت احملقــق‬\n      ‫بكتابــة هــذا اإلقــرار عنــي وقــرأه علــي وعليــه أوقــع واهلل خيــر‬\n      ‫الشــاهدين‪ .‬املقــر مبــا فيــه ‪... /‬ـ بصمتــه) أ‪.‬ه ـ وبعــرض هــذا‬\n      ‫ا إن هــذا االعتــراف‬    ‫االعتــراف علــى املدعــى عليــه أجــاب عنــه قائـ ً‬\n      ‫صحيــح وصادقــت عليــه يف احملكمــة اجلزئيــة بالدمــام هكــذا قــال‬\n      ‫وبســؤال املدعــي العــام واملدعــى عليــه هــل لديهمــا مــا يريــدان‬\n      ‫ا ليــس لــدي مــا‬  ‫إضافتــه فأجــاب كل واحــد منهمــا مبفــرده قائـ ً‬\n\n\n‫‪199‬‬\n\f‫ـاء علــى مــا تقــدم مــن الدعــوى‬  ‫أريــد إضافتــه هكــذا قــاال فبنـ ً‬\n‫واإلجابــة ومبــا أن املدعــي العــام لــم يدعــي علــى املدعــى عليــه‬\n‫بتزويــد االســتخبارات العراقيــة مبعلومــات عمــا طلبتــه منــه ولــم‬\n‫يدعــي أنــه جتســس لصالــح تلــك اجلهــة ومبــا أن املدعــى عليــه ذكــر‬\n‫بــأن موافقتــه علــى مــا عرضتــه عليــه االســتخبارات العراقيــة إمنــا‬\n‫كان رغبــة منــه يف العــودة إلــى بــاده وأنــه لــم يقــم بالتجســس‬\n‫لتلــك الدولــة وإقــراره املذكــور ليــس فيــه مــا يدينــه بخصــوص‬\n‫التجســس واإلقــرار كل ال يتجــزأ لذلــك كلــه لــم يثبــت لــدي‬\n‫إدانــة املدعــى عليــه مبــا نســبه إليــه املدعــي العــام يف دعــواه وقــررت‬\n‫رد دعــوى املدعــي العــام لعــدم ثبوتهــا وأخليــت ســبيل املدعــى عليــه‬\n‫مــن هــذه الدعــوى وبذلــك حكمــت وبعــرض احلكــم علــى املدعــي‬\n‫العــام قــرر عــدم القناعــة باحلكــم وطلــب رفــع املعاملــة حملكمــة‬\n‫االســتئناف اجلزائيــة املتخصصــة بالئحــة فأجبتــه لطلبــه وأفهمتــه‬\n‫بأنــه ســوف يســلم نســخة مــن هــذا احلكــم بتاريــخ هــذا اليــوم وأنــه‬\n‫متــى مضــت املــدة احملــددة لالعتــراض دون تقــدمي الئحــة اعتــراض‬\n‫ســوف يرفــع احلكــم إلــى محكمــة االســتئناف اجلزائيــة املتخصصــة‬\n‫بــدون الئحــة اعتــراض إعمــا ًال للمادتــن رقــم (‪ )195-194‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة وقــرر املدعــى عليــه قناعتــه باحلكــم وبــه‬\n‫ختمــت اجللســة يف متــام الســاعة احلاديــة عشــر وعليــه جــرى التوقيــع‬\n‫وبــاهلل التوفيــق وصلــى اهلل تعالــى وبــارك وســلم علــى نبينــا محمــد‬\n                                                     ‫وآله وصحبه أجمعني‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي ‪ ...‬باحملكمــة اجلزائيــة‬\n‫املتخصصــة افتتحــت اجللســة الثانيــة يف الســاعة العاشــرة مــن يــوم‬\n\n\n                                                                                  ‫‪200‬‬\n\f      ‫األحــد ‪1434/5/5‬ه ـ املوافــق ‪2013/3/17‬م اخلاصــة بالدعــوى‬\n      ‫العامــة ضــد املدعــى عليــه ‪ ...‬وفيهــا حضــر املدعــي العــام ‪...‬‬\n      ‫وســلم لــه نســخة مــن قــرار احلكــم املســجل برقــم (‪)11/34/1‬‬\n      ‫وتاريــخ ‪1434/5/4‬ه ـ وأعلــم بــأن مــدة االعتــراض ثالثــون يوم ـ ًا‬\n      ‫تبــدأ مــن تاريــخ هــذا اليــوم ‪1434/5/5‬ه ـ وأنــه إذا لــم يقــدم‬\n      ‫الئحتــه االعتراضيــة خــال هــذه املــدة ســوف يرفــع احلكــم إلــى‬\n      ‫محكمــة االســتئناف اجلزائيــة املتخصصــة بــدون الئحــة اعتــراض‬\n      ‫خــال خمســة وأربعــن يوم ـ ًا مــن تاريــخ النطــق باحلكــم إعمــا ًال‬\n      ‫للمادتــن رقــم (‪ )195-194‬مــن نظــام اإلجــراءات اجلزائيــة وحــرر يف‬\n      ‫‪1434/5/5‬ه ـ وبــاهلل التوفيــق وصلــى اهلل تعالــى وبــارك وســلم علــى‬\n      ‫نبينــا محمــد وآلــه وصحبــه أجمعــن احلمــد هلل وحــده وبعــد يف يــوم‬\n      ‫األحــد ‪1434/6/4‬ه ـ افتتحــت اجللســة الثالثــة يف الســاعة الواحــدة‬\n      ‫ظهــر ًا وقــد وردتنــا الالئحــة االعتراضيــة املقدمــة مــن املدعــي العــام‬\n      ‫واملقيــدة باحملكمــة بالقيــد رقــم ‪ 34/11400‬وتاريــخ ‪1434/6/4‬ه ـ‬\n      ‫واملكونــة مــن لفتــن وقــد جــرى منــي االطــاع علــى هــذه الالئحــة‬\n      ‫ولــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه وللبيــان جــرى‬\n      ‫حتريــره وحــرر يف ‪1434/6/4‬ه ـ وبــاهلل التوفيــق وصلــى اهلل تعالــى‬\n                            ‫وســلم علــى نبينــا محمــد وآلــه وصحبــه أجمعــن‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد افتتحــت اجللســة الرابعــة يف الســاعة احلاديــة‬\n      ‫عشــر صباحـ ًا مــن يــوم األحــد ‪1434/8/28‬ه ـ وفيهــا حضــر املدعــي‬\n      ‫العــام ‪ ...‬وحضــور حلضــوره املدعــى عليــه ‪ ... /‬املدونــة هويتــه ســابق ًا‬\n      ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف اجلزائيــة املتخصصــة‬\n      ‫مبوجــب خطــاب رئيســها رقــم ‪ 34/1010‬وتاريــخ ‪1434/8/15‬ه ـ‬\n\n\n‫‪201‬‬\n\f‫وبرفقهــا القــرار الصــادر مــن الدائــرة الثالثيــة األولــى مبحكمــة‬\n‫االســتئناف اجلزائيــة املتخصصــة برقــم ‪/1/364‬م‪1434/08/14/‬‬\n‫وتاريخ ‪1434/8/14‬هـ املتضمن انه بدراسة القرار وصورة ضبطه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ أن مــا حكــم بــه‬\n‫فضيلتــه مــن عــدم ثبــوت مــا نســبه إليــه املدعــي العــام مــن اســتجابته‬\n‫للتعــاون مــع املخابــرات العراقيــة ضــد اململكــة يف وقــت تتخــذ‬\n‫موقف ـ ًا معادي ـ ًا لهــا يف غيــر محلــه فاملدعــى عليــه أقــر بذلــك يف‬\n‫املجلــس الشــرعي وتضمنــه إقــراره املصــدق شــرع ًا فعلــى فضيلتــه‬\n‫إعــادة التأمــل واثبــات إدانتــه بذلــك ومعاقبتــه علــى فعلــه نظــر ًا‬\n‫خلطــورة هــذا اجلــرم وعــدم التهــاون مــع مثــل ذلــك ملــا يفضــي إلــى‬\n‫الضــرر الكبيــر بالبــاد والعبــاد ملالحظــة مــا ذكــر ورصــد مــا‬\n‫يجد يف الضبط وصورته والقرار وسجله واهلل املوفق وصلى اهلل‬\n‫علــى نبينــا محمــد والــه وصحبــه وســلم‪ .‬ـ ـ ـ ـ ـ عليــه أجيــب أصحــاب‬\n‫الفضيلــة مشــايخنا وفقهــم اهلل بأنــه ثبــت لــدي وعــد املدعــى عليــه‬\n‫‪ ...‬بــان يقــوم مبــا طلبــت منــه االســتخبارات العراقيــة يف حــال‬\n‫إخراجــه مــن الســجن ونظــرا إلــى أنــه لــم يحصــل منــه ذلــك فانــه‬\n‫قرينــة علــى صحــة مــا دفــع بــه مــن أن قصــده هــو اخلــروج مــن‬\n‫الســجن فقــط دون الوفــاء مبــا اســتعد لهــم بــه ومبــا أن املدعــى‬\n‫عليــه لــم يخبــر اجلهــات املختصــة يف هــذا البلــد بعــد دخولــه مبــا‬\n‫حصــل فقــد قــررت تعزيــره علــى ذلــك بســجنه ســتة أشــهر اعتبــار ًا‬\n‫مــن تاريــخ إيقافــه يف ‪1432/11/3‬ه ـ وبذلــك حكمــت ‪ .‬وبعــرض‬\n‫احلكــم علــى املدعــى العــام واملدعــى عليــه وإفهامهــا بحقهمــا يف‬\n‫االســتئناف قــرر املدعــى عليــه قناعتــه باحلكــم وقــرر املدعــي العــام‬\n\n\n                                                                                 ‫‪202‬‬\n\f      ‫عــدم قناعتــه باحلكــم وطلــب رفــع معاملتــه حملكمــة االســتئناف‬\n      ‫اجلزائيــة املتخصصــة بــدون الئحــة اعتراضيــة وأمــرت بإحلــاق مــا‬\n      ‫ذكــر بالضبــط يف القــرار ثــم بعــث كامــل أوراق املعاملــة إلــى‬\n      ‫محكمــة االســتئناف اجلزائيــة املتخصصــة إلجــراء الــازم حســب‬\n      ‫التعليمــات‪ .‬وبــه ختمــت اجللســة يف متــام الســاعة احلاديــة عشــر‬\n      ‫والنصــف وعليــه جــرى التوقيــع وحــرر يف ‪1434/8/28‬ه ـ وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل تعالــى وبــارك وســلم علــى نبينــا محمــد وآلــه‬\n                                                                ‫وصحبــه أجمعــن‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد افتتحــت اجللســة اخلامســة يــوم الثالثــاء‬\n      ‫املوافــق ‪1435/03/21‬ه ـ الســاعة الثامنــة والنصــف وقــد عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف بخطــاب رئيســها رقــم ‪341480‬‬\n      ‫وتاريــخ ‪1434/10/11‬ه ـ مرفق ـ ًا بــه قــرار الدائــرة الثالثيــة األولــى‬\n      ‫برقــم ‪/2/364‬ص‪ 1434/10/7/‬وتاريــخ ‪1434/08/14‬ه ـ املتضمــن‬\n      ‫بعــد املقدمــة مــا نصــه ‪( :‬املصادقــة علــى احلكــم بعــد اإلجــراء‬\n      ‫األخيــر واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد ‪ ،‬عضــو‬\n      ‫د ‪ ...‬ختمــه وتوقيعــه وعضــو ‪ ...‬ورئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه)‬\n      ‫وللبيــان جــرى حتريــره‪ ،‬مــع التنبيــه أنــه لــم يتــم ضبطهــا يف حــن‬\n      ‫ورودهــا مــن محكمــة االســتئناف ســهو ًا مــن املوظــف املختــص وبــه‬\n      ‫ختمت اجللسة يف متام الساعة الثامنة وأربعني دقيقة وباهلل التوفيق‬\n          ‫وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1435/03/21‬ه‪.‬‬\n\n\n\n\n‫‪203‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":191,"source_page_end":203,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4f78e8d6422284599d95e860f13644dfe72e0ca98a1abe5233b067927b87d6cd","normalized_text_hash":"e8574ca8f2ac5d204241c7b4b99ed142f0ca43ea68a9bd57dbd598c9b5e30134","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p191-11-34-1"},{"id":"a05b5281-188e-585e-8aae-b1828992cf12","document_type":"judgment","category":"judicial","subcategory":"general","title":"إخال باألمن الوطني -الدعوة للخروج على ولي األمر بالتحريض على التظاهر -جرائم معلوماتية -إنتاج ما من شأنه املساس بالنظام العام -تقرير طبي متخصص -عدم قبول الرجوع عن اإلقرار فيما يوجب التعزير -إدانة.","document_number":"3244413","case_number":"475","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/3/11","year":"1434","subject":"إخال باألمن الوطني -الدعوة للخروج على ولي األمر بالتحريض على التظاهر -جرائم معلوماتية -إنتاج ما من شأنه املساس بالنظام العام -تقرير طبي متخصص -عدم قبول الرجوع عن اإلقرار فيما يوجب التعزير -إدانة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3244413 :‬تاريخه‪1432/3/11 :‬هـ‬\n                          ‫رقم الدعوى‪475 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪/350‬خ‪ 1/3/‬وتاريخ ‪1432/6/1 :‬هـ‬\n\n\n‫إخــال باألمــن الوطنــي‪ -‬الدعــوة للخــروج علــى ولــي األمــر بالتحريــض‬\n‫علــى التظاهــر‪ -‬جرائــم معلوماتيــة‪ -‬إنتــاج مــا مــن شــأنه املســاس‬\n‫بالنظــام العــام‪ -‬تقريــر طبــي متخصــص ‪ -‬عــدم قبــول الرجــوع عــن‬\n                                  ‫اإلقــرار فيمــا يوجــب التعزيــر‪ -‬إدانــة‪.‬‬\n\n\n\n\n‫‪ -1‬قــول اهلل تعالــى‪(( :‬وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى‬\n                                                                        ‫اإلثــم والعــدوان))‪.‬‬\n          ‫‪ -2‬قول اهلل تعالى‪(( :‬واعتصموا بحبل اهلل جميعا وال تفرقوا))‪.‬‬\n‫‪ -3‬قــول اهلل تعالــى‪(( :‬وأن هــذا صراطــي مســتقيما فاتبعــوه وال تتبعــوا‬\n                             ‫الســبل فتفــرق بكــم عــن ســبيله ذلكــم وصاكــم بــه))‪.‬‬\n‫‪ -4‬قــول النبــي صلــى اهلل عليــه وسـ ّلم‪( :‬ال َي ْج ِنــي جــانٍ ِإال َع َلــى َن ْف ِسـهِ)‬\n                                        ‫رواه أحمــد وابــن ماجــه والترمــذي وصححــه‪.‬‬\n‫‪ -5‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬الديــن النصيحــة قالــوا ملــن‬\n‫يارســول اهلل قــال هلل ولكتابــه ولرســوله وألئمــة املســلمني وعامتهــم) رواه‬\n                                                          ‫الترمــذي وأبــو داود والنســائي‪.‬‬\n‫‪ -6‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬فــإن يتركوهــم ومــا أرادوا‬\n        ‫هلكــوا جميع ـ ًا وإن أخــذوا علــى أيديهــم جنــوا وجنــوا جميع ـ ًا)‪.‬‬\n‫‪ -7‬قــول النبــي صلــى اهلل عليــه وس ـ ّلم‪( :‬مــن أتاكــم وأمركــم جميعــا‬\n‫علــى رجــل واحــد يريــد أن يشــق عصاكــم ويفــرق جماعتكــم فاقتلــوه‬\n                                                                                                ‫‪204‬‬\n\f                                                                                           ‫)‪ .‬رواه مســلم‪.‬‬\n      ‫ماع ـ َة قِ يـ َـد ِش ـ ْب ٍر‬\n                                ‫اجل َ‬    ‫(مـ ْـن فَ ـ َ‬\n                                    ‫ـار َق َ‬         ‫‪ -8‬قــول النبــي صلــى اهلل عليــه وس ـ ّلم‪َ :‬‬\n                                     ‫ا ِم مِ ـ ْـن ُع ْنقِ ـهِ)‪ .‬رواه أبــو داود‪.‬‬   ‫فَ َقــدْ َخ َلـ َـع ِرب َْق ـ َة ْ‬\n                                                                                ‫اإلس ـ َ‬\n      ‫‪ -9‬قــول النبــي صلــى اهلل عليــه وسـ ّلم‪( :‬مــن أعطــى إمامــا صفقــة يــده ‪،‬‬\n      ‫وثمــرة فــؤاده ‪ ،‬فليطعــه مــا اســتطاع ‪ ،‬فــإن جــاء آخــر ينازعــه ‪ ،‬فاضربــوا‬\n                                                                            ‫عنــق اآلخــر )‪ .‬رواه مســلم‪.‬‬\n      ‫‪ -10‬قــول النبــي صلــى اهلل عليــه وسـ ّلم‪( :‬مــن خــرج علــى الطاعــة وفــارق‬\n                                      ‫اجلماعــة ومــات ‪ ،‬مــات ميتــة جاهليــة)‪ .‬رواه مســلم‪.‬‬\n      ‫‪ -11‬قــول الطحــاوي‪« :‬وال نــرى اخلــروج علــى أئمتنــا ووالة أمورنــا وإن‬\n      ‫جــاروا وال ندعــو عليهــم وال ننــزع يــد ًا مــن طاعتهــم»‪ .‬شــرح الطحاويــة‬\n                                                                                                   ‫(ص ‪.)333‬‬\n      ‫ـريفة ينبغــي التفطــن لهــا‬         ‫‪ -12‬قــول ابــن تيميــة‪ُ « )1( :‬هنــا َقاعِ ــد ٌة شـ َ‬\n      ‫وهــى‪ :‬أن مــا عــاد مــن الذنــوب بإضــرار الغيــر يف دينــه ودنيــاه‪ ،‬فعقوبتنــا‬\n      ‫لــه يف الدنيــا أكبــر»‪ .‬الفتــاوى (‪ )2( ،)373/10‬وقولــه‪« :‬فهؤالء يعاقبون‬\n      ‫ال وتأديب ًا بقدر ما يراه الوالي ‪..‬إلخ»‪ .‬السياســة الشــرعية‬                        ‫تعزير ًا وتنكي ً‬\n      ‫(ص‪91‬ـ‪ )3( ،)92‬وقولــه‪« :‬ومنهــا عقوبــات غيــر مقــدرة تســمى التعزيــر‬\n      ‫‪..‬إلــخ»‪ .‬احلســبة (ص‪ )4( ،)50‬وقولــه‪ « :‬وهــذا أصــل متفــق عليــه‪ :‬أن‬\n      ‫كل مــن فعــل محرمــا‪ ،‬أو تــرك واجب ـ ًا اســتحق العقوبــة ‪..‬إلــخ» (‪)5‬‬\n      ‫وقولــه‪« :‬وعلــى أن الواجــب حتصيــل املصالــح وتكميلهــا‪ ،‬وتعطيــل‬\n      ‫املفاســد وتقليلهــا ‪..‬إلــخ» (‪ )6‬وقولــه‪« :‬العقوبــات شــرعت داعيــة إلــى‬\n      ‫فعــل الواجبــات‪ ،‬وتــرك احملرمــات»‪ )7( ،‬وقولــه‪« :‬الشــر واملعصيــة‪ :‬ينبغــي‬\n      ‫حســم مادتــه‪ ،‬وســد ذريعتــه‪ ،‬ودفــع مــا يفضــي إليــه»‪ .‬السياســة الشــرعية‬\n                                                                                           ‫(‪.) 36،40،111‬‬\n\n\n‫‪205‬‬\n\f‫‪ -13‬قــول الشــاطبي‪« :‬النظــر يف مــآالت األفعــال معتبــر مقصــود شــرع ًا‬\n                                              ‫‪ ..‬إلــخ»‪ .‬املوافقــات (‪.)194/4‬‬\n              ‫‪ -14‬املواد (‪ )4‬و(‪ )195-194‬من نظام اإلجراءات اجلزائية‪.‬‬\n                   ‫‪ -15‬املادة (‪ )6‬من نظام مكافحة اجلرائم املعلوماتية‪.‬‬\n\n\n\n\n‫أقــام املدعــي العــام دعــوى جزائيــة عامــة ضــد املدعــى عليــه طلــب فيهــا‬\n‫إدانتــه بالدعــوة للخــروج علــى ولــي األمــر بالتحريــض علــى التظاهــر‬\n‫وإنتــاج مــا مــن شــأنه املســاس بالنظــام العــام‪ ،‬وطلــب احلكــم عليــه‬\n‫بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة السادســة مــن نظــام‬\n‫مكافحــة جرائــم املعلوماتيــة وبعقوبــة تعزيريــة ومبصــادرة اجلــوال‬\n‫املوصــوف يف الدعــوى‪ -‬قبــض علــى املدعــى عليــه إثــر بــاغ تقــدم بــه‬\n‫أحــد املواطنــن بتلقيــه رســائل علــى هاتفــه اجلــوال مــن رقــم جــوال عائــد‬\n‫للمدعــى عليــه تتضمــن حتريــض علــى املظاهــرات‪ ،‬وبتفتيشــه ضبــط‬\n‫معــه جهــاز جــوال بداخلــه شــريحة حتمــل ذات الرقــم الصــادرة منــه تلــك‬\n‫الرســائل‪ ،‬وباســتجوابه أقــر بأنــه قــام بإرســال عــدة رســائل متضمنــة‬\n‫الدعــوة حلضــور املظاهــرات‪ -‬مبواجهتــه بالدعــوى أمــام احملكمــة‬\n‫أنكــر جميــع مــا أســنده إليــه املدعــي العــام ســوى عائديــة رقــم الشــريحة‬\n‫لــه ودفــع بأنــه معــاق بصري ـ ًا ومريــض نفســياً‪ -‬املدعــى عليــه لــه إقــرار‬\n‫مصــدق شــرع ًا ورجوعــه عــن بعــض مــا ورد فيــه غيــر مقبــول ألن الرجــوع‬\n‫عــن اإلقــرار فيمــا موجبــه التعزيــر ال يقبــل‪ -‬قضــت احملكمــة بإدانــة‬\n‫املدعــى عليــه مبــا نســب إليــه وقــررت لقــاء ذلــك ســجنه ملــدة ســنة وســتة‬\n‫أشــهر ومصــادرة جهــاز اجلــوال والشــريحة املضبوطــة معــه وأخــذ التعهــد‬\n\n                                                                                     ‫‪206‬‬\n\f      ‫عليــه بعــدم العــودة ملثــل مــا بــدر منــه‪ -‬عــارض املدعي العــام واملدعى عليه‬\n       ‫علــى احلكــم‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .................‬القاضــي باحملكمــة‬\n      ‫اجلزائيــة املتخصصــة و بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة املتخصصــة برقــم ‪ 475‬وتاريــخ ‪1433/7/13‬ه ـ‬\n      ‫واملقيــدة بهــذه احملكمــة برقــم ‪ 33/7733‬وتاريــخ ‪1433/7/13‬ه ـ‬\n      ‫اخلاصــة بدعــوى املدعــي العــام ‪ ....................‬ضــد ‪ ....................‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )..................‬ويف يــوم االثنــن‬\n      ‫املوافق‪1433/8/26‬هـ افتتحت اجللســة يف متام الســاعة العاشــرة صباحا‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ .....................‬ولــم يحضــر املدعــى عليــه‬\n      ‫‪ .......................‬وال مــن ينــوب عنــه ولــم تردنــا أي إفــادة رســمية مــن اجلهــة‬\n      ‫املختصــة حيــال ســبب عــدم إحضــاره علمــا انــه قــد طلــب إحضــاره‬\n      ‫مبوجــب خطابنــا املوجــه لفضيلــة رئيــس هــذه احملكمــة برقــم ‪338966‬‬\n      ‫وتاريــخ ‪1433/8/19‬ه ـ وقــدم املدعــي العــام دعــواه ضــد املدعــى عليــه‬\n      ‫يف هــذه القضيــة محــرره وهــذا نصهــا ( بصفتــي مدعي ـ ًا عام ـ ًا بهيئــة‬\n      ‫التحقيــق واالدعــاء العــام أدعــي علــى ‪ ، ............/‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )...........‬مولــود بتاريــخ ‪1398/10/17‬ه ـ‬\n      ‫‪ ،‬مســتوى التعليــم ‪ :‬ثانــوي ‪ ،‬موظــف حكومــي ‪ ،‬موقــوف مــن تاريــخ‬\n      ‫القبــض عليــه يف ‪1432/5/22‬ه ـ مبوجــب أمــر مذكــرة توقيــف رقــم‬\n      ‫(‪ )4506‬وتاريــخ ‪1432/5/27‬هــ‪ .‬بارتكابــه اجلرائــم التاليــة ‪-1 -:‬‬\n      ‫الدعــوة للخــروج علــى ولــي األمــر بالتحريــض علــى التظاهــر مخالف ـ ًا‬\n\n‫‪207‬‬\n\f‫تعليمــات ولــي األمــر وبيــان هيئــة كبــار العلمــاء الصــادر بتاريــخ‬\n‫‪1432/4/1‬ه ـ ‪-2 .‬إنتــاج مــا مــن شــأنه املســاس بالنظــام العــام وذلــك مــن‬\n‫خــال قيامــه بالدعــوة حلضــور املظاهــرات املســماة بثــورة حنــن عبــر‬\n‫إرســال رســائل نصيــة ألرقــام عشــوائية مــن هاتفــه اجلــوال ‪ .‬حيــث قبــض‬\n‫عليــه إثــر بــاغ تقــدم بــه املواطــن‪ ............../‬متضمنـ ًا تلقيــه رســائل علــى‬\n‫هاتفــه اجلــوال رقــم (‪ )...............‬مــن الرقــم (‪ )..................‬تتضمــن‬\n‫حتريــض علــى املظاهــرات كــون اجلــوال الصــادرة منــه تلــك الرســائل‬\n‫عائــد ًا للمذكــور‪ .‬وبتفتيشــه ضبــط معــه جهــاز جــوال نــوع ‪ ....‬بداخلــه‬\n‫شــريحة ‪ ....‬حتمــل ذات الرقــم الصــادرة منــه تلــك الرســائل ‪.‬وباســتجوابه‬\n‫أقــر بــأن الشــريحة ذات الرقــم (‪ )....................‬تعــود لــه وأنــه املســتخدم‬\n‫الفعلــي لهــا ‪ ،‬كمــا أقــر بأنــه قــام بإرســال خمــس أو ســت رســائل تقريبـ ًا‬\n‫ألرقــام عشــوائية مخزنــة بجهــازه وليســت علــى الشــريحة حتــى ال يعرفــه‬\n‫الشــخص الــذي أرســلت لــه الرســالة متضمنــة الدعوة حلضــور املظاهرات‬\n‫املســماة بثــورة حنــن يف ‪1432/4/6‬ه ـ مــن جوالــه ‪ ....‬ذي الرقــم‬\n‫التسلســلي (‪ )351893/01/335256/5‬وأن ذلــك كان نظــر ًا لظروفــه‬\n‫املاديــة والصحيــة وصــدق إقــراره بذلــك شــرع ًا ‪ .‬وقــد انتهــى التحقيــق‬\n‫إلــى توجيــه االتهــام لــه مبــا أســند إليــه لألدلــة والقرائــن التاليــة ‪-:‬‬\n‫‪-1‬إقــراره املصــدق شــرع ًا املنــوه عنــه املــدون مبلــف التحقيــق لفــه رقــم‬\n‫(‪ )4‬صفحــة رقــم (‪ -2 . )5‬محضــر القبــض والتفتيــش املرفــق باملعاملــة ‪.‬‬\n‫‪ -3‬مــا جــاء يف أقوالــه بالتحقيــق املرفقــة باملعاملــة ‪ .‬وحيــث إن مــا أقــدم‬\n‫عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم‬\n‫ومعاقــب عليــه شــرع ًا ومجــرم نظام ـ ًا وموجــب مــن موجبــات التعازيــر ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور يعتبــر مــن قبيــل الدعــم للتنظيــم‬\n\n\n                                                                                          ‫‪208‬‬\n\f      ‫الــذي يتزعمــه املــارق‪ ....‬والــذي يهــدف إلــى مناهضــه الدولــة وهــدم نظــام‬\n      ‫احلكــم وتأليــب املواطنــن علــى الدولــة وإثــارة الفتنــة مــن خــال احلــث‬\n      ‫علــى املشــاركة يف املظاهــرات واالعتصامــات عبــر إرســال رســائل مــن‬\n      ‫جوالــه إلــى العديــد مــن األرقــام العشــوائية ويعــد خروجـ ًا علــى ولــي األمــر‬\n      ‫واســتنقاص ًا لواليتــه ومخالــف ملــا أمــر اهلل بــه مــن الطاعــة الواجبــة يف‬\n      ‫قول ــه تعالــى ( يأيهــا الذيــن آمنــوا أطيعــوا اهلل وأطيعــوا الرســول وأولــي‬\n      ‫األمــر منكــم )[ النســاء ‪ :‬جــزء مــن اآليــة ‪ ،]59‬وقــال النبــي صلــى اهلل‬\n      ‫عليــه وســلم ‪( :‬مــن خــرج عــن الطاعــة وفــارق اجلماعــة ومــات فميتتــه ميتــة‬\n      ‫جاهليــة)) رواه مســلم يف صحيحــة ‪ ،‬وقــال النبــي صلــى اهلل عليــه وســلم‬\n      ‫‪( :‬عليــك بالســمع والطاعــة يف عســرك ويســرك ومنشــطك ومكرهــك)‬\n      ‫أخرجــه مســلم ‪ ،‬وقــال النبــي صلــى اهلل عليــه وســلم ‪( :‬الســلطان ظــل‬\n      ‫اهلل يف األرض مــن أكرمــه أكرمــه اهلل ومــن أهانــه أهانــه اهلل) وقــال‬\n      ‫ســهل بــن عبــداهلل التســتري ‪( :‬ال يــزال النــاس بخيــر ما عظموا الســلطان‬\n      ‫والعلمــاء فــإن عظمــوا هذيــن أصلــح اهلل دنياهــم وأخراهــم وإن اســتخفوا‬\n      ‫بهذيــن أفســد اهلل دنياهــم وأخراهــم) ‪ ،‬كمــا أن املشــاركة يف‬\n      ‫املظاهــرات واالعتصامــات والدعــوة إليهــا وتأليــب املواطنــن ضد الدولة‬\n      ‫مــن الفــن املؤديــة للتفــرق واالختــاف املخالــف ملــا أمــر اهلل بــه يف قولــه‬\n      ‫قــال تعالــى ( واعتصمــوا بحبــل اهلل جميعــا وال تفرقــوا) [آل عمــران‪:‬‬\n      ‫جــزء مــن اآليــة ] ‪ ،‬قــال ابــن مســعود (حبــل اهلل اجلماعــة)‪ ،‬وقــد نــص‬\n      ‫بيــان هيئــة كبــار العلمــاء يف دورتــه التاســعة واخلمســن بتاريــخ‬\n      ‫‪1424/6/11‬ه ـ علــى (وجــوب لــزوم اجلماعــة والتحذيــر مــن دعــاة‬\n      ‫الضاللــة والفتنــة والفرقــة الذيــن ظهــروا يف هــذه األزمــان قلبــوا علــى‬\n      ‫املســلمني أمرهــم وحرضوهــم علــى معصيــة والة أمرهــم واخلــروج عليهــم‬\n\n\n‫‪209‬‬\n\f‫وذلــك مــن أعظــم احملرمــات) ‪ ،‬وقــال النبــي صلــى اهلل عليــه وســلم ‪:‬‬\n‫((إنــه ســتكون هنــات وهنــات فمــن أراد أن يفــرق أمــر هــذه األمــة وهــي‬\n‫جميــع فاضربــوه بالســيف كائنـ ًا مــن كان)) رواه مســلم ‪ ،‬قــال ســماحة‬\n‫(أمــا مــا يقــوم بــه ســعد الفقيــه‬\n                                   ‫الشــيخ عبدالعزيــز بــن بــاز رحمــه اهلل َّ‬\n‫ومحمــد املســعري وأشــباههما مــن ناشــري الدعــوات الفاســدة الضالــة‬\n‫فهــذا بــا شــك شــر عظيــم وهــم دعــاة شــر عظيــم وفســاد كبيــر‬\n‫والواجــب احلــذر مــن نشــراتهم والقضــاء عليهــم وعــدم التعــاون معهــم يف‬\n‫أي شــيء يدعــو إلــى الفســاد والشــر والباطــل والفــن ‪ ...‬كمــا أن‬\n‫املظاهــرات النســائية والرجاليــة مــن أســباب الفــن والشــرور والتعــدي‬\n‫علــى بعــض النــاس بغيــر حــق) كمــا نصــت املــادة الثانيــة عشــر مــن‬\n‫النظــام األساســي للحكــم علــى (تعزيــز الوحــدة الوطنيــة واجــب ومتنــع‬\n‫الدولــة كل مــا يــؤدي للفرقــة والفتنــة واالنقســام) ‪ -‬وبالتالــي فــإن مــا‬\n‫قــام بــه يعــد مــن اإلثــارة املنهــي عنهــا قــال اإلمــام الشــوكاني (فــإذا دعــا‬\n‫رجــل إلــى التثبيــط أو اإلثــارة فــإن لولــي األمــر إيقــاع العقوبــة املتالئمــة‬\n‫مــع جرمــه مــن ضــرب أو حبــس أو نفــي أو غيــر ذلــك الن تثبيــط ولــي‬\n‫األمــر وإثــارة الرعيــة عليــه مــن أعظــم مقدمــات اخلــروج ‪ ،‬واخلــروج مــن‬\n‫أشــنع اجلرائــم وأبشــعها فــكان مــا يفضــي إليــه كذلــك) كل ذلــك‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا وموجــب مــن موجبــات التعازيــر ‪ ،‬لــذا‬\n‫فأننــي أطلــب اآلتــي‪ -1 -:‬إثبــات مــا أســند إليــه ‪ -2 .‬احلكــم عليــه‬\n‫بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة السادســة مــن نظــام‬\n‫مكافحــة جرائــم املعلوماتيــة ‪ -3 .‬احلكــم عليــه بعقوبــة تعزيريــة زاجــرة‬\n‫لــه ورادعــة لغيــره ‪ -4 .‬مصــادرة اجلــوال ذي الرقــم التسلســلي‬\n‫(‪ )351893/01/335256/5‬وفقـ ًا للمــادة الثالثــة عشــر مــن النظــام ذاته‬\n\n\n                                                                                          ‫‪210‬‬\n\f      ‫املشــار إليــه ‪ ).‬هــذه دعــواي ثــم رفعــت اجللســة للكتابــة للجهــة املختصــة‬\n      ‫إلحضــار املدعــى عليــه لعــرض دعــوى املدعــي العــام عليــه وذلــك إلــى يــوم‬\n      ‫الثالثــاء املوافــق ‪1433/10/10‬ه ـ الســاعة التاســعة صباحــا ومت قفــل‬\n      ‫هــذه اجللســة يف متــام الســاعة احلاديــة عشــرة صباحــا واهلل املوفــق وصلــى‬\n      ‫اهلل و ســلم علــى نبينــا محمــد وعلــى آلــه وصحبــة أجمعــن حــرر يف‬\n      ‫‪1433/8/26‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .........‬القاضــي‬\n      ‫باحملكمــة اجلزائيــة املتخصصــة ويف يــوم الثالثــاء املوافــق‬\n      ‫‪1433/10/10‬ه ـ افتتحــت اجللســة يف متــام الســاعة التاســعة صباح ـ ًا‬\n      ‫وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه‬\n      ‫ولــم تردنــا أي إفــادة رســمية مــن اجلهــة املختصــة حيــال ســبب عــدم‬\n      ‫إحضــاره علمــا أنــه قــد طلــب إحضــاره مبوجــب خطابنــا املوجــه لفضيلــة‬\n      ‫رئيــس هــذه احملكمــة برقــم ‪ 33/9509‬وتاريــخ ‪1433/9/12‬ه ـ ورفعــت‬\n      ‫اجللســة للكتابــة للجهــة املختصــة إلحضــار املدعــى عليــه لعــرض دعــوى‬\n      ‫املدعــي العــام عليــه وذلــك إلــى يــوم االثنــن املوافــق ‪1433/10/23‬ه ـ‬\n      ‫الســاعة احلاديــة عشــر والنصــف صباح ـ ًا ومت قفــل هــذه اجللســة يف متــام‬\n      ‫الســاعة العاشــرة صباح ـ ًا واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1433/10/10‬ه ـ احلمــد هلل‬\n      ‫وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة اجلزائيــة املتخصصــة ويف‬\n      ‫نفــس اليــوم الثالثــاء املوافــق ‪1433/10/10‬ه ـ ويف متــام الســاعة احلاديــة‬\n      ‫عشــر والنصــف حضــر املدعــي العــام واملدعــى عليــه‪ ....‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ....‬وجــرى عــرض دعــوى املدعــي العــام‬\n      ‫املدونــة يف اجللســة األولــى علــى املدعــى عليــه وجــرى تســليمه نســخة مــن‬\n      ‫الئحــة الدعــوى وســؤاله عــن جوابــه عنهــا بعــد أن مت إفهامــه مبــا تضمنتــه‬\n\n\n‫‪211‬‬\n\f‫املــادة الرابعــة مــن نظــام اإلجــراءات اجلزائيــة مــن أن لــه حــق االســتعانة‬\n‫بوكيــل أو محــام للدفــاع عنــه فــرد املدعــى عليــه بقولــه إن لــدي وكيــل‬\n‫شــرعي مبوجــب وكالــة شــرعية يدعــى ‪ ....‬وأطلــب إعطائــي مهلــة قريبــة‬\n‫إلعــداد جوابــي عــن الدعــوى وتقدميــه لكــم هكــذا أجــاب ثــم رفعــت‬\n‫اجللســة حتــى ورود إجابــة املدعــى عليــه عــن الدعــوى وذلــك إلــى يــوم‬\n‫الســبت املوافــق ‪1433/10/14‬ه ـ الســاعة احلاديــة عشــر صباح ـ ًا ومت‬\n‫قفــل هــذه اجللســة يف متــام الســاعة الثانيــة عشــر ظهــر ًا واهلل املوفق وصلى‬\n‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف‬\n‫‪1433/10/10‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي‬\n‫باحملكمــة اجلزائيــة املتخصصــة ويف يــوم الســبت املوافــق ‪10 /10‬‬\n‫‪1433/‬ه ـ افتتحــت اجللســة يف متــام الســاعة احلاديــة عشــرة صباحــا حضر‬\n‫املدعــي العــام واملدعــى عليــه واملدعــو ‪ ....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم بصفتــه وكيــا عــن املدعــى عليــه ‪ ......‬مبوجــب‬\n‫صــك الوكالــة الصــادر مــن كتابــة عــدل الطائــف الثانيــة برقــم‬\n‫‪37147‬وتاريــخ ‪1433/7/2‬ه ـ جلــد ‪ 5879‬وجــرى ســؤال املدعــى عليــه‬\n‫عــن جوابــه عــن الدعــوى فقــدم جوابــا هــذا نصــه ( إن مــا جــاء بــه املدعــي‬\n‫العــام يف الئحــة اتهامــه غيــر صحيــح وذلــك لآلتــي ‪ :‬أو ًال ‪ :‬قيــام املدعــي‬\n‫العــام بانتــزاع مــا يثبــت إدانتــي بــدون وجــه حــق وعــدم ضبــط أقوالــي‬\n‫كاملــة يف محضــر التحقيــق‪ .‬قــام املدعــي العــام بانتــزاع مــا يثبــت إدانتــي‬\n‫بــدون وجــه حــق حيــث قــام بتوجيــه ســؤال واحــد فقــط لــي هــل رقــم‬\n‫اجلــوال هــذا (‪ )...................‬خــاص بــك أم ال وقمــت باإلجابــة بنعــم هــذا‬\n‫اجلــوال خــاص بــي ‪ ،‬وأمــا مــا جــاء يف الئحــة اتهــام املدعــي العــام بأننــي‬\n‫قمــت بإرســال خمــس رســائل مــن هــذا اجلــوال إلــى أرقــام عشــوائية‬\n\n\n                                                                                       ‫‪212‬‬\n\f      ‫واعترفــت بذلــك فهــذا غيــر صحيــح ‪ ،‬وكانــت إجابتــي بخصــوص‬\n      ‫الرســائل املرســلة هــو إننــي ال اعلــم أي شــيء عــن هــذه الرســائل ومــن‬\n      ‫املمكــن أن تكــون هــذه الرســالة قــد أرســلت لــي بطريقــة عشــوائية‬\n      ‫وقــد قمــت بــدون قصــد بإرســالها إلــى أشــخاص آخريــن حيــث إننــي‬\n      ‫معــاق بصريــا ولــدي مــا يثبــت ذلــك وقمــت بتقدميــه إلــى املدعــي العــام أو‬\n      ‫قــام احــد األشــخاص بقصــد توريطــي وقــام باســتغالل اإلعاقــة البصريــة‬\n      ‫لــدي وقــام بإرســال هــذه الرســائل بهــدف توريطــي إال أن املدعــي العــام‬\n      ‫لــم يضبــط أقوالــي واعترافاتــي كاملــة وذلــك بهــدف توريطــي بــدون‬\n      ‫وجــه حــق ‪ .‬ثانيـاً‪ :‬عــدم التوصيــف الشــرعي الصحيــح للواقعــة ‪.‬حيــث أن‬\n      ‫املدعــي العــام لــم يقــم بتوصيــف الواقعــة الوصــف الشــرعي الصحيــح‬\n      ‫حيــث أن الوصــف الشــرعي الصحيــح للواقعــة هــو إرســال رســائل بطريق‬\n      ‫اخلطــأ ألشــخاص عشــوائيني حيــث أن املدعــي العــام لــم يقــدم أي إثبــات‬\n      ‫يثبــت القصــد اجلرمــي لــي أو أي تواصــل مــع املارق‪./‬ثالثـاً‪ :‬وجــود إعاقــة‬\n      ‫بصريــة لــدي متنعنــي مــن القراءة والكتابة ‪ .‬حيث انه مرفق لفضيلتكم‬\n      ‫مــا يثبــت وجــود إعاقــة بصريــا لــدي متنعنــي مــن القــراءة والكتابــة ممــا‬\n      ‫يثبــت لفضيلتكــم أن هــذه الرســائل املرســلة إذا أرســلتها مــن جوالــي‬\n      ‫فهــي أرســلت بــدون قصــد منــي وذلــك لوجــود إعاقــة بصريــا لــدي متنعنــي‬\n      ‫مــن معرفــة محتــوى هــذه الرســائل ممــا يثبــت عــدم توافــر أي قصــد‬\n      ‫جرمــي لــدي يف إرســال هــذه الرســائل ‪ .‬رابعـاً‪ :‬عــدم قيــام املدعــي العــام‬\n      ‫بإثبــات أي صلــة أو تواصــل بينــي وبــن املــارق ‪ ... .. /‬ويتمثــل ذلــك يف أن‬\n      ‫املدعــي العــام لــم يقــدم أي دليــل أو بينــة يثبــت بهــا كــم التهــم الــذي قــام‬\n      ‫بتوجيههــا لــي حيــث انــه لــم يســتند إال علــى اعتــراف غيــر صحيــح مت‬\n      ‫انتســابه لــي بــدون وجــه حــق وهــو إننــي قمــت بإرســال هــذه الرســائل وأنــا‬\n\n\n‫‪213‬‬\n\f‫علــى علــم مبحتواهــا ومــدى تأثيرهــا علــى اآلخريــن وهــذا غيــر صحيــح‬\n‫كمــا أن املدعــي العــام لــم يقــدم أي دليــل علــى وجــود تواصــل أو أي صلــة‬\n‫أو عالقــة بينــي وبــن املــارق ‪ ..... /‬أو أي جهــة مشــبوهة ‪.‬خامس ـ ًا ‪ :‬عــدم‬\n‫انطبــاق نظــام مكافحــة اجلرائــم املعلوماتيــة علــي املدعــى عليــه ‪.‬حيــث‬\n‫أن اجلرائــم املعلوماتيــة ال تثبــت إال بوجــود قصــد جرمــي باالختــراق او‬\n‫بالتعــدي ســواء كان االختــراق أو التعــدي كان للســرقة أو التخريــب أو‬\n‫اإلرهــاب أمــا بالنســبة لــي فــأن نظــام مكافحــة اجلرائــم املعلوماتيــة ال‬\n‫ينطبــق علــي وذلــك لعــدم اســتطاعة املدعــي العــام بتقــدمي أي دليــل أو‬\n‫بينــة تثبــت وجــود قصــد جرمــي لــدي يف إرســال هــذه الرســائل‪ .‬وعليــه ‪:‬‬\n‫نطلــب مــن فضيلتكــم احلكــم باآلتــي ‪ :‬أو ًال ‪ :‬صــرف النظــر عــن كافــة‬\n‫طلبــات املدعــي العــام جتاهــي ( املدعــى عليــه ‪.) ......... /‬ثاني ـ ًا ‪:‬إطــاق‬\n‫ســراحي وتبرئتــي ممــا نســب لــي ) أ ‪ .‬ه ـ وبعــرض جــواب املدعــى عليــه‬\n‫علــى املدعــي العــام أجــاب بقولــه الصحيــح مــا ورد يف الدعــوى وبينتــي‬\n‫علــى ذلــك األدلــة والقرائــن املشــار لهــا يف الئحــة الدعــوى هكــذا أجــاب‬\n‫وبالرجــوع ألوراق املعاملــة وجــدت اعتــراف املدعــى عليــه ‪ ....‬علــى‬\n‫الصحيفــة رقــم (‪ )5‬مــن ملــف التحقيــق املرفــق باملعاملــة لفــه رقــم (‪)4‬‬\n‫يتضمــن مــا نصــه ( أقــر أنــا املوقــوف‪ ..... .... /‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...............‬مصدرهــا الطائــف مــن مواليــد الطائــف‬\n‫لعــام ‪1398‬ه ـ وأحمــل شــهادة الثانويــة العامــة وأعمــل مبهنــة مأمــور‬\n‫اتصــاالت مبستشــفى ‪ ....‬بالطائــف وأســم والدتــي ‪..............‬ومتــزوج‬\n‫ولــدي ولــد بأننــي أعانــي مــن ضعف شــديد يف البصر ‪ .‬أقر بأن الشــريحة‬\n‫التــي رقمهــا ‪ ...........‬تعــود لــي وأنــا املســتخدم الفعلــي لهــا وقــد قمــت‬\n‫بشــرائها مــن ســوق اجلــواالت بشــارع ‪ .............‬أقــر أننــي قمــت بإرســال‬\n\n\n                                                                                      ‫‪214‬‬\n\f      ‫عــدد حوالــي خمــس أو ســت رســائل ألرقــام عشــوائية مخزنــه بجهــازي‬\n      ‫وليســت علــى الشــريحة حتــى ال يعرفنــي الشــخص الــذي أرســلت لــه تلــك‬\n      ‫الرســالة أقــر أن الرســائل كانــت تتضمــن الدعــوة حلضــور املظاهــرات‬\n      ‫التــي تســمى بثــورة حنــن يف ‪1432/4/6‬ه ـ أقــر أننــي غيــر راضــي عمــا‬\n      ‫قمــت بــه ولكــن لظــرويف املاديــة القاســية ووضعــي الصحــي وعــدم‬\n      ‫صــرف إعانــات لــي مــن مركــز التأهيــل الشــامل وكذلــك حرمانــي مــن‬\n      ‫وزارة الصحــة لبــدل طبيعــة عمــل وعــدم وضعــي علــى الدرجــة املســتحقة‬\n      ‫لــي نظامـ ًا جعلتنــي أتصــرف وأقــوم بذلــك حتــى تتعــرف اجلهــات املختصــة‬\n      ‫علــى وضعــي مــن جميــع النواحــي ألنــي ال أســتطيع احلصــول علــى مــا‬\n      ‫ذكرتــه بحكــم معاناتــي البصريــة وعــدم اســتجابة ندائــي مــن قبــل‬\n      ‫هــذه اجلهــات ‪ .‬أقــر أننــي بعــد أن أرســلت تلــك الرســائل لــم اســتخدم تلــك‬\n      ‫الشــريحة كمــا أنــه لــم يحرضنــي أي شــخص بالقيــام بذلــك ولــم أخبــر‬\n      ‫أي شــخص بذلــك وهــذا إقــراري أوقــع عليــه طوعـ ًا واختيــارا بعــد أن متــت‬\n      ‫كتابتــه مــن قبــل التحقيــق لعــدم قدرتــي علــى ذلــك ) أ ـ ه ـ ومصــادق‬\n      ‫عليــه شــرع ًا مــن احملكمــة اجلزئيــة بالطائــف وبعــرض االعتــراف املــدون‬\n      ‫أعــاه علــى املدعــى عليــه وســؤاله عنــه أجــاب بقولــه إن هــذا اعتــرايف‬\n      ‫ومــا ذكــر فيــه مــن أننــي أرســلت رســائل تتضمــن الدعــوة حلضــور‬\n      ‫املظاهــرات التــي تســمى ( ‪ ) ....‬فغيــر صحيــح وقــد اعترفــت بذلــك رغبــة‬\n      ‫يف اخلــروج مــن التوقيــف هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام‬\n      ‫واملدعــى عليــه هــل لــدى أحــد منهمــا يف إضافتــه فأجابــا بقولهمــا ليــس‬\n      ‫لدينــا مــا نرغــب يف إضافتــه هكــذا أجابــا ثــم رفعــت اجللســة للدراســة‬\n      ‫والتأمــل إلــى يــوم الثالثــاء املوافــق ‪1433/10/24‬ه ـ الســاعة الثانيــة‬\n      ‫عشــرة والنصــف ظهــرا ومت قفــل هــذه اجللســة يف متــام الســاعة الثانيــة‬\n\n\n‫‪215‬‬\n\f‫عشــرة والنصــف ظهــر ًا واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1433/10/10‬ه ـ احلمــد هلل وحــده‬\n‫وبعــد فلــدي أنــا ‪ ....‬القاضــي باحملكمــة اجلزائيــة املتخصصــة ويف يــوم‬\n‫الثالثــاء املوافــق ‪1433/10/24‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n‫الثانيــة عشــرة والنصــف ظهــر ًا وفيهــا حضــر املدعــي العــام ‪ ... ....‬واملدعى‬\n‫ا إننــي أعانــي مــن مــرض نفســي مــن‬   ‫عليــه ‪ .......‬وقــرر املدعــى عليــه قائـ ً‬\n‫قبــل القبــض علــي مبــدة وقــد راجعــت مستشــفى الصحــة النفســية‬\n‫بالطائــف عــدة مــرات وأعطونــي عــاج وال زلــت أعانــي مــن آثــار املــرض‬\n‫حتــى اآلن هكــذا قــرر لــذا وإلقــرار املدعــى عليــه أنــه يعانــي مــن مــرض‬\n‫نفســي فقــد قــررت الكتابــة للجهــة املختصــة لعــرض املدعــى عليــه علــى‬\n‫جلنــة طبيــة مختصــة للكشــف عليــه واإلفــادة هــل يعانــي مــن أمــراض‬\n‫نفســية وهــل لهــا تأثيــر علــى مســؤوليته اجلنائيــة أم ال ومــا مــدى ذلــك‬\n‫التأثيــر إن وجــد ورفعــت اجللســة لذلــك وحتــى ورود اإلفــادة إلــى يــوم‬\n‫االثنــن املوافــق ‪1433/11/29‬ه ـ الســاعة العاشــرة والنصــف صباح ـ ًا‬\n‫ومت قفــل هــذه اجللســة يف متــام الســاعة الواحــدة ظهــر ًا واهلل املوفــق وصلى‬\n‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف‬\n‫‪1433/10/24‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي‬\n‫باحملكمة اجلزائية املتخصصة ويف يوم االثنني املوافق ‪1433/11/29‬هـ‬\n‫افتتحــت اجللســة يف متــام الســاعة العاشــرة والنصــف صباحـ ًا وفيها حضر‬\n‫املدعــي العــام واملدعــى عليــه وقــد جــرى منــا الكتابــة للجهــة املختصــة‬\n‫لعــرض املدعــى عليــه علــى جلنــة طبيــة مختصــة للكشــف عليــه واإلفــادة‬\n‫هــل يعانــي مــن أمــراض نفســية وهــل لهــا تأثيــر علــى مســؤوليته اجلنائيــة‬\n‫أم ال مبوجــب اخلطــاب رقــم ‪ 33/10833‬وتاريــخ ‪1433/10/24‬ه ـ ولــم‬\n\n\n                                                                                         ‫‪216‬‬\n\f      ‫ا لقــد مت‬    ‫تردنــا أي إفــادة رســمية حتــى اآلن وقــرر املدعــى عليــه قائ ـ ً‬\n      ‫إرســالي ملستشــفى ‪ ....‬بالريــاض الثالثــاء املاضــي ومت إعطائــي موعــد‬\n      ‫للكشــف علــي يف نهايــة شــهر ذي احلجــة هكــذا قــرر لــذا وحتــى ورود‬\n      ‫اإلفــادة مــن اجلهــة املختصــة حيــال مــا مت طلبــه فقــد رفعــت اجللســة إلــى‬\n      ‫يــوم االثنــن املوافــق ‪1434/ 1/26‬ه ـ الســاعة التاســعة صباحـ ًا ومت قفــل‬\n      ‫هــذه اجللســة يف متــام احلاديــة عشــرة صباح ـ ًا وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪11 / 29‬‬\n      ‫‪1433/‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي باحملكمــة‬\n      ‫اجلزائيــة املتخصصــة ويف يــوم االثنــن املوافــق ‪1434/1/26‬ه ـ افتتحــت‬\n      ‫اجللســة يف متــام الســاعة التاســعة صباحـ ًا وفيهــا حضــر املدعــي العــام ‪....‬‬\n      ‫ووكيــل املدعــى عليــه ‪ ....‬ولــم يحضــر املدعــى عليــه ولــم تردنــا أي إفــادة‬\n      ‫رســمية مــن قبــل اجلهــة املختصــة حيــال طلــب الكشــف علــى املدعــى‬\n      ‫ا لقــد مت‬     ‫عليــه حتــى اآلن وقــرر وكيــل املدعــى عليــه احلاضــر قائ ـ ً‬\n      ‫اإلفــراج عــن موكلــي يف نهايــة شــهر ذي احلجــة مــن عــام ‪1433‬هـ هكذا‬\n      ‫قــرر لــذا وحتــى ورود اإلفــادة مــن اجلهــة املختصــة حيــال مــا مت طلبــه فقــد‬\n      ‫رفعــت اجللســة إلــى يــوم االثنــن املوافــق ‪1434/ 4/1‬ه ـ الســاعة العاشــرة‬\n      ‫صباح ـ ًا ومت قفــل هــذه اجللســة يف متــام الســاعة العاشــرة صباح ـ ًا وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آله وصحبــه أجمعني‬\n      ‫حــرر يف ‪1434/ 1 / 26‬ه ـ احلمــد اهلل وحــده وبعــد فلــدي أنــا‪...........‬‬\n      ‫القاضــي باحملكمــة اجلزائيــة املتخصصــة ويف يــوم االثنــن املوافــق‬\n      ‫‪1434/4/1‬ه ـ افتتحــت اجللســة يف متــام الســاعة العاشــرة صباحـ ًا وفيهــا‬\n      ‫حضــر املدعــي العــام واملدعــى عليــه ‪ ....‬ووكيــل املدعــى عليــه وقــد وردنا‬\n      ‫خطــاب مديــر شــعبه ســجن امللــز رقــم ‪ 0072243/11‬وتاريــخ‬\n\n\n‫‪217‬‬\n\f‫‪1434/3/2‬ه ـ واملقيــد بهــذه احملكمــة برقــم ‪ 34/4511‬وتاريــخ‬\n‫‪1434/3/3‬ه ـ وبرفقــه تقريــر طبــي صــادر مــن مجمــع األمــل للصحــة‬\n‫النفســية بالريــاض برقــم ‪ 0060921‬وتاريــخ ‪1434/2/30‬ه ـ ويتضمــن‬\n‫مــا نصــه ( االســم ‪ /‬العمــر ‪ 33/‬اجلنســية ‪ /‬ســعودي رقــم امللــف ‪......‬‬\n‫بعــرض املذكــور أعــاه علــى اللجنــة الطبيــة اليــوم األربعــاء بتاريــخ‬\n‫‪1433/12/29‬ه ـ وباالطــاع علــى ملفه لدينــا والتقارير الطبية الصادرة‬\n‫بحقــه وبأخــذ التاريــخ املرضــي مــن أخيــه وإجــراء املقابلــة النفســية‬\n‫وفحــص احلالــة العقليــة تبــن التالــي لــم يســبق أن راجــع لدينــا مــن قبــل‬\n‫وحســب تقريــر مستشــفى الصحــة النفســية بالطائــف رقــم ‪ ..........‬وتاريخ‬\n‫‪1434/1/14‬ه ـ أن املذكــور راجــع لديهــم مــرة واحــده بتاريــخ‬\n‫‪1423/4/17‬ه ـ وشــخصت احلالــة اكتئــاب نفســي وأفــاد املذكــور أنــه‬\n‫يعانــي مــن مشــاكل يف عينيــه (ميــاه بيضــاء انفصــال الشــبكية وارتفاع‬\n‫بســكر الــدم ) أدى إلــى تدنــي يف الرؤيــة وأفــاد أن االتهــام املنســوب غيــر‬\n‫صحيــح وأنــه لــم يرســل هــذه الرســائل ‪ .‬ومبناظرتــه اليــوم وجــد انــه‬\n‫هــادئ متعــاون كالمــه مترابــط مزاجــه معتــدل مدرك للزمــان واملكان‬\n‫واألشــخاص الوظائــف املعرفيــة ضمــن احلــدود الطبيعيــة حكمــه علــى‬\n‫األمــور جيــد ومســتبصر بحالتــه ‪ .‬التوصيــات تــرى اللجنــة الطبيــة أن‬\n‫املذكــور كان يعانــي مــن أعــراض قلــق واكتئــاب وحالتــه مســتقرة‬\n‫علــى العــاج املوصــوف لــه يف الوقــت الراهــن وحالتــه ليــس لهــا تأثيــر‬\n‫علــى مســؤليته اجلنائيــة ‪ .‬ومذيــل بتوقيــع أعضــاء اللجنــة د‪ ........... /‬و‬\n‫د‪ ............/‬و د‪ ).........../‬ا‪-‬ه ـ ومت إفهــام الطرفــن مبــا تضمنــه التقريــر‬\n‫الطبــي املذكــور وجــرى ســؤالهما هــل لــدى أحــد منهمــا مــا يرغــب يف‬\n‫إضافتــه فأجــاب كل واحــد منهمــا بقولــه ليــس لــدي مــا أرغــب يف‬\n\n\n                                                                                     ‫‪218‬‬\n\f      ‫إضافتــه هكــذا أجابــا ثــم رفعــت اجللســة للدراســة والتأمــل إلــى يــوم‬\n      ‫الثالثــاء املوافــق ‪1434/ 4/2‬ه ـ الســاعة العاشــرة صباحـ ًا ومت قفــل هــذه‬\n      ‫اجللســة يف متــام الســاعة العاشــرة والنصــف صباح ـ ًا وبــاهلل التوفيــق‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر‬\n      ‫يف ‪1434/ 4 / 1‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي‬\n      ‫باحملكمــة اجلزائيــة املتخصصــة ويف يــوم الثالثــاء املوافــق ‪1434/4/2‬هـ‬\n      ‫افتتحــت اجللســة يف متــام الســاعة العاشــرة صباحـ ًا وفيهــا حضــر املدعــي‬\n      ‫العــام ‪ ............‬واملدعــى عليــه ‪ ...............‬ووكيلــه ‪ ...............‬وقــد جــرى‬\n      ‫منــي الرجــوع ألوراق املعاملــة فوجــدت محضــر حجــز مضبــوط املرفــق‬\n      ‫باملعاملــة لفــه رقــم ‪ 24‬يتضمــن أن نــوع اجلــوال املضبــوط مــع املدعــى عليــه‬\n      ‫هــو ‪ ....‬لونــه ‪ ....‬يحمــل الرقــم التسلســلي ‪351893/01/335256/5‬‬\n      ‫ورقــم الشــريحة املضبوطــة معــه هــو ‪ .................‬موبايلــي وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه وســؤاله عنــه أجــاب بقولــة لقــد ضبــط معــي جــوال‬\n      ‫نــوع ‪ ....‬ولكنــي ال أعــرف رقمــه التسلســلي وأمــا الشــريحة فهــي التــي‬\n      ‫ضبطــت هكــذا أجــاب ثــم جــرى إفهــام الطرفــن بأنــه مت قفــل بــاب‬\n      ‫املرافعــة يف هــذه الدعــوى وبعــد تأمــل جميــع مــا ســبق ضبطــه وإلقــرار‬\n      ‫املدعــى عليــه بــأن اجلــوال رقــم ‪ .................‬يعــود لــه وألن إقــراره املصــدق‬\n      ‫شــرع ًا تضمــن أنــه هــو املســتخدم الفعلــي لــه وأنــه قــام بإرســال خمــس أو‬\n      ‫ســت رســائل تتضمــن الدعــوة حلضــور املظاهــرات التــي تســمى ( ‪) ....‬‬\n      ‫ألرقــام عشــوائية مخزنــة بجهــازه وليســت علــى الشــريحة لكــي ال يعرفه‬\n      ‫الشــخص الــذي أرســلت لــه تلــك الرســالة وأنــه فعــل ذلــك لظروفــه املاديــة‬\n      ‫القاســية ووضعــه الصحــي وعــدم وضعــه علــى الدرجــة املســتحقة لــه‬\n      ‫نظام ـ َا وعــدم صــرف طبيعــة عمــل لــه ومبــا أن رجــوع املدعــى عليــه عــن‬\n\n\n‫‪219‬‬\n\f‫بعــض مــا ورد يف اعترافــه املصــدق شــرع ًا ال يقبــل منــه ألن الرجــوع عــن‬\n‫اإلقــرار فيمــا موجبــه التعزيــر ال يقبــل كمــا صــرح بذلــك أهــل العلــم‬\n‫رحمهــم اهلل ألن التقريــر الطبــي الصــادر مــن مستشــفى األمــل لصحــة‬\n‫النفســية تضمــن أن حالــة املدعــى عليــه ليــس لهــا تأثيــر علــى مســؤوليته‬\n‫اجلنائيــة وألن مــا صــدر مــن املدعــى عليــه فيــه تعــاون علــى اإلثــم والعدوان‬\n‫وســعي لتفريــق األمــة وقــد قــال اهلل عــز وجــل (وتعاونــوا علــى البــر‬\n‫والتقــوى وال تعاونــوا علــى اإلثــم والعــدوان ) وقــال ســبحانه وتعالــى‬\n‫(واعتصمــوا بحبــل اهلل جميعــا وال تفرقــوا ) وقــال ســبحانه ( وأن هــذا‬\n‫صراطــي مســتقيما فاتبعــوه وال تتبعــوا الســبل فتفــرق بكــم عــن ســبيله‬\n‫ذلكــم وصاكــم بــه ) وقــد حــذر النبــي صلــى اهلل عليــه وســلم مــن دعــاة‬\n‫الفــن واخبــر أنهــم دعــاة علــى أبــواب جهنــم ونظــر ًا إلــى أن مــن أهــداف‬\n‫التنظيمــات املعاديــة لهــذه البــاد ـ ـ التــي ســعى املدعــى عليــه لتنفيــذ‬\n‫خططهــا بدعوتــه للمشــاركة يف املظاهــرات ـ ـ نقــض البيعــة واخلــروج‬\n‫علــى ولــي األمــر وإحــداث الفوضــى واالضطــراب وقــد قــال عليــه الصالة‬\n‫والســام( مــن أتاكــم وأمركــم جميعــا علــى رجــل واحــد يريــد أن يشــق‬\n‫عصاكــم ويفــرق جماعتكــم فاقتلــوه ) رواه مســلم وعــن َأبــي َذ ّر ـ ٍ رضي‬\n‫ـار َق‬\n   ‫اهلل عنــه ـ ـ قــال قــال َر ُســولُ اهلل صلــى اهلل عليــه وس ـلّم‪َ ( :‬مــنْ َفـ َ‬\n‫اإلسـا َِم مِ ــنْ ُع ْنقِ ـهِ) رواه أبــو داود ‪،‬‬\n                                             ‫َماعـ َة قِ يـ َـد ِشـ ْب ٍر َف َقــدْ َخ َلـ َـع ِر ْب َقـ َة ْ‬\n                                                                                                         ‫اجل َ‬\n‫وعــن أبــي ذر رضــي اهلل عنــه قــال ‪ :‬ســمعت رســول اهلل صلــى اهلل عليــه‬\n‫وســلم يقــول ‪ ( :‬مــن أعطــى إمامــا صفقــة يــده ‪ ،‬وثمــرة فــؤاده ‪ ،‬فليطعــه‬\n‫مــا اســتطاع ‪ ،‬فــإن جــاء آخــر ينازعــه ‪ ،‬فاضربــوا عنــق اآلخــر ) رواه‬\n‫مســلم ‪ ،‬كمــا أن اخلــروج علــى اإلمــام مــن أعظــم املنكــرات ومخالــف‬\n‫لعقيــدة أهــل الســنة واجلماعــة ألحاديــث كثيــرة منهــا ‪ :‬قولــه صلــى اهلل‬\n\n\n                                                                                                                 ‫‪220‬‬\n\f      ‫عليــه وســلم ‪ ( :‬مــن خــرج علــى الطاعــة وفــارق اجلماعــة ومــات ‪ ،‬مــات‬\n      ‫ميتــة جاهليــة ) رواه مســلم وأقــوال العلمــاء قدمي ـ ًا وحديث ـ ًا مشــهورة‬\n      ‫معروفــة ‪ ،‬قــال أبــو جعفــر الطحــاوي رحمــه اهلل ‪ ( :‬وال نــرى اخلــروج علــى‬\n      ‫أئمتنــا ووالة أمورنــا وإن جــاروا وال ندعــو عليهــم وال ننــزع يــد ًا مــن‬\n      ‫طاعتهــم ) شــرح الطحاويــة ص ‪ ،333‬وقــال ســماحة الشــيخ عبــد العزيــز‬\n      ‫بــن بــاز رحمــه اهلل ‪ ( :‬الواجــب علــى جميــع املســلمني يف هــذه اململكــة‬\n      ‫الســمع والطاعــة لــوالة األمــور باملعــروف كمــا دلــت على ذلــك األحاديث‬\n      ‫الصحيحــة الــواردة والثابتــة عــن النبــي صلــى اهلل عليــه وســلم ‪ ،‬وال يجــوز‬\n      ‫ألحــد أن ينــزع يــد ًا مــن طاعــة ا‪.‬ه ـ ) ‪ ،‬وقــال أيض ـ ًَا ‪ ( :‬ننصــح اجلميــع‬\n      ‫بوجــوب الســمع والطاعــة كمــا تقــدم واحلــذر مــن شــق العصــا واخلــروج‬\n      ‫علــى والة األمــور ‪ ،‬بــل هــذا مــن املنكــرات العظيمــة ‪ ،‬بــل هــذا ديــن‬\n      ‫اخلــوارج) ا‪ .‬ه ـ وقــد بــن العلمــاء حــال دعــاة الضــال وحــذروا منهــم ومــن‬\n      ‫منهجهــم واملدعــى عليــه ال يخفــى علــى مثلــه ذلــك جــاء يف قــرار مجلــس‬\n      ‫هيئــة كبــار العلمــاء يف الــدورة التاســعة واخلمســن املؤرخــة يف‬\n      ‫‪1424/6/24‬ه ـ مــا نصه(ويحــذر املجلــس مــن دعــاة الضاللــة والفتنــة‬\n      ‫والفرقــة الذيــن ظهــروا يف هــذه األزمــان فلبســوا علــى املســلمني أمرهــم‬\n      ‫وحرضوهــم علــى معصيــة والة أمورهــم واخلــروج عليهــم وذلــك مــن أعظــم‬\n      ‫احملرمــات أ‪.‬ه ـ وجــاء يف بيــان هيئــة كبــار العلمــاء بهــذه البــاد املؤرخ يف‬\n      ‫‪1432/4/1‬ه ـ مــا نصــه ( ومبــا أن اململكــة العربيــة الســعودية قائمــة‬\n      ‫علــى الكتــاب والســنة والبيعــة ولــزوم اجلماعــة والطاعــة فــإن اإلصــاح‬\n      ‫والنصيحــة فيهــا ال تكــون باملظاهــرات والوســائل التــي تثيــر الفــن‬\n      ‫وتفــرق اجلماعــة وهــذا مــا قــرره علمــاء هــذه البــاد قدمي ـ ًا وحديث ـ ًا مــن‬\n      ‫حترميهــا والتحذيــر منهــا )أ‪-‬ه ـ وقــال ســماحة الشــيخ عبدالعزيــز بــن بــاز‬\n\n\n‫‪221‬‬\n\f‫رحمــة اهلل ( فاألســلوب احلســن مــن أعظــم الوســائل لقبــول احلــق‬\n‫واألســلوب الســيئ العنيــف مــن أخطــر الوســائل يف رد احلــق وعــدم قبولــه‬\n‫أو إثــارة القالقــل والظلــم والعــدوان واملضاربــات ويلحــق بهــذا البــاب مــا‬\n‫يفعلــه بعــض النــاس مــن املظاهــرات التــي تســبب شــر ًا عظيم ـ ًا علــى‬\n‫الدعاة فاملســيرات يف الشــوارع والهتافات ليســت هي الطريق لإلصالح‬\n‫والدعــوة) أ ـ ـ ه ـ وألن مــا صــدر مــن املدعــى عليــه معصيــة متعديــة وقــد‬\n‫بــن شــيخ اإلســام ابــن تيميــة أن العقوبــة علــى الذنــب املتعــدي ضــرره‬\n‫أشــد حيــث قــال رحمــه اهلل يف الفتــاوى ‪ 373/10‬مــا نصــه ( هنــا قاعــدة‬\n‫شــريفة ينبغــي التفطــن لهــا وهــي أن مــا عــاد مــن الذنــوب بإضــرار الغيــر‬\n‫يف دينــه ودنيــاه فعقوبتنــا لــه يف الدنيــا اكبــر ) ا‪-‬ه ـ ولكــون املدعــى‬\n‫عليــه مكلفــا شــرع ًا مؤاخــذ ًا بأقوالــه وأفعالــه ولقــول النبــي صلــى اهلل‬\n‫عليــه وســلم ( ال يجنــي جــان إال علــى نفســه ) رواه أحمــد وابــن ماجــه‬\n‫والترمــذي وصححــه ‪ ،‬ومبــا أن مــا أقــدم عليــه املدعــى عليــه معصيــة‬\n‫موجبــة لتعزيــره ‪ ،‬قــال شــيخ اإلســام ابــن ـ ـ رحمــه اهلل ـ ـ ‪ ( :‬وهــذا أصــل‬\n‫متفــق عليــه ‪ :‬أن كل مــن فعــل محرمــا ‪ ،‬أو تــرك واجبـ ًا اســتحق العقوبــة‬\n‫‪ ،‬فــإن لــم تكــن مقــدرة بالشــرع كان تعزيــر ًا يجتهــد فيــه ولــي األمــر )‬\n‫ا ـ ـ ه ـ وقــال ـ ـ رحمــه اهلل ـ ـ ‪ ( :‬وعلــى أن الواجــب حتصيــل املصالــح‬\n‫وتكميلهــا ‪ ،‬وتعطيــل املفاســد وتقليلهــا فــإذا تعارضــت كان حتصيــل‬\n‫أعظــم املصلحتــن بتفويــت أدناهمــا ودفــع أعظــم املفســدتني مــع احتمــال‬\n‫أدناهمــا ‪ :‬هــو املشــروع ) ‪ ،‬وقــال ( العقوبــات شــرعت داعيــة إلــى فعــل‬\n‫الواجبــات ‪ ،‬وتــرك احملرمــات ) ‪ ،‬وقــال ـ ـ رحمــه اهلل ـ ـ ( الشــر واملعصيــة‬\n‫‪ :‬ينبغــي حســم مادتــه ‪ ،‬وســد ذريعتــه ‪ ،‬ودفــع مــا يفضــي إليــه ) ينظــر ص ـ‬\n‫‪ ، 36‬ص ـ ‪ ، 40‬ص ـ ‪ 111‬مــن كتابــه السياســة الشــرعية ‪ .‬وقــال شــيخ‬\n\n\n                                                                                      ‫‪222‬‬\n\f      ‫اإلســام ابــن تيميــة رحمــه اهلل فيمــن يفعــل املعاصــي التــي ليــس فيهــا‬\n      ‫ا وتأديب ـ ًا‬\n                  ‫حــد مقــدر وال كفــارة‪ ( :‬فهــؤالء يعاقبــون تعزيــر ًا وتنكي ـ ً‬\n      ‫بقــدر مــا يــراه الوالــي‪ ،‬علــى حســب كثــرة الذنــب يف النــاس وقلتــه‪،‬‬\n      ‫فــإذا كان كثيــر ًا زاد يف العقوبــة‪ ،‬بخــاف مــا إذا كان قليـاً‪ ،‬وعلــى‬\n      ‫حســب حــال املذنــب‪ ،‬فــإذا كان مــن املدمنــن علــى الفجــور زيــد يف‬\n      ‫عقوبتــه‪ ،‬بخــاف املقــل مــن ذلــك‪ ،‬وعلــى حســب كبر الذنــب وصغره‪....‬‬\n      ‫إلــى قولــه ‪ :‬وكذلــك قــد يعــزر باحلبــس وقــد يعــزر بالضــرب ) السياســة‬\n      ‫الشــرعية ص ‪ 91‬ـ ‪ ،92‬وقــال ـ رحمــه اهلل ـ ‪ ( :‬ومنهــا‪ :‬ـ أي العقوبــة ـ‬\n      ‫عقوبــات غيــر مقــدرة تســمى «التعزيــر» وتختلــف مقاديرهــا وصفاتهــا‬\n      ‫بحســب كبــر الذنــوب وصغرهــا وبحســب حــال املذنــب وبحســب حــال‬\n      ‫الذنــب يف قلتــه وكثرتــه )احلســبة ص‪ ،50‬وألن النظــر يف مآالت األفعال‬\n      ‫معتبــر شــرعا قــال اإلمــام الشــاطبي ‪ -‬رحمــه اهلل‪( -‬النظــر يف مــآالت‬\n      ‫األفعــال معتبــر مقصــود شــرعا ســواء كانــت األفعــال موافقــة أو مخالفة‬\n      ‫وذلــك أن املجتهــد ال يحكــم علــى فعــل مــن األفعــال الصــادرة عــن‬\n      ‫املكلفــن باإلقــدام أو باإلحجــام إال بعــد نظــرة إلــى مــا يــؤول إليــه ذلــك‬\n      ‫الفعــل مشــروعا ملصلحــة فيــه تســتجلب أو ملفســدة تــدرأ ) أ ـ ـ ه ـ ولقــول‬\n      ‫النبــي صلــى اهلل عليــه وســلم ‪ ( :‬الديــن النصيحــة هلل ولكتابــه ولرســوله‬\n      ‫وألئمــة املســلمني وعامتهــم ) رواه الترمــذي وأبــو داود والنســائي ‪ ،‬فــإن‬\n      ‫النصيحــة لديــن اهلل اإلســام وألئمــة املســلمني وعامتهــم يف احلكــم‬\n      ‫علــى مــن ارتكــب هــذه اجلرائــم مبــا يناســبه مــن تعزيــر يحصــل بــه حماية‬\n      ‫البــاد والعبــاد مــن شــره ‪ ،‬كمــا يحصــل بــه حفظــه واســتصالح حالــه ـ‬\n      ‫بــإذن اهلل ـ وملــا يف حديــث النعمــان بــن بشــير رضــي اهلل عنهمــا مرفوعـ ًا‬\n      ‫إلــى النبــي صلــى اهلل عليــه وســلم وفيــه ‪ ( :‬فــإن يتركوهــم ومــا أرادوا‬\n\n\n‫‪223‬‬\n\f‫هلكــوا جميع ـ ًا وإن أخــذوا علــى أيديهــم جنــوا وجنــوا جميع ـ ًا ) رواه‬\n‫البخــاري وألن مــا تضمنــه التقريــر الطبــي املذكــور مــن أن املدعــى عليــه‬\n‫كان يعانــي مــن أعــراض قلــق واكتئــاب مــن أســباب تخفيــف العقوبــة‬\n‫بحقــه لذلــك كلــه قــررت مــا يلــي ‪ :‬ـ ـ أو ًال ثبــت لــدي قيــام املدعــى عليــه‬\n‫بالدعــوة للخــروج علــى ولــي األمــر بالتحريــض علــى التظاهــر وإنتــاج‬\n‫وإرســال مــا مــن شــأنه املســاس بالنظــام العــام مــن خــال قيامــه بالدعــوة‬\n‫حلضــور املظاهــرات املســماة ( ‪ ) ....‬عبــر إرســاله عــدة رســائل نصيــه‬\n‫ألرقــام عشــوائية مــن هاتفــه اجلــوال وقــررت تعزيــره لقــاء ذلــك بســجنه‬\n‫ملــدة ســنه وســتة أشــهر تبــدأ مــن تاريــخ إيقافــه ‪1432/5/27‬ه ـ منها ســنه‬\n‫لقــاء إنتاجــه وإرســاله مــا مــن شــأنه املســاس بالنظــام العــام بنــاء علــى‬\n‫املــادة السادســة مــن نظــام مكافحــة اجلرائــم املعلوماتيــة ‪ .‬ثاني ـ ًا ‪ :‬ـ ـ‬\n‫مصــادرة جهــاز اجلــوال والشــريحة املضبوطــة مــع املدعــى عليــه إلقــراره‬\n‫باســتخدامها يف الدعــوة إلــى املظاهــرات ‪ .‬ثالث ـ ًا ‪ :‬ـ ـ أخــذ التعهــد علــى‬\n‫املدعــى عليــه بعــدم العــودة ملثــل مــا بــدر منــه ومبــا ذكــر حكمــت للحــق‬\n‫العــام وبعــرض احلكــم علــى الطرفــن وإفهامهمــا بــأن لهمــا احلــق يف‬\n‫االعتــراض علــى احلكــم ورفعــه حملكمــة االســتئناف اجلزائيــة‬\n‫ا أعتــرض علــى احلكــم‬         ‫املتخصصــة لتدقيقــه قــرر املدعــى العــام قائ ـ ً‬\n‫لعــدم كفايــة العقوبــة املقــررة فيــه ملــا ثبــت إدانــة املدعــى عليــه بــه مــن‬\n‫جرائــم وأطلــب تشــديد العقوبــة بأكثــر ممــا تقــرر يف هــذا احلكــم‬\n‫وأكتفــي بذلــك عــن تقــدمي الئحــة اعتراضيــة وقــرر املدعــي عليــه عــدم‬\n‫قناعتــه باحلكــم وأنــه يرغــب يف تقــدمي الئحــة اعتراضيــة فجــرى إفهامــه‬\n‫باملراجعــة يــوم الســبت املوافــق ‪1434/4/13‬ه ـ الســتالم نســخه من قرار‬\n‫احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا تبــدأ مــن التاريــخ‬\n\n\n                                                                                         ‫‪224‬‬\n\f      ‫املذكــور وأنــه إذا لــم يقــدم اعتراضــه خــال املــدة املذكــورة فإنه ســيتم‬\n      ‫رفــع احلكــم حملكمــة االســتئناف لتدقيقــه بنــاء علــى املــادة رقــم ‪-194‬‬\n      ‫‪ 195‬مــن نظــام اإلجــراءات اجلزائيــة ويف نفــس اجللســة قــرر املدعــى عليــه‬\n      ‫ا وكلــت املدعــو ‪ ....‬هــذا احلاضــر يف‬   ‫وهــو بحالتــه املعتبــرة شــرع ًا قائ ـ ً‬\n      ‫اســتالم نســخة احلكــم وتقــدمي االعتــراض عليــه والتوقيــع نيابــة عنــي يف‬\n      ‫ذلــك هكــذا قــرر وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                        ‫آله وصحبه أجمعني حرر يف ‪1434/4/2‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة اجلزائيــة‬\n      ‫املتخصصــة ويف يــوم األحــد املوافــق ‪1434/ 4/14‬ه ـ حضــر املدعــي‬\n      ‫العــام ‪ ....‬و‪................‬وكيــل املدعــى عليــه وللعلــم فإنــه قــد مت تنظيــم‬\n      ‫قــرار يف هــذه القضيــة برقــم‪ 0203028223088340021‬وتاريــخ‬\n      ‫‪1434/4/14‬ه ـ وألن توكيــل املدعــى عليــه لوكيلــه احلاضــر تضمــن‬\n      ‫توكيلــه لــه يف اســتالم نســخة قــرار احلكــم فقــد جــرى تســليم كل‬\n      ‫واحــد مــن املدعــي العــام ووكيــل املدعــى عليــه هــذا اليــوم نســخة مــن‬\n      ‫قــرار احلكــم املذكــور وجــرى إفهامهمــا بــأن مــدة االعتــراض علــى‬\n      ‫احلكــم تبــدأ مــن هــذا اليــوم األحــد املوافــق ‪1434/4/14‬ه ـ وأنهمــا إذا‬\n      ‫لــم يقدمــا اعتراضهمــا خــال املــدة املذكــورة فإنــه ســيتم رفــع احلكــم‬\n      ‫ـاء علــى املــادة رقــم ‪ 195-194‬مــن نظام‬  ‫حملكمــة االســتئناف لتدقيقــه بنـ ً‬\n      ‫اإلجــراءات اجلزائيــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                            ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434 /4/14‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ونظــر ًا النتهــاء مــدة االعتــراض علــى احلكــم‬\n      ‫دون ورود أي الئحــة اعتراضيــة مــن املدعــى العــام أو املدعــى عليــه ‪.....‬‬\n      ‫‪ ......‬وبنــاء علــى املــادة رقــم ‪ 195 - 194‬مــن نظــام اإلجــراءات اجلزائيــة‬\n\n\n‫‪225‬‬\n\f‫فقــد قــررت بعــث املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم ‪ .‬وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫حــرر بتاريــخ ‪1434/6/20‬ه ـ احلمــد هلل وحــده وبعــد وللعلــم فإنــه قــد‬\n‫وردت املعاملــة مــن محكمــة االســتئناف اجلزائيــة املتخصصــة باخلطــاب‬\n‫رقــم ‪ 34/1029‬وتاريــخ ‪1434/7/18‬ه ـ وبرفقهــا قــرار أصحــاب‬\n‫الفضيلــة قضــاة الدائــرة الثالثيــة االولــى مبحكمــة االســتئناف اجلزائيــة‬\n‫املتخصصــة رقــم ‪/1/355‬ص‪ 1434/7/17/‬وتاريــخ ‪1434/7/17‬ه ـ‬\n‫ويتضمــن مــا نصــه بعــد املقدمــة (وبدارســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم) أ ـ ـ ه ـ واهلل املوفــق وصلى‬\n ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم) حــرر يف ‪1434/8/6‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪226‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":204,"source_page_end":226,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b0e21740f455c082af20ce74f8997a40ff941efdb96372badb1e744fc67345de","normalized_text_hash":"4d7f7b3ffef61ddf8a615a6bdb601d3c89a4058d6adb186609ebbdb46f4534b4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p204-3244413"}]$archive_payload$::jsonb AS data)
